-- HotKey target database schema. This file is the only application-owned
-- database structure fact source and is safe to execute repeatedly on an empty
-- PostgreSQL 16+ database with pgvector installed.

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS users (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1,
    email varchar(254) NOT NULL,
    password_hash varchar(255) NOT NULL,
    display_name varchar(120) NOT NULL,
    role varchar(16) NOT NULL CHECK (role IN ('admin', 'analyst', 'editor', 'viewer')),
    status varchar(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
    last_login_at timestamptz,
    created_by bigint, updated_by bigint,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS users_active_email_uq ON users (lower(email)) WHERE deleted_at IS NULL;

-- Forward-compatible four-role expansion for existing databases. No user is
-- remapped automatically; administrators assign Analyst explicitly.
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check
    CHECK (role IN ('admin', 'analyst', 'editor', 'viewer'));

CREATE TABLE IF NOT EXISTS user_preferences (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1,
    user_id bigint NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
    timezone varchar(64) NOT NULL DEFAULT 'UTC', locale varchar(16) NOT NULL DEFAULT 'zh-CN',
    preferences jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by bigint, updated_by bigint,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS source_connections (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1,
    source_type varchar(24) NOT NULL CHECK (source_type IN ('rss','hacker_news','x','bing_grounding','bilibili','weibo','google_agent_search')),
    name varchar(120) NOT NULL, endpoint text NOT NULL,
    auth_type varchar(24) NOT NULL DEFAULT 'none' CHECK (auth_type IN ('none','api_key','oauth2','bearer')),
    credential_ref text CONSTRAINT source_connections_credential_ref_rule CHECK ((auth_type = 'none' AND credential_ref IS NULL) OR (auth_type <> 'none' AND (credential_ref ~ '^env:[A-Z_][A-Z0-9_]{0,127}$' OR credential_ref = 'managed:v1'))),
    config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object'), enabled boolean NOT NULL DEFAULT true,
    health_status varchar(16) NOT NULL DEFAULT 'unknown' CHECK (health_status IN ('unknown','healthy','degraded','unavailable')),
    terms_policy_url text,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
    body_storage_default_migrated_at timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS source_connections_active_name_uq ON source_connections(name) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS source_request_usage_ledgers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    resource_profile_version varchar(64) NOT NULL CHECK (resource_profile_version ~ '^[a-z][a-z0-9-]{0,62}-v[1-9][0-9]*$'),
    budget_day date NOT NULL,
    used bigint NOT NULL CHECK (used > 0),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, resource_profile_version, budget_day)
);
CREATE INDEX IF NOT EXISTS source_request_usage_ledgers_day_idx
    ON source_request_usage_ledgers(budget_day, source_connection_id);

CREATE TABLE IF NOT EXISTS source_credentials (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_connection_id bigint NOT NULL UNIQUE REFERENCES source_connections(id) ON DELETE CASCADE,
    key_version smallint NOT NULL CHECK (key_version = 1),
    nonce bytea NOT NULL CHECK (octet_length(nonce) = 12),
    ciphertext bytea NOT NULL CHECK (octet_length(ciphertext) >= 17 AND octet_length(ciphertext) <= 16400),
    created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS bilibili_webhook_receipts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_digest char(40) NOT NULL UNIQUE CHECK (event_digest ~ '^[0-9a-f]{40}$'),
    event_type varchar(32) NOT NULL CHECK (event_type IN ('verify_webhooks','deauthorize')),
    open_id varchar(128),
    status varchar(16) NOT NULL CHECK (status = 'processed'),
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz NOT NULL
);

ALTER TABLE source_connections
    ADD COLUMN IF NOT EXISTS body_storage_default_migrated_at timestamptz;
ALTER TABLE source_connections DROP CONSTRAINT IF EXISTS source_connections_source_type_check;
ALTER TABLE source_connections ADD CONSTRAINT source_connections_source_type_check
    CHECK (source_type IN ('rss','hacker_news','x','bing_grounding','bilibili','weibo','google_agent_search'));
ALTER TABLE source_connections DROP CONSTRAINT IF EXISTS source_connections_credential_ref_rule;
ALTER TABLE source_connections DROP CONSTRAINT IF EXISTS source_connections_credential_ref_check;
ALTER TABLE source_connections DROP CONSTRAINT IF EXISTS source_connections_check;
ALTER TABLE source_connections ADD CONSTRAINT source_connections_credential_ref_rule
    CHECK ((auth_type = 'none' AND credential_ref IS NULL)
        OR (auth_type <> 'none' AND (credential_ref ~ '^env:[A-Z_][A-Z0-9_]{0,127}$' OR credential_ref = 'managed:v1')));

CREATE TABLE IF NOT EXISTS metric_capability_profiles (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1,
    source_type varchar(24) NOT NULL CHECK (source_type IN ('rss','hacker_news','x','bilibili','weibo')),
    profile_version varchar(64) NOT NULL CHECK (profile_version ~ '^[a-z][a-z0-9._-]{0,63}$'),
    supports_views boolean NOT NULL DEFAULT false,
    supports_likes boolean NOT NULL DEFAULT false,
    supports_comments boolean NOT NULL DEFAULT false,
    supports_shares boolean NOT NULL DEFAULT false,
    independence_strategy varchar(24) NOT NULL CHECK (independence_strategy IN ('source_connection','author')),
    normalization_window_hours integer NOT NULL CHECK (normalization_window_hours BETWEEN 1 AND 720),
    credibility_weight numeric(4,3) NOT NULL CHECK (credibility_weight BETWEEN 0 AND 1),
    max_single_item_contribution numeric(5,2) NOT NULL CHECK (max_single_item_contribution > 0 AND max_single_item_contribution <= 100),
    status varchar(16) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')),
    published_at timestamptz,
    archived_at timestamptz,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_type, profile_version),
    CHECK ((supports_views OR supports_likes OR supports_comments OR supports_shares)
        AND ((status = 'draft' AND published_at IS NULL AND archived_at IS NULL)
          OR (status = 'published' AND published_at IS NOT NULL AND archived_at IS NULL)
          OR (status = 'archived' AND archived_at IS NOT NULL)))
);
CREATE UNIQUE INDEX IF NOT EXISTS metric_capability_profiles_one_published_uq
    ON metric_capability_profiles(source_type) WHERE status = 'published';
ALTER TABLE metric_capability_profiles DROP CONSTRAINT IF EXISTS metric_capability_profiles_source_type_check;
ALTER TABLE metric_capability_profiles ADD CONSTRAINT metric_capability_profiles_source_type_check
    CHECK (source_type IN ('rss','hacker_news','x','bilibili','weibo'));

CREATE OR REPLACE FUNCTION enforce_metric_capability_profile_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'metric_capability_profiles_append_only_check', MESSAGE = 'metric capability profiles cannot be deleted';
    END IF;
    IF OLD.status = 'archived' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'metric_capability_profiles_archived_immutable_check', MESSAGE = 'archived metric capability profiles cannot be changed';
    END IF;
    IF OLD.status = 'published' AND (
        NEW.source_type IS DISTINCT FROM OLD.source_type
        OR NEW.profile_version IS DISTINCT FROM OLD.profile_version
        OR NEW.supports_views IS DISTINCT FROM OLD.supports_views
        OR NEW.supports_likes IS DISTINCT FROM OLD.supports_likes
        OR NEW.supports_comments IS DISTINCT FROM OLD.supports_comments
        OR NEW.supports_shares IS DISTINCT FROM OLD.supports_shares
        OR NEW.independence_strategy IS DISTINCT FROM OLD.independence_strategy
        OR NEW.normalization_window_hours IS DISTINCT FROM OLD.normalization_window_hours
        OR NEW.credibility_weight IS DISTINCT FROM OLD.credibility_weight
        OR NEW.max_single_item_contribution IS DISTINCT FROM OLD.max_single_item_contribution
        OR NEW.published_at IS DISTINCT FROM OLD.published_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'metric_capability_profiles_published_immutable_check', MESSAGE = 'published metric capability configuration is immutable';
    END IF;
    IF OLD.status = 'published' AND NEW.status NOT IN ('published','archived') THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'metric_capability_profiles_transition_check', MESSAGE = 'published metric capability profile can only be archived';
    END IF;
    IF OLD.status = 'draft' AND NEW.status NOT IN ('draft','published','archived') THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'metric_capability_profiles_transition_check', MESSAGE = 'invalid metric capability profile transition';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS metric_capability_profiles_immutable ON metric_capability_profiles;
CREATE TRIGGER metric_capability_profiles_immutable
BEFORE UPDATE OR DELETE ON metric_capability_profiles
FOR EACH ROW EXECUTE FUNCTION enforce_metric_capability_profile_immutability();

CREATE TABLE IF NOT EXISTS monitors (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1,
    name varchar(120) NOT NULL, description text NOT NULL DEFAULT '',
    status varchar(16) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','paused','archived')),
    draft_config_version_id bigint, published_config_version_id bigint,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS monitors_active_name_uq ON monitors(lower(name)) WHERE deleted_at IS NULL AND status <> 'archived';

CREATE TABLE IF NOT EXISTS monitor_config_versions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1,
    monitor_id bigint NOT NULL REFERENCES monitors(id) ON DELETE RESTRICT,
    revision bigint NOT NULL CHECK (revision > 0),
    state varchar(16) NOT NULL DEFAULT 'draft' CHECK (state IN ('draft','published','superseded')),
    timezone varchar(64) NOT NULL DEFAULT 'UTC', languages text[] NOT NULL DEFAULT '{}', regions text[] NOT NULL DEFAULT '{}',
    collection_interval_seconds integer NOT NULL DEFAULT 300 CHECK (collection_interval_seconds BETWEEN 300 AND 86400 AND mod(collection_interval_seconds, 60) = 0),
    relevance_threshold numeric(5,2) NOT NULL DEFAULT 60 CHECK (relevance_threshold BETWEEN 60 AND 100),
    event_threshold numeric(5,2) NOT NULL DEFAULT 0 CHECK (event_threshold BETWEEN 0 AND 100),
    alert_min_heat numeric(5,2) NOT NULL DEFAULT 70 CHECK (alert_min_heat BETWEEN 0 AND 100),
    alert_min_momentum numeric(5,2) NOT NULL DEFAULT 55 CHECK (alert_min_momentum BETWEEN 0 AND 100),
    alert_min_breadth numeric(5,2) NOT NULL DEFAULT 25 CHECK (alert_min_breadth BETWEEN 0 AND 100),
    alert_warning_threshold numeric(5,2) NOT NULL DEFAULT 75 CHECK (alert_warning_threshold BETWEEN 0 AND 100),
    alert_critical_threshold numeric(5,2) NOT NULL DEFAULT 90 CHECK (alert_critical_threshold BETWEEN 0 AND 100 AND alert_critical_threshold >= alert_warning_threshold),
    alert_cooldown_minutes integer NOT NULL DEFAULT 60 CHECK (alert_cooldown_minutes BETWEEN 5 AND 1440),
    alert_email_enabled boolean NOT NULL DEFAULT false,
    alert_email_min_severity varchar(16) NOT NULL DEFAULT 'critical' CHECK (alert_email_min_severity IN ('warning','critical')),
    retention_days integer NOT NULL DEFAULT 180 CHECK (retention_days BETWEEN 1 AND 3650),
    config_hash char(64), published_at timestamptz,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (monitor_id, revision), UNIQUE (id, monitor_id),
    CHECK (state = 'draft' AND config_hash IS NULL AND published_at IS NULL OR state = ANY (ARRAY['published','superseded']) AND config_hash IS NOT NULL AND published_at IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS monitor_config_versions_one_draft_uq ON monitor_config_versions(monitor_id) WHERE state = 'draft';
CREATE UNIQUE INDEX IF NOT EXISTS monitor_config_versions_one_published_uq ON monitor_config_versions(monitor_id) WHERE state = 'published';

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'monitors_draft_config_version_fkey'
          AND conrelid = 'monitors'::regclass
    ) THEN
        ALTER TABLE monitors
            ADD CONSTRAINT monitors_draft_config_version_fkey
            FOREIGN KEY (draft_config_version_id) REFERENCES monitor_config_versions(id) ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'monitors_published_config_version_fkey'
          AND conrelid = 'monitors'::regclass
    ) THEN
        ALTER TABLE monitors
            ADD CONSTRAINT monitors_published_config_version_fkey
            FOREIGN KEY (published_config_version_id) REFERENCES monitor_config_versions(id) ON DELETE RESTRICT;
    END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS monitor_rules (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1, config_version_id bigint NOT NULL REFERENCES monitor_config_versions(id) ON DELETE RESTRICT,
    rule_type varchar(24) NOT NULL CHECK (rule_type IN ('keyword','phrase','exclude_keyword','domain','author','language','region','entity','regex')),
    operator varchar(16) NOT NULL CHECK (operator IN ('contains','equals','not_equals','matches')),
    value text NOT NULL, weight numeric(5,2) NOT NULL DEFAULT 0 CHECK (weight BETWEEN 0 AND 100),
    priority smallint NOT NULL DEFAULT 100, origin varchar(16) NOT NULL DEFAULT 'user' CHECK (origin IN ('user','ai','system')),
    approval_status varchar(16) NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('pending','approved','rejected')),
    enabled boolean NOT NULL DEFAULT true, created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS monitor_sources (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    config_version_id bigint NOT NULL REFERENCES monitor_config_versions(id) ON DELETE RESTRICT,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    query_override text CHECK (query_override IS NULL OR (octet_length(query_override) >= 1 AND octet_length(query_override) <= 2048)),
    query_signature char(64), source_options jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (source_options = '{}'::jsonb), priority smallint NOT NULL DEFAULT 100,
    enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (config_version_id, source_connection_id), UNIQUE (id, config_version_id)
);
CREATE INDEX IF NOT EXISTS monitor_sources_relevance_active_source_idx
    ON monitor_sources(source_connection_id, priority, config_version_id)
    WHERE enabled;
CREATE INDEX IF NOT EXISTS monitor_rules_relevance_approved_lexical_idx
    ON monitor_rules(lower(value), config_version_id, origin, weight DESC, id)
    WHERE enabled AND approval_status = 'approved'
      AND rule_type IN ('keyword','phrase','entity','exclude_keyword');

CREATE OR REPLACE FUNCTION enforce_monitor_config_version_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'draft' OR NEW.config_hash IS NOT NULL OR NEW.published_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_config_versions_initial_draft_check', MESSAGE = 'monitor configuration versions must be created as drafts';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        IF EXISTS (
            SELECT 1
            FROM monitors
            WHERE draft_config_version_id = OLD.id OR published_config_version_id = OLD.id
        ) THEN
            RETURN OLD;
        END IF;
        IF OLD.state <> 'draft' THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_config_versions_immutable', MESSAGE = 'published monitor configuration versions are immutable';
        END IF;
        RETURN OLD;
    END IF;

    IF OLD.state = 'superseded' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_config_versions_immutable', MESSAGE = 'superseded monitor configuration versions are immutable';
    END IF;
    IF OLD.state = 'published' THEN
        IF NEW.state <> 'superseded'
           OR NEW.monitor_id IS DISTINCT FROM OLD.monitor_id
           OR NEW.revision IS DISTINCT FROM OLD.revision
           OR NEW.version IS DISTINCT FROM OLD.version
           OR NEW.timezone IS DISTINCT FROM OLD.timezone
           OR NEW.languages IS DISTINCT FROM OLD.languages
           OR NEW.regions IS DISTINCT FROM OLD.regions
           OR NEW.collection_interval_seconds IS DISTINCT FROM OLD.collection_interval_seconds
           OR NEW.relevance_threshold IS DISTINCT FROM OLD.relevance_threshold
           OR NEW.event_threshold IS DISTINCT FROM OLD.event_threshold
           OR NEW.alert_min_heat IS DISTINCT FROM OLD.alert_min_heat
           OR NEW.alert_min_momentum IS DISTINCT FROM OLD.alert_min_momentum
           OR NEW.alert_min_breadth IS DISTINCT FROM OLD.alert_min_breadth
           OR NEW.alert_warning_threshold IS DISTINCT FROM OLD.alert_warning_threshold
           OR NEW.alert_critical_threshold IS DISTINCT FROM OLD.alert_critical_threshold
           OR NEW.alert_cooldown_minutes IS DISTINCT FROM OLD.alert_cooldown_minutes
           OR NEW.alert_email_enabled IS DISTINCT FROM OLD.alert_email_enabled
           OR NEW.alert_email_min_severity IS DISTINCT FROM OLD.alert_email_min_severity
           OR NEW.retention_days IS DISTINCT FROM OLD.retention_days
           OR NEW.config_hash IS DISTINCT FROM OLD.config_hash
           OR NEW.published_at IS DISTINCT FROM OLD.published_at
           OR NEW.created_by IS DISTINCT FROM OLD.created_by
           OR NEW.updated_by IS DISTINCT FROM OLD.updated_by
           OR NEW.created_at IS DISTINCT FROM OLD.created_at
           OR NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_config_versions_immutable', MESSAGE = 'published monitor configuration versions are immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.state = 'published' THEN
        IF NEW.config_hash IS NULL OR NEW.published_at IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_config_versions_publish_check', MESSAGE = 'published monitor configuration requires hash and timestamp';
        END IF;
    ELSIF NEW.state <> 'draft' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_config_versions_state_transition_check', MESSAGE = 'draft configuration must publish before superseding';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS monitor_config_versions_immutable ON monitor_config_versions;
CREATE TRIGGER monitor_config_versions_immutable
BEFORE INSERT OR UPDATE OR DELETE ON monitor_config_versions
FOR EACH ROW EXECUTE FUNCTION enforce_monitor_config_version_immutability();

CREATE OR REPLACE FUNCTION enforce_monitor_config_child_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    current_config_version_id bigint;
    current_state varchar(16);
    prior_state varchar(16);
BEGIN
    IF TG_OP = 'DELETE' THEN
        current_config_version_id := OLD.config_version_id;
    ELSE
        current_config_version_id := NEW.config_version_id;
    END IF;
    SELECT state INTO current_state FROM monitor_config_versions WHERE id = current_config_version_id;
    IF current_state IS DISTINCT FROM 'draft' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = TG_TABLE_NAME || '_immutable', MESSAGE = 'published monitor configuration children are immutable';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.config_version_id IS DISTINCT FROM OLD.config_version_id THEN
        SELECT state INTO prior_state FROM monitor_config_versions WHERE id = OLD.config_version_id;
        IF prior_state IS DISTINCT FROM 'draft' THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = TG_TABLE_NAME || '_immutable', MESSAGE = 'published monitor configuration children are immutable';
        END IF;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

DROP TRIGGER IF EXISTS monitor_rules_immutable ON monitor_rules;
CREATE TRIGGER monitor_rules_immutable
BEFORE INSERT OR UPDATE OR DELETE ON monitor_rules
FOR EACH ROW EXECUTE FUNCTION enforce_monitor_config_child_immutability();

DROP TRIGGER IF EXISTS monitor_sources_immutable ON monitor_sources;
CREATE TRIGGER monitor_sources_immutable
BEFORE INSERT OR UPDATE OR DELETE ON monitor_sources
FOR EACH ROW EXECUTE FUNCTION enforce_monitor_config_child_immutability();

CREATE OR REPLACE FUNCTION enforce_monitor_config_pointers()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    draft_state varchar(16);
    published_state varchar(16);
BEGIN
    IF NEW.draft_config_version_id IS NOT NULL THEN
        SELECT state INTO draft_state FROM monitor_config_versions WHERE id = NEW.draft_config_version_id AND monitor_id = NEW.id;
        IF draft_state IS DISTINCT FROM 'draft' THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitors_draft_config_version_owner_check', MESSAGE = 'draft configuration does not belong to monitor or is not a draft';
        END IF;
    END IF;
    IF NEW.published_config_version_id IS NOT NULL THEN
        SELECT state INTO published_state FROM monitor_config_versions WHERE id = NEW.published_config_version_id AND monitor_id = NEW.id;
        IF published_state IS DISTINCT FROM 'published' THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitors_published_config_version_owner_check', MESSAGE = 'published configuration does not belong to monitor or is not published';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS monitors_config_pointer_owner ON monitors;
CREATE TRIGGER monitors_config_pointer_owner
BEFORE INSERT OR UPDATE OF draft_config_version_id, published_config_version_id ON monitors
FOR EACH ROW EXECUTE FUNCTION enforce_monitor_config_pointers();

CREATE OR REPLACE FUNCTION validate_source_connection_configuration()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    config_key text;
BEGIN
    IF jsonb_typeof(NEW.config) <> 'object' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_config_object_check', MESSAGE = 'source config must be an object';
    END IF;
    FOR config_key IN SELECT jsonb_object_keys(NEW.config)
    LOOP
        IF config_key NOT IN ('allow_body_storage', 'requires_attribution', 'requires_deletion_sync', 'content_retention_days', 'metrics_retention_days', 'allowed_languages', 'allowed_regions', 'rate_limit_per_minute', 'request_timeout_seconds', 'max_pages_per_run', 'grounding_data_boundary_approved', 'bilibili_open_id', 'google_location', 'google_serving_config', 'hacker_news_mode', 'x_metric_refresh_enabled', 'x_metric_refresh_interval_minutes', 'x_metric_refresh_observation_hours', 'x_metric_refresh_max_posts_per_run', 'x_metric_refresh_daily_request_budget') THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_config_whitelist_check', MESSAGE = 'source config contains an unsupported key';
        END IF;
    END LOOP;
    IF (NEW.config ? 'allow_body_storage' AND jsonb_typeof(NEW.config->'allow_body_storage') <> 'boolean')
       OR (NEW.config ? 'requires_attribution' AND jsonb_typeof(NEW.config->'requires_attribution') <> 'boolean')
       OR (NEW.config ? 'requires_deletion_sync' AND jsonb_typeof(NEW.config->'requires_deletion_sync') <> 'boolean')
       OR (NEW.config ? 'grounding_data_boundary_approved' AND jsonb_typeof(NEW.config->'grounding_data_boundary_approved') <> 'boolean')
       OR (NEW.config ? 'x_metric_refresh_enabled' AND jsonb_typeof(NEW.config->'x_metric_refresh_enabled') <> 'boolean') THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_config_boolean_check', MESSAGE = 'source config boolean value is invalid';
    END IF;
    IF (NEW.config ? 'content_retention_days' AND (jsonb_typeof(NEW.config->'content_retention_days') <> 'number' OR (NEW.config->>'content_retention_days')::numeric <> trunc((NEW.config->>'content_retention_days')::numeric) OR (NEW.config->>'content_retention_days')::integer NOT BETWEEN 1 AND 3650))
       OR (NEW.config ? 'metrics_retention_days' AND (jsonb_typeof(NEW.config->'metrics_retention_days') <> 'number' OR (NEW.config->>'metrics_retention_days')::numeric <> trunc((NEW.config->>'metrics_retention_days')::numeric) OR (NEW.config->>'metrics_retention_days')::integer NOT BETWEEN 1 AND 3650))
       OR (NEW.config ? 'rate_limit_per_minute' AND (jsonb_typeof(NEW.config->'rate_limit_per_minute') <> 'number' OR (NEW.config->>'rate_limit_per_minute')::numeric <> trunc((NEW.config->>'rate_limit_per_minute')::numeric) OR (NEW.config->>'rate_limit_per_minute')::integer NOT BETWEEN 1 AND 600))
       OR (NEW.config ? 'request_timeout_seconds' AND (jsonb_typeof(NEW.config->'request_timeout_seconds') <> 'number' OR (NEW.config->>'request_timeout_seconds')::numeric <> trunc((NEW.config->>'request_timeout_seconds')::numeric) OR (NEW.config->>'request_timeout_seconds')::integer NOT BETWEEN 1 AND 120))
       OR (NEW.config ? 'max_pages_per_run' AND (jsonb_typeof(NEW.config->'max_pages_per_run') <> 'number' OR (NEW.config->>'max_pages_per_run')::numeric <> trunc((NEW.config->>'max_pages_per_run')::numeric) OR (NEW.config->>'max_pages_per_run')::integer NOT BETWEEN 1 AND 20))
       OR (NEW.config ? 'x_metric_refresh_interval_minutes' AND (jsonb_typeof(NEW.config->'x_metric_refresh_interval_minutes') <> 'number' OR (NEW.config->>'x_metric_refresh_interval_minutes')::numeric <> trunc((NEW.config->>'x_metric_refresh_interval_minutes')::numeric) OR (NEW.config->>'x_metric_refresh_interval_minutes')::integer NOT BETWEEN 15 AND 1440))
       OR (NEW.config ? 'x_metric_refresh_observation_hours' AND (jsonb_typeof(NEW.config->'x_metric_refresh_observation_hours') <> 'number' OR (NEW.config->>'x_metric_refresh_observation_hours')::numeric <> trunc((NEW.config->>'x_metric_refresh_observation_hours')::numeric) OR (NEW.config->>'x_metric_refresh_observation_hours')::integer NOT BETWEEN 1 AND 168))
       OR (NEW.config ? 'x_metric_refresh_max_posts_per_run' AND (jsonb_typeof(NEW.config->'x_metric_refresh_max_posts_per_run') <> 'number' OR (NEW.config->>'x_metric_refresh_max_posts_per_run')::numeric <> trunc((NEW.config->>'x_metric_refresh_max_posts_per_run')::numeric) OR (NEW.config->>'x_metric_refresh_max_posts_per_run')::integer NOT BETWEEN 1 AND 100))
       OR (NEW.config ? 'x_metric_refresh_daily_request_budget' AND (jsonb_typeof(NEW.config->'x_metric_refresh_daily_request_budget') <> 'number' OR (NEW.config->>'x_metric_refresh_daily_request_budget')::numeric <> trunc((NEW.config->>'x_metric_refresh_daily_request_budget')::numeric) OR (NEW.config->>'x_metric_refresh_daily_request_budget')::integer NOT BETWEEN 1 AND 1440)) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_config_integer_check', MESSAGE = 'source config integer value is invalid';
    END IF;
	IF NEW.source_type <> 'x' AND COALESCE((NEW.config->>'x_metric_refresh_enabled')::boolean, false) IS TRUE THEN
		RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_x_metric_refresh_source_check', MESSAGE = 'X metric refresh is available only for X sources';
	END IF;
    IF (NEW.config ? 'allowed_languages' AND (jsonb_typeof(NEW.config->'allowed_languages') <> 'array' OR jsonb_array_length(NEW.config->'allowed_languages') > 8 OR EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.config->'allowed_languages') AS value WHERE jsonb_typeof(value) <> 'string')))
       OR (NEW.config ? 'allowed_regions' AND (jsonb_typeof(NEW.config->'allowed_regions') <> 'array' OR jsonb_array_length(NEW.config->'allowed_regions') > 8 OR EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.config->'allowed_regions') AS value WHERE jsonb_typeof(value) <> 'string'))) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_config_array_check', MESSAGE = 'source config array value is invalid';
    END IF;
    IF NEW.config ? 'bilibili_open_id' AND COALESCE(NEW.config->>'bilibili_open_id', '') <> '' AND (jsonb_typeof(NEW.config->'bilibili_open_id') <> 'string' OR NEW.config->>'bilibili_open_id' !~ '^[A-Za-z0-9_-]{1,128}$') THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_bilibili_open_id_check', MESSAGE = 'Bilibili OpenID is invalid';
    END IF;
    IF (NEW.config ? 'google_location' AND jsonb_typeof(NEW.config->'google_location') <> 'string')
       OR (NEW.config ? 'google_serving_config' AND jsonb_typeof(NEW.config->'google_serving_config') <> 'string') THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_google_config_string_check', MESSAGE = 'Google Agent Search config string is invalid';
    END IF;
    IF NEW.config ? 'hacker_news_mode' AND (jsonb_typeof(NEW.config->'hacker_news_mode') <> 'string' OR NEW.config->>'hacker_news_mode' NOT IN ('new', 'top', 'best')) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_hacker_news_mode_check', MESSAGE = 'Hacker News mode must be new, top, or best';
    END IF;
    IF NEW.source_type = 'hacker_news' AND NEW.endpoint <> 'https://hacker-news.firebaseio.com/v0' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_hacker_news_endpoint_check', MESSAGE = 'hacker news endpoint must be the official endpoint';
    END IF;
    IF NEW.source_type = 'x' AND (NEW.endpoint <> 'https://api.x.com/2/tweets/search/recent' OR NEW.auth_type <> 'bearer' OR NEW.credential_ref IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_x_configuration_check', MESSAGE = 'X requires the official recent search endpoint and Bearer credential';
    END IF;
    IF NEW.source_type = 'bing_grounding' AND (NEW.endpoint !~ '^https://[A-Za-z0-9-]+\.services\.ai\.azure\.com/api/projects/[A-Za-z0-9][A-Za-z0-9._-]{0,127}/toolboxes/[A-Za-z0-9][A-Za-z0-9._-]{0,127}/versions/[A-Za-z0-9][A-Za-z0-9._-]{0,127}/mcp\?api-version=v1$' OR NEW.auth_type <> 'bearer' OR NEW.credential_ref IS NULL OR NEW.terms_policy_url IS NULL OR NEW.terms_policy_url !~ '^https://' OR COALESCE((NEW.config->>'allow_body_storage')::boolean, false) IS NOT TRUE OR COALESCE((NEW.config->>'requires_attribution')::boolean, false) IS NOT TRUE OR COALESCE((NEW.config->>'max_pages_per_run')::integer, 0) <> 1) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_bing_grounding_configuration_check', MESSAGE = 'Bing Grounding requires a versioned Foundry Toolbox MCP endpoint, Bearer credential, attribution, body storage, and one page';
    END IF;
    IF NEW.source_type = 'bilibili' AND (NEW.endpoint <> 'https://member.bilibili.com/arcopen/fn' OR NEW.auth_type <> 'oauth2' OR NEW.credential_ref IS NULL OR NEW.terms_policy_url <> 'https://openhome.bilibili.com/agreement/privacy-policy' OR COALESCE(NEW.config->>'bilibili_open_id', '') !~ '^[A-Za-z0-9_-]{1,128}$' OR COALESCE((NEW.config->>'allow_body_storage')::boolean, false) IS NOT TRUE OR COALESCE((NEW.config->>'requires_attribution')::boolean, false) IS NOT TRUE OR COALESCE((NEW.config->>'requires_deletion_sync')::boolean, false) IS NOT TRUE) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_bilibili_configuration_check', MESSAGE = 'Bilibili requires the official endpoint, OAuth2 credential, authorized OpenID, policy, attribution, body storage, and deletion sync';
    END IF;
	IF NEW.source_type = 'weibo' AND (NEW.endpoint <> 'https://open.weibo.com/cli/api' OR NEW.auth_type <> 'bearer' OR NEW.credential_ref IS NULL OR NEW.terms_policy_url <> 'https://open.weibo.com/wiki/%E5%BC%80%E5%8F%91%E8%80%85%E5%8D%8F%E8%AE%AE' OR COALESCE((NEW.config->>'allow_body_storage')::boolean, false) IS NOT TRUE OR COALESCE((NEW.config->>'requires_attribution')::boolean, false) IS NOT TRUE OR COALESCE((NEW.config->>'requires_deletion_sync')::boolean, false) IS NOT TRUE) THEN
		RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_weibo_configuration_check', MESSAGE = 'Weibo requires the official CLI API endpoint, Bearer credential, developer agreement, attribution, body storage, and deletion sync';
	END IF;
    IF NEW.source_type = 'google_agent_search' AND (
        NEW.auth_type <> 'bearer' OR NEW.credential_ref IS NULL OR NEW.terms_policy_url <> 'https://cloud.google.com/terms'
        OR COALESCE(NEW.config->>'google_location', '') NOT IN ('global','us','eu')
        OR COALESCE(NEW.config->>'google_serving_config', '') !~ '^projects/[a-z][a-z0-9-]{4,28}[a-z0-9]/locations/(global|us|eu)/collections/default_collection/dataStores/[A-Za-z0-9_-]{1,63}/servingConfigs/[A-Za-z0-9_-]{1,63}$'
        OR position('/locations/' || (NEW.config->>'google_location') || '/' IN COALESCE(NEW.config->>'google_serving_config', '')) = 0
        OR NEW.endpoint <> CASE NEW.config->>'google_location'
            WHEN 'global' THEN 'https://discoveryengine.googleapis.com'
            WHEN 'us' THEN 'https://us-discoveryengine.googleapis.com'
            WHEN 'eu' THEN 'https://eu-discoveryengine.googleapis.com'
            ELSE '' END
        OR COALESCE((NEW.config->>'allow_body_storage')::boolean, false) IS NOT TRUE
        OR COALESCE((NEW.config->>'requires_attribution')::boolean, false) IS NOT TRUE
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_google_agent_search_configuration_check', MESSAGE = 'Google Agent Search requires a matching official endpoint, location, ServingConfig, Bearer credential, terms, attribution, and snippet storage';
    END IF;
    IF TG_OP = 'UPDATE'
       AND (NEW.source_type IS DISTINCT FROM OLD.source_type OR NEW.endpoint IS DISTINCT FROM OLD.endpoint OR NEW.config IS DISTINCT FROM OLD.config)
       AND NOT (
           NEW.source_type IS NOT DISTINCT FROM OLD.source_type
           AND NEW.endpoint IS NOT DISTINCT FROM OLD.endpoint
           AND (NEW.config - 'allow_body_storage') IS NOT DISTINCT FROM (OLD.config - 'allow_body_storage')
           AND COALESCE(OLD.config->>'allow_body_storage', 'false') = 'false'
           AND NEW.config->>'allow_body_storage' = 'true'
       )
       AND EXISTS (
           SELECT 1
           FROM monitor_sources AS monitor_source
           JOIN monitor_config_versions AS config_version ON config_version.id = monitor_source.config_version_id
           WHERE monitor_source.source_connection_id = OLD.id AND config_version.state IN ('published', 'superseded')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_connections_semantic_immutable', MESSAGE = 'published monitor configuration source semantics are immutable';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS source_connections_semantic_immutable ON source_connections;
CREATE TRIGGER source_connections_semantic_immutable
BEFORE INSERT OR UPDATE OF source_type, endpoint, auth_type, credential_ref, config, terms_policy_url ON source_connections
FOR EACH ROW EXECUTE FUNCTION validate_source_connection_configuration();

-- Upgrade records created with the old implicit default once. The marker is
-- kept on the source row so later explicit operator choices are not
-- overwritten on every application restart.
UPDATE source_connections
SET config = jsonb_set(COALESCE(config, '{}'::jsonb), '{allow_body_storage}', 'true'::jsonb, true),
    body_storage_default_migrated_at = now(),
    updated_at = now()
WHERE body_storage_default_migrated_at IS NULL;

CREATE TABLE IF NOT EXISTS source_authors (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    external_id varchar(255) NOT NULL, handle varchar(255), display_name varchar(255), profile_url text,
    verified boolean NOT NULL DEFAULT false, follower_count bigint NOT NULL DEFAULT 0 CHECK (follower_count >= 0),
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, external_id)
);

CREATE TABLE IF NOT EXISTS contents (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    external_id varchar(512) NOT NULL, author_id bigint REFERENCES source_authors(id) ON DELETE SET NULL,
    content_type varchar(16) NOT NULL CHECK (content_type IN ('article','post','video','podcast','bulletin')),
    title text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', canonical_url text NOT NULL,
    language varchar(16) NOT NULL DEFAULT 'und', published_at timestamptz, fetched_at timestamptz NOT NULL,
    dedupe_key char(64) NOT NULL, duplicate_of_id bigint REFERENCES contents(id) ON DELETE SET NULL,
    view_count bigint CHECK (view_count >= 0), like_count bigint CHECK (like_count >= 0),
    comment_count bigint CHECK (comment_count >= 0), share_count bigint CHECK (share_count >= 0),
    extra_metrics jsonb NOT NULL DEFAULT '{}'::jsonb,
    content_status varchar(16) NOT NULL DEFAULT 'active' CHECK (content_status IN ('active','invalid','duplicate','deleted','expired')),
    manual_locked boolean NOT NULL DEFAULT false, created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
    dedupe_reason varchar(32), dedupe_version varchar(64),
    UNIQUE (source_connection_id, external_id),
    UNIQUE (id, source_connection_id),
    CHECK ((content_status = 'duplicate' AND duplicate_of_id IS NOT NULL AND dedupe_reason IS NOT NULL AND dedupe_version IS NOT NULL)
        OR (content_status <> 'duplicate' AND duplicate_of_id IS NULL AND dedupe_reason IS NULL AND dedupe_version IS NULL))
);
-- Existing installations originally required a publication timestamp and
-- therefore conflated an unknown source value with discovery time. Keep the
-- canonical schema forward-applicable without fabricating that source fact.
ALTER TABLE contents ALTER COLUMN published_at DROP NOT NULL;
CREATE INDEX IF NOT EXISTS contents_published_idx ON contents(published_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS contents_source_published_idx ON contents(source_connection_id, published_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS contents_dedupe_key_idx ON contents(dedupe_key);
CREATE INDEX IF NOT EXISTS contents_search_active_trgm_idx
  ON contents USING gin (lower(((title || ' ') || excerpt)) gin_trgm_ops)
  WHERE (content_status = 'active') AND deleted_at IS NULL;

-- Canonical Hotspot score used by radar ordering and notification projection.
CREATE OR REPLACE FUNCTION hotspot_heat_score(
    views bigint, likes bigint, comments bigint, shares bigint
) RETURNS numeric
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
    SELECT round(least(100::numeric,(
        ln(1 + coalesce(views, 0)) * 2 +
        ln(1 + coalesce(likes, 0)) * 10 +
        ln(1 + coalesce(comments, 0)) * 4 +
        ln(1 + coalesce(shares, 0)) * 6
    )::numeric), 1)
$$;

CREATE OR REPLACE FUNCTION hotspot_importance(
    views bigint, likes bigint, comments bigint, shares bigint
) RETURNS varchar
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
    SELECT CASE
        WHEN hotspot_heat_score(views,likes,comments,shares) >= 75 THEN 'urgent'
        WHEN hotspot_heat_score(views,likes,comments,shares) >= 50 THEN 'high'
        WHEN hotspot_heat_score(views,likes,comments,shares) >= 25 THEN 'medium'
        ELSE 'low'
    END
$$;

CREATE TABLE IF NOT EXISTS content_assets (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    asset_type varchar(24) NOT NULL CHECK (asset_type IN ('raw_response','html','text','image','screenshot','video_metadata','attachment')),
    object_key text NOT NULL UNIQUE, original_url text, mime_type varchar(255) NOT NULL, sha256 char(64) NOT NULL,
    size_bytes bigint NOT NULL DEFAULT 0 CHECK (size_bytes >= 0), captured_at timestamptz NOT NULL,
    object_status varchar(16) NOT NULL DEFAULT 'pending' CHECK (object_status IN ('pending','available','missing','delete_pending','deleted')),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS monitor_matches (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    monitor_id bigint NOT NULL, monitor_config_version_id bigint NOT NULL, content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    rule_score numeric(5,2) NOT NULL CHECK (rule_score BETWEEN 0 AND 100), semantic_score numeric(5,2) CHECK (semantic_score BETWEEN 0 AND 100),
    llm_score numeric(5,2) CHECK (llm_score BETWEEN 0 AND 100), final_score numeric(5,2) NOT NULL CHECK (final_score BETWEEN 0 AND 100),
    decision varchar(16) NOT NULL CHECK (decision IN ('accepted','rejected','review')), reason_codes text[] NOT NULL DEFAULT '{}',
    explanation jsonb NOT NULL DEFAULT '{}'::jsonb, algorithm_version varchar(64) NOT NULL, manual_locked boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    input_hash char(64) NOT NULL, scoring_version varchar(64) NOT NULL, recall_paths text[] NOT NULL DEFAULT '{}',
    degraded boolean NOT NULL DEFAULT false, decision_origin varchar(16) NOT NULL DEFAULT 'rule' CHECK (decision_origin IN ('rule','ai')),
    embedding_model_profile_id bigint,
    embedding_model_profile_version bigint, embedding_model_version varchar(64), review_ai_run_id bigint,
    FOREIGN KEY (monitor_config_version_id, monitor_id) REFERENCES monitor_config_versions(id, monitor_id) ON DELETE RESTRICT,
    CHECK (jsonb_typeof(explanation) = 'object'),
    CHECK (
      embedding_model_profile_id IS NULL AND embedding_model_profile_version IS NULL AND embedding_model_version IS NULL
      OR embedding_model_profile_id IS NOT NULL AND embedding_model_profile_version IS NOT NULL AND embedding_model_version IS NOT NULL
    ),
    UNIQUE (monitor_config_version_id, content_id, input_hash, scoring_version),
    UNIQUE (id, monitor_config_version_id, content_id)
);
CREATE INDEX IF NOT EXISTS monitor_matches_latest_snapshot_idx ON monitor_matches(monitor_config_version_id, content_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS monitor_matches_list_idx ON monitor_matches(monitor_id, decision, final_score DESC, id DESC);
CREATE INDEX IF NOT EXISTS monitor_matches_content_active_idx ON monitor_matches(content_id, monitor_id, final_score DESC, id DESC);
CREATE INDEX IF NOT EXISTS monitor_matches_monitor_content_latest_idx
  ON monitor_matches(monitor_id, content_id, created_at DESC, id DESC) INCLUDE (final_score, decision);

CREATE TABLE IF NOT EXISTS monitor_match_feedbacks (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    monitor_id bigint NOT NULL, monitor_config_version_id bigint NOT NULL,
    content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    monitor_match_id bigint, actor_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    feedback_type varchar(16) NOT NULL CHECK (feedback_type IN ('relevant','irrelevant','false_positive','false_negative')),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (monitor_config_version_id, monitor_id) REFERENCES monitor_config_versions(id, monitor_id) ON DELETE RESTRICT,
    FOREIGN KEY (monitor_match_id, monitor_config_version_id, content_id)
      REFERENCES monitor_matches(id, monitor_config_version_id, content_id) ON DELETE RESTRICT,
    UNIQUE (monitor_config_version_id, content_id, actor_user_id)
);

CREATE TABLE IF NOT EXISTS monitor_feedback_suggestions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    monitor_id bigint NOT NULL, monitor_config_version_id bigint NOT NULL,
    suggestion_type varchar(24) NOT NULL CHECK (suggestion_type IN ('add_term','add_exclude','add_entity')),
    value varchar(500) NOT NULL, support_count integer NOT NULL CHECK (support_count >= 2),
    status varchar(16) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
    reviewed_by_user_id bigint REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (monitor_config_version_id, monitor_id) REFERENCES monitor_config_versions(id, monitor_id) ON DELETE RESTRICT,
    CHECK (
      status = 'pending' AND reviewed_by_user_id IS NULL
      OR status IN ('approved','rejected') AND reviewed_by_user_id IS NOT NULL
    )
);
CREATE UNIQUE INDEX IF NOT EXISTS monitor_feedback_suggestions_pending_uq
  ON monitor_feedback_suggestions(monitor_config_version_id, suggestion_type, value) WHERE status = 'pending';

CREATE TABLE IF NOT EXISTS events (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    event_key varchar(96) NOT NULL UNIQUE, event_fingerprint char(64), fingerprint_version varchar(64), title_zh text NOT NULL,
    title_en text, summary text NOT NULL DEFAULT '', lifecycle_status varchar(16) NOT NULL CHECK (lifecycle_status IN ('detected','active','cooling','closed','merged','archived','rejected')),
    heat_score numeric(7,2) NOT NULL DEFAULT 0 CHECK (heat_score >= 0), trend_score numeric(7,2) NOT NULL DEFAULT 0,
    trend_status varchar(16) NOT NULL DEFAULT 'stable' CHECK (trend_status IN ('emerging','rising','stable','falling','dormant')),
    heat_window_hours smallint NOT NULL DEFAULT 24 CHECK (heat_window_hours IN (1,6,24)),
    heat_version varchar(64) NOT NULL DEFAULT 'heat-v1', heat_reason_codes text[] NOT NULL DEFAULT '{}',
    metric_capability_profile_set_hash char(64) NOT NULL DEFAULT repeat('0', 64), heat_calculated_at timestamptz,
    confidence numeric(5,2) NOT NULL DEFAULT 0 CHECK (confidence BETWEEN 0 AND 100), first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL,
    peak_at timestamptz, representative_content_id bigint REFERENCES contents(id) ON DELETE SET NULL,
    merged_into_id bigint REFERENCES events(id) ON DELETE SET NULL, manual_locked boolean NOT NULL DEFAULT false,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz
);
CREATE INDEX IF NOT EXISTS events_lifecycle_last_seen_idx ON events(lifecycle_status, last_seen_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS events_radar_last_seen_idx ON events(last_seen_at DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS events_search_active_trgm_idx
  ON events USING gin (lower(((((title_zh || ' ') || COALESCE(title_en, '')) || ' ') || summary)) gin_trgm_ops)
  WHERE deleted_at IS NULL;
ALTER TABLE events ADD COLUMN IF NOT EXISTS trend_status varchar(16) NOT NULL DEFAULT 'stable';
ALTER TABLE events ADD COLUMN IF NOT EXISTS heat_window_hours smallint NOT NULL DEFAULT 24;
ALTER TABLE events ADD COLUMN IF NOT EXISTS heat_version varchar(64) NOT NULL DEFAULT 'heat-v1';
ALTER TABLE events ADD COLUMN IF NOT EXISTS heat_reason_codes text[] NOT NULL DEFAULT '{}';
ALTER TABLE events ADD COLUMN IF NOT EXISTS metric_capability_profile_set_hash char(64) NOT NULL DEFAULT repeat('0', 64);
ALTER TABLE events ADD COLUMN IF NOT EXISTS heat_calculated_at timestamptz;
ALTER TABLE events DROP CONSTRAINT IF EXISTS events_trend_status_check;
ALTER TABLE events ADD CONSTRAINT events_trend_status_check CHECK (trend_status IN ('emerging','rising','stable','falling','dormant'));
ALTER TABLE events DROP CONSTRAINT IF EXISTS events_heat_window_hours_check;
ALTER TABLE events ADD CONSTRAINT events_heat_window_hours_check CHECK (heat_window_hours IN (1,6,24));

CREATE TABLE IF NOT EXISTS event_contents (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    event_id bigint NOT NULL REFERENCES events(id) ON DELETE CASCADE, content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    membership_score numeric(5,2) NOT NULL CHECK (membership_score BETWEEN 0 AND 100),
    evidence_role varchar(16) NOT NULL CHECK (evidence_role IN ('primary','supporting','context','duplicate')),
    is_representative boolean NOT NULL DEFAULT false, origin varchar(16) NOT NULL CHECK (origin IN ('rule','model','user')),
    manual_locked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (event_id, content_id)
);
CREATE INDEX IF NOT EXISTS event_contents_score_idx ON event_contents(event_id, membership_score DESC);
CREATE UNIQUE INDEX IF NOT EXISTS event_contents_one_current_event_uq
    ON event_contents(content_id) WHERE evidence_role <> 'duplicate';

-- PLAN-010 keeps every candidate decision, including rejected candidates and
-- new-event decisions. This is an append-only fact source for replays and
-- downstream reconciliation; it never stores raw content or provider text.
CREATE TABLE IF NOT EXISTS event_clustering_decisions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    candidate_event_id bigint REFERENCES events(id) ON DELETE SET NULL,
    candidate_event_key varchar(96) NOT NULL,
    clustering_version varchar(64) NOT NULL,
    feature_input_hash char(64) NOT NULL,
    channel varchar(16) NOT NULL CHECK (channel IN ('lexical','temporal','fingerprint','vector')),
    candidate_rank integer NOT NULL CHECK (candidate_rank >= 0 AND candidate_rank <= 50),
    entity_action_score numeric(5,2) NOT NULL CHECK (entity_action_score BETWEEN 0 AND 100),
    semantic_score numeric(5,2) NOT NULL CHECK (semantic_score BETWEEN 0 AND 100),
    temporal_score numeric(5,2) NOT NULL CHECK (temporal_score BETWEEN 0 AND 100),
    location_score numeric(5,2) NOT NULL CHECK (location_score BETWEEN 0 AND 100),
    source_context_score numeric(5,2) NOT NULL CHECK (source_context_score BETWEEN 0 AND 100),
    membership_score numeric(5,2) NOT NULL CHECK (membership_score BETWEEN 0 AND 100),
    decision varchar(16) NOT NULL CHECK (decision IN ('accepted','review','rejected','new_event')),
    decision_origin varchar(16) NOT NULL CHECK (decision_origin IN ('rule','model','user')),
    reason_codes text[] NOT NULL DEFAULT '{}',
    feature_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(feature_snapshot) = 'object'),
    evidence_content_ids bigint[] NOT NULL DEFAULT '{}',
    actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((decision = 'new_event' AND candidate_event_id IS NULL AND candidate_event_key = '__new_event__') OR (decision <> 'new_event' AND candidate_event_id IS NOT NULL AND candidate_event_key <> '__new_event__'))
);
CREATE UNIQUE INDEX IF NOT EXISTS event_clustering_decisions_idempotency_uq
    ON event_clustering_decisions(content_id, clustering_version, feature_input_hash, candidate_event_key);
CREATE INDEX IF NOT EXISTS event_clustering_decisions_content_idx
    ON event_clustering_decisions(content_id, created_at DESC, id DESC);

-- Governance history is retained even when an Event is merged or rejected.
CREATE TABLE IF NOT EXISTS event_governance_audits (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
    action varchar(40) NOT NULL CHECK (action IN ('lifecycle_transition','merge','split','member_move','manual_lock','manual_unlock','evidence_recompute','downstream_reconcile_required','deduplicated')),
    actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
    reason_code varchar(64) NOT NULL,
    from_status varchar(16) CHECK (from_status IS NULL OR from_status IN ('detected','active','cooling','closed','archived','rejected','merged')),
    to_status varchar(16) CHECK (to_status IS NULL OR to_status IN ('detected','active','cooling','closed','archived','rejected','merged')),
    source_event_id bigint REFERENCES events(id) ON DELETE SET NULL,
    target_event_id bigint REFERENCES events(id) ON DELETE SET NULL,
    expected_version bigint,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(metadata) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS event_governance_audits_event_idx ON event_governance_audits(event_id, created_at DESC, id DESC);

-- Event keys are stable business identifiers. Decisions and governance audits
-- are retained facts: corrections create a new fact instead of mutating one.
CREATE OR REPLACE FUNCTION enforce_event_key_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.event_key IS DISTINCT FROM OLD.event_key THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'events_event_key_immutable', MESSAGE = 'event_key is immutable';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS events_event_key_immutable ON events;
CREATE TRIGGER events_event_key_immutable
BEFORE UPDATE OF event_key ON events
FOR EACH ROW EXECUTE FUNCTION enforce_event_key_immutability();

CREATE OR REPLACE FUNCTION reject_event_append_only_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'event_append_only_mutation', MESSAGE = 'event decision and governance audit facts are append-only';
END;
$$;

DROP TRIGGER IF EXISTS event_clustering_decisions_append_only ON event_clustering_decisions;
CREATE TRIGGER event_clustering_decisions_append_only
BEFORE UPDATE OR DELETE ON event_clustering_decisions
FOR EACH ROW EXECUTE FUNCTION reject_event_append_only_mutation();

DROP TRIGGER IF EXISTS event_governance_audits_append_only ON event_governance_audits;
CREATE TRIGGER event_governance_audits_append_only
BEFORE UPDATE OR DELETE ON event_governance_audits
FOR EACH ROW EXECUTE FUNCTION reject_event_append_only_mutation();

CREATE TABLE IF NOT EXISTS monitor_events (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    monitor_id bigint NOT NULL REFERENCES monitors(id) ON DELETE RESTRICT, event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
    relevance_score numeric(5,2) NOT NULL CHECK (relevance_score BETWEEN 0 AND 100), final_score numeric(7,2) NOT NULL,
    first_matched_at timestamptz NOT NULL, last_matched_at timestamptz NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'visible' CHECK (status IN ('visible','hidden','review')),
    feedback varchar(16) CHECK (feedback IN ('relevant','irrelevant')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (monitor_id, event_id)
);
CREATE INDEX IF NOT EXISTS monitor_events_list_idx ON monitor_events(monitor_id, status, final_score DESC, id DESC);

CREATE TABLE IF NOT EXISTS entities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    entity_key varchar(128) NOT NULL UNIQUE, entity_type varchar(24) NOT NULL CHECK (entity_type IN ('person','organization','product','location','policy','event','other')),
    canonical_name varchar(255) NOT NULL, description text NOT NULL DEFAULT '', status varchar(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','merged','archived')),
    merged_into_id bigint REFERENCES entities(id) ON DELETE SET NULL, manual_locked boolean NOT NULL DEFAULT false,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz
);

CREATE TABLE IF NOT EXISTS entity_aliases (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    entity_id bigint NOT NULL REFERENCES entities(id) ON DELETE CASCADE, alias varchar(255) NOT NULL,
    normalized_alias varchar(255) NOT NULL, language varchar(16) NOT NULL, origin varchar(16) NOT NULL CHECK (origin IN ('source','model','user')),
    confirmed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (entity_id, normalized_alias, language)
);
CREATE INDEX IF NOT EXISTS entity_aliases_trgm_idx ON entity_aliases USING gin (normalized_alias gin_trgm_ops);

CREATE TABLE IF NOT EXISTS event_entities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    event_id bigint NOT NULL REFERENCES events(id) ON DELETE CASCADE, entity_id bigint NOT NULL REFERENCES entities(id) ON DELETE RESTRICT,
    role varchar(64) NOT NULL, confidence numeric(5,2) NOT NULL CHECK (confidence BETWEEN 0 AND 100),
    origin varchar(16) NOT NULL CHECK (origin IN ('source','model','user')), confirmed boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (event_id, entity_id, role)
);

CREATE TABLE IF NOT EXISTS event_claims (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT, normalized_claim text NOT NULL, claim_hash char(64) NOT NULL,
    status varchar(24) NOT NULL CHECK (status IN ('unverified','single_source','corroborated','disputed','retracted')),
    confidence numeric(5,2) NOT NULL DEFAULT 0 CHECK (confidence BETWEEN 0 AND 100), first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL,
    manual_locked boolean NOT NULL DEFAULT false, created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (event_id, claim_hash)
);
CREATE INDEX IF NOT EXISTS event_claims_status_idx ON event_claims(event_id, status);

CREATE TABLE IF NOT EXISTS claim_evidences (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    claim_id bigint NOT NULL REFERENCES event_claims(id) ON DELETE CASCADE, content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    stance varchar(16) NOT NULL CHECK (stance IN ('supports','contradicts','mentions')), evidence_locator text NOT NULL,
    short_excerpt varchar(500) NOT NULL DEFAULT '', confidence numeric(5,2) NOT NULL CHECK (confidence BETWEEN 0 AND 100),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (claim_id, content_id, stance)
);

CREATE TABLE IF NOT EXISTS topics (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    topic_key varchar(128) NOT NULL UNIQUE, title varchar(255) NOT NULL, summary text NOT NULL DEFAULT '',
    status varchar(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived','merged')),
    parent_topic_id bigint REFERENCES topics(id) ON DELETE SET NULL, merged_into_id bigint REFERENCES topics(id) ON DELETE SET NULL,
    owner_id bigint REFERENCES users(id) ON DELETE SET NULL, manual_locked boolean NOT NULL DEFAULT false,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz
);

CREATE TABLE IF NOT EXISTS topic_events (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    topic_id bigint NOT NULL REFERENCES topics(id) ON DELETE CASCADE, event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
    relation_type varchar(16) NOT NULL CHECK (relation_type IN ('evidence_for','milestone','update','contradiction')),
    relevance_score numeric(5,2) NOT NULL CHECK (relevance_score BETWEEN 0 AND 100),
    origin varchar(16) NOT NULL CHECK (origin IN ('rule','model','user')), confirmed boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (topic_id, event_id, relation_type)
);

CREATE TABLE IF NOT EXISTS topic_entities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    topic_id bigint NOT NULL REFERENCES topics(id) ON DELETE CASCADE, entity_id bigint NOT NULL REFERENCES entities(id) ON DELETE RESTRICT,
    relation_type varchar(64) NOT NULL, confidence numeric(5,2) NOT NULL CHECK (confidence BETWEEN 0 AND 100),
    origin varchar(16) NOT NULL CHECK (origin IN ('rule','model','user')), confirmed boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (topic_id, entity_id, relation_type)
);

CREATE TABLE IF NOT EXISTS topic_relations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    from_topic_id bigint NOT NULL REFERENCES topics(id) ON DELETE CASCADE, to_topic_id bigint NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    relation_type varchar(16) NOT NULL CHECK (relation_type IN ('parent_of','related_to','evolves_from','opposes')),
    confidence numeric(5,2) NOT NULL CHECK (confidence BETWEEN 0 AND 100), confirmed boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (from_topic_id <> to_topic_id), UNIQUE (from_topic_id, to_topic_id, relation_type)
);

CREATE TABLE IF NOT EXISTS entity_relations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    from_entity_id bigint NOT NULL REFERENCES entities(id) ON DELETE CASCADE, to_entity_id bigint NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    relation_type varchar(64) NOT NULL CHECK (relation_type IN ('related_to','affiliated_with','located_in','owns','operates','supports','opposes')), confidence numeric(5,2) NOT NULL CHECK (confidence BETWEEN 0 AND 100),
    valid_from timestamptz, valid_to timestamptz, origin varchar(16) NOT NULL CHECK (origin IN ('rule','model','user')),
    confirmed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (from_entity_id <> to_entity_id), CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from),
    UNIQUE NULLS NOT DISTINCT (from_entity_id, to_entity_id, relation_type, valid_from)
);
ALTER TABLE entity_relations DROP CONSTRAINT IF EXISTS entity_relations_relation_type_check;
ALTER TABLE entity_relations ADD CONSTRAINT entity_relations_relation_type_check CHECK (relation_type IN ('related_to','affiliated_with','located_in','owns','operates','supports','opposes'));

CREATE TABLE IF NOT EXISTS ai_model_profiles (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    name varchar(120) NOT NULL, task_type varchar(32) NOT NULL CHECK (task_type IN ('embedding','term_expansion','relevance_review','event_cluster','event_summary','entity_claim_extraction')),
    provider varchar(120) NOT NULL CHECK (provider IN ('openai','deepseek','ollama','onnx')), model_name varchar(255) NOT NULL, endpoint text CHECK (endpoint IS NULL), credential_ref text,
    parameters jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (parameters = '{}'::jsonb), timeout_seconds integer NOT NULL DEFAULT 30 CHECK (timeout_seconds > 0),
    daily_budget numeric(12,4), fallback_priority smallint NOT NULL DEFAULT 100, enabled boolean NOT NULL DEFAULT true,
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
    model_version varchar(64) NOT NULL,
    embedding_dimensions smallint,
    max_attempts smallint NOT NULL DEFAULT 1 CHECK (max_attempts BETWEEN 1 AND 3),
    max_cost numeric(12,4) NOT NULL CHECK (max_cost > 0),
    CHECK (
      (provider = 'openai' AND credential_ref = 'env:OPENAI_API_KEY')
      OR (provider = 'deepseek' AND credential_ref = 'env:DEEPSEEK_API_KEY')
      OR (provider IN ('ollama','onnx') AND credential_ref IS NULL)
    ),
    CHECK (
      (task_type = 'embedding' AND embedding_dimensions = 1024)
      OR (task_type IN ('term_expansion','relevance_review','event_cluster','event_summary','entity_claim_extraction') AND embedding_dimensions IS NULL)
    ),
    CHECK (
      (provider = 'onnx' AND task_type = 'embedding')
      OR (provider = 'deepseek' AND task_type <> 'embedding')
      OR provider IN ('openai','ollama')
    ),
    CHECK (
      provider <> 'ollama'
      OR (
        model_version ~ '^[0-9a-f]{64}$'
        AND (task_type <> 'embedding' OR model_name = 'qwen3-embedding:0.6b')
      )
    ),
    CHECK (daily_budget IS NULL OR daily_budget > 0),
    CHECK (daily_budget IS NULL OR daily_budget >= max_cost)
);

-- Keep provider constraints convergent when this complete schema is executed
-- again after adding a provider. CREATE TABLE IF NOT EXISTS does not update
-- constraints on an existing table, so replace only the provider-related
-- checks and leave profile data and unrelated checks untouched.
ALTER TABLE ai_model_profiles DROP CONSTRAINT IF EXISTS ai_model_profiles_provider_check;
DO $$
DECLARE
    constraint_row record;
BEGIN
    FOR constraint_row IN
        SELECT constraint_definition.conname
        FROM pg_constraint AS constraint_definition
        WHERE constraint_definition.conrelid = 'ai_model_profiles'::regclass
          AND constraint_definition.contype = 'c'
          AND (
              (
                  pg_get_constraintdef(constraint_definition.oid) ILIKE '%credential_ref%'
                  AND pg_get_constraintdef(constraint_definition.oid) ILIKE '%provider%'
              )
              OR (
                  pg_get_constraintdef(constraint_definition.oid) ILIKE '%provider%'
                  AND pg_get_constraintdef(constraint_definition.oid) ILIKE '%task_type%'
                  AND pg_get_constraintdef(constraint_definition.oid) NOT ILIKE '%embedding_dimensions%'
              )
              OR (
                  pg_get_constraintdef(constraint_definition.oid) ILIKE '%provider%'
                  AND pg_get_constraintdef(constraint_definition.oid) ILIKE '%model_version%'
              )
          )
    LOOP
        EXECUTE format(
            'ALTER TABLE ai_model_profiles DROP CONSTRAINT %I',
            constraint_row.conname
        );
    END LOOP;
END $$;
ALTER TABLE ai_model_profiles
    ADD CONSTRAINT ai_model_profiles_provider_check
        CHECK (provider IN ('openai','deepseek','ollama','onnx')),
    ADD CONSTRAINT ai_model_profiles_credential_check CHECK (
        (provider = 'openai' AND credential_ref = 'env:OPENAI_API_KEY')
        OR (provider = 'deepseek' AND credential_ref = 'env:DEEPSEEK_API_KEY')
        OR (provider IN ('ollama','onnx') AND credential_ref IS NULL)
    ),
    ADD CONSTRAINT ai_model_profiles_provider_task_check CHECK (
        (provider = 'onnx' AND task_type = 'embedding')
        OR (provider = 'deepseek' AND task_type <> 'embedding')
        OR provider IN ('openai','ollama')
    ),
    ADD CONSTRAINT ai_model_profiles_ollama_model_check CHECK (
        provider <> 'ollama'
        OR (
            model_version ~ '^[0-9a-f]{64}$'
            AND (task_type <> 'embedding' OR model_name = 'qwen3-embedding:0.6b')
        )
    );
ALTER TABLE ai_model_profiles
    DROP CONSTRAINT IF EXISTS ai_model_profiles_task_type_check,
    DROP CONSTRAINT IF EXISTS ai_model_profiles_check1,
    DROP CONSTRAINT IF EXISTS ai_model_profiles_embedding_dimensions_check;
ALTER TABLE ai_model_profiles
    ADD CONSTRAINT ai_model_profiles_task_type_check CHECK (
        task_type IN ('embedding','term_expansion','relevance_review','event_cluster','event_summary','entity_claim_extraction')
    ),
    ADD CONSTRAINT ai_model_profiles_embedding_dimensions_check CHECK (
        (task_type = 'embedding' AND embedding_dimensions = 1024)
        OR (task_type IN ('term_expansion','relevance_review','event_cluster','event_summary','entity_claim_extraction') AND embedding_dimensions IS NULL)
    );
CREATE UNIQUE INDEX IF NOT EXISTS ai_model_profiles_active_name_uq ON ai_model_profiles(name) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS reports (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    report_type varchar(16) NOT NULL CHECK (report_type IN ('daily','weekly')), monitor_id bigint REFERENCES monitors(id) ON DELETE SET NULL,
    period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, timezone varchar(64) NOT NULL, title text NOT NULL,
    summary text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', input_snapshot_hash char(64) NOT NULL DEFAULT repeat('0',64),
    status varchar(16) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_approval','published','rejected','failed','archived')),
    generated_at timestamptz, published_at timestamptz, version_no integer NOT NULL DEFAULT 1 CHECK (version_no > 0),
    submitted_at timestamptz, submitted_by bigint,
    reviewed_at timestamptz, reviewed_by bigint, review_reason varchar(64),
    created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
    CHECK (period_end > period_start),
    CONSTRAINT reports_input_snapshot_hash_check CHECK (input_snapshot_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT reports_pending_submission_check CHECK (status <> 'pending_approval' OR submitted_at IS NOT NULL AND submitted_by IS NOT NULL),
    CONSTRAINT reports_review_check CHECK (status <> ALL (ARRAY['published','rejected']) OR reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL),
    CONSTRAINT reports_rejection_reason_check CHECK (status <> 'rejected' OR review_reason IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS reports_period_version_uq ON reports(report_type, COALESCE(monitor_id, 0), period_start, period_end, version_no);
CREATE INDEX IF NOT EXISTS reports_list_idx ON reports(report_type, monitor_id, period_start DESC, id DESC);

CREATE TABLE IF NOT EXISTS report_revision_transitions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id bigint NOT NULL REFERENCES reports(id) ON DELETE RESTRICT,
    from_status varchar(16) NOT NULL CHECK (from_status IN ('draft','pending_approval','published','rejected','failed','archived')),
    to_status varchar(16) NOT NULL CHECK (to_status IN ('draft','pending_approval','published','rejected','failed','archived')),
    expected_resource_version bigint NOT NULL CHECK (expected_resource_version > 0),
    result_resource_version bigint NOT NULL CHECK (result_resource_version = (expected_resource_version + 1)),
    actor_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    reason_code varchar(64), created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (report_id,result_resource_version),
    CHECK (from_status <> to_status),
    CHECK (to_status <> 'rejected' OR reason_code IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS report_revision_transitions_report_idx
    ON report_revision_transitions(report_id,id);

CREATE TABLE IF NOT EXISTS report_items (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    report_id bigint NOT NULL REFERENCES reports(id) ON DELETE CASCADE, event_id bigint REFERENCES events(id) ON DELETE RESTRICT,
    event_update_id bigint,
    micro_event_id bigint, micro_event_version bigint, micro_event_update_id bigint, micro_event_summary_id bigint,
    rank integer NOT NULL CHECK (rank > 0), section varchar(64) NOT NULL, inclusion_reason text NOT NULL DEFAULT '',
    title_snapshot text NOT NULL, summary_snapshot text NOT NULL DEFAULT '', heat_score_snapshot numeric(7,2) NOT NULL,
    evidence_set_hash char(64) NOT NULL, reason_codes text[] NOT NULL DEFAULT '{}',
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (report_id, event_id), UNIQUE (report_id, event_update_id), UNIQUE (report_id, rank),
    CHECK (event_id IS NOT NULL AND event_update_id IS NOT NULL
        AND micro_event_id IS NULL AND micro_event_version IS NULL AND micro_event_update_id IS NULL AND micro_event_summary_id IS NULL
        OR event_id IS NULL AND event_update_id IS NULL
        AND micro_event_id IS NOT NULL AND micro_event_version > 0 AND micro_event_update_id IS NOT NULL AND micro_event_summary_id IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS report_subscriptions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, monitor_id bigint REFERENCES monitors(id) ON DELETE SET NULL,
    report_type varchar(16) NOT NULL CHECK (report_type IN ('daily','weekly')), channel varchar(16) NOT NULL CHECK (channel IN ('email','rss')),
    recipient varchar(254), rss_token_hash char(64), timezone varchar(64) NOT NULL, schedule varchar(64) NOT NULL,
    enabled boolean NOT NULL DEFAULT true, created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
    CHECK ((channel = 'email' AND recipient IS NOT NULL AND rss_token_hash IS NULL) OR (channel = 'rss' AND rss_token_hash IS NOT NULL AND recipient IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS report_subscriptions_active_scope_uq ON report_subscriptions(user_id, COALESCE(monitor_id, 0), report_type, channel) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS knowledge_documents (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    document_type varchar(16) NOT NULL CHECK (document_type IN ('event','topic','report')),
    event_id bigint REFERENCES events(id) ON DELETE RESTRICT, topic_id bigint REFERENCES topics(id) ON DELETE RESTRICT,
    report_id bigint REFERENCES reports(id) ON DELETE RESTRICT, vault_path text NOT NULL UNIQUE, revision_no bigint NOT NULL DEFAULT 0 CHECK (revision_no >= 0),
    content_hash char(64), generated_hash char(64), status varchar(16) NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','active','conflict','archived','missing')),
    last_written_at timestamptz, created_by bigint REFERENCES users(id) ON DELETE SET NULL, updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (num_nonnulls(event_id, topic_id, report_id) = 1)
);
CREATE UNIQUE INDEX IF NOT EXISTS knowledge_documents_report_uq ON knowledge_documents(report_id) WHERE report_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS knowledge_change_proposals (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    document_id bigint NOT NULL REFERENCES knowledge_documents(id) ON DELETE RESTRICT,
    change_type varchar(16) NOT NULL CHECK (change_type IN ('create','update','merge','archive')),
    base_revision_no bigint NOT NULL CHECK (base_revision_no >= 0), base_hash char(64), proposed_frontmatter jsonb NOT NULL DEFAULT '{}'::jsonb,
    proposed_body text NOT NULL DEFAULT '', diff_summary text NOT NULL DEFAULT '', reason text NOT NULL DEFAULT '',
    status varchar(16) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','conflict','applied','failed')),
    requested_by bigint REFERENCES users(id) ON DELETE SET NULL, reviewed_by bigint REFERENCES users(id) ON DELETE SET NULL,
    reviewed_at timestamptz, applied_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS knowledge_change_proposals_status_idx ON knowledge_change_proposals(status, created_at, id);

CREATE TABLE IF NOT EXISTS knowledge_annotations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    document_id bigint NOT NULL REFERENCES knowledge_documents(id) ON DELETE RESTRICT, author_id bigint REFERENCES users(id) ON DELETE SET NULL,
    annotation_type varchar(16) NOT NULL CHECK (annotation_type IN ('note','correction','question')), body text NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','resolved','archived')),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz
);

CREATE TABLE IF NOT EXISTS retention_policies (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    data_class varchar(64) NOT NULL UNIQUE, retention_days integer NOT NULL CHECK (retention_days > 0),
    action varchar(16) NOT NULL CHECK (action IN ('archive','delete')), enabled boolean NOT NULL DEFAULT true,
    description text NOT NULL DEFAULT '', created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    updated_by bigint REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO retention_policies (data_class, retention_days, action, enabled, description)
VALUES
    ('captured_items', 30, 'delete', true, '删除已标准化或明确跳过的采集临时项'),
    ('content_metric_snapshots', 180, 'delete', true, '删除过期内容指标快照'),
    ('event_metric_snapshots', 180, 'delete', true, '删除过期事件指标快照'),
    ('sessions', 30, 'delete', true, '删除过期或已撤销会话'),
    ('delivery_attempts', 90, 'delete', true, '删除过期报告投递尝试'),
    ('job_attempts', 30, 'delete', true, '删除过期队列尝试'),
    ('audit_logs', 365, 'delete', false, '受保护的审计事实，普通保留任务不可删除')
ON CONFLICT (data_class) DO NOTHING;

CREATE TABLE IF NOT EXISTS quota_usage_ledgers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dimension varchar(64) NOT NULL CHECK (dimension = 'manual_searches'),
    subject_type varchar(16) NOT NULL CHECK (subject_type = 'user'),
    subject_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    window_start timestamptz NOT NULL,
    window_end timestamptz NOT NULL CHECK (window_end > window_start),
    used bigint NOT NULL DEFAULT 0 CHECK (used >= 0),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (dimension, subject_type, subject_id, window_start)
);
CREATE INDEX IF NOT EXISTS quota_usage_ledgers_window_idx
    ON quota_usage_ledgers(dimension, window_start, subject_id);

CREATE TABLE IF NOT EXISTS auth_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    family_id uuid NOT NULL UNIQUE, absolute_expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz, revoke_reason varchar(120), created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (absolute_expires_at > created_at)
);
CREATE INDEX IF NOT EXISTS auth_sessions_active_user_idx ON auth_sessions(user_id, absolute_expires_at) WHERE revoked_at IS NULL;

CREATE OR REPLACE FUNCTION enforce_auth_session_absolute_expiry_immutable()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.absolute_expires_at IS DISTINCT FROM OLD.absolute_expires_at THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            CONSTRAINT = 'auth_sessions_absolute_expiry_immutable',
            MESSAGE = 'auth session absolute expiry is immutable';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS auth_sessions_absolute_expiry_immutable ON auth_sessions;
CREATE TRIGGER auth_sessions_absolute_expiry_immutable
BEFORE UPDATE OF absolute_expires_at ON auth_sessions
FOR EACH ROW EXECUTE FUNCTION enforce_auth_session_absolute_expiry_immutable();

CREATE TABLE IF NOT EXISTS auth_refresh_tokens (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id bigint NOT NULL REFERENCES auth_sessions(id) ON DELETE CASCADE,
    token_hash char(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL,
    used_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at > created_at)
);
CREATE INDEX IF NOT EXISTS auth_refresh_tokens_session_expiry_idx ON auth_refresh_tokens(session_id, expires_at);

CREATE TABLE IF NOT EXISTS agent_tokens (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    name varchar(64) NOT NULL CHECK (name = btrim(name) AND char_length(name) >= 1 AND char_length(name) <= 64),
    token_prefix varchar(24) NOT NULL UNIQUE CHECK (token_prefix ~ '^hk_agent_[A-Za-z0-9_-]{6,15}$'),
    token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    scopes text[] NOT NULL CHECK (
        cardinality(scopes) >= 1 AND cardinality(scopes) <= 6
        AND scopes <@ ARRAY['monitors.read','events.read','contents.read','reports.read','search.run','alerts.write']::text[]
    ),
    expires_at timestamptz NOT NULL,
    last_used_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at > created_at),
    CHECK (last_used_at IS NULL OR last_used_at >= created_at),
    CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);
CREATE INDEX IF NOT EXISTS agent_tokens_active_user_idx
    ON agent_tokens(user_id, expires_at, id) WHERE revoked_at IS NULL;

CREATE OR REPLACE FUNCTION enforce_auth_refresh_token_expiry()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    session_absolute_expires_at timestamptz;
BEGIN
    SELECT absolute_expires_at INTO session_absolute_expires_at
    FROM auth_sessions
    WHERE id = NEW.session_id;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;
    IF NEW.expires_at > session_absolute_expires_at THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            CONSTRAINT = 'auth_refresh_tokens_expires_within_session_check',
            MESSAGE = 'auth refresh token expiry must not exceed session absolute expiry';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS auth_refresh_tokens_expires_within_session_check ON auth_refresh_tokens;
CREATE TRIGGER auth_refresh_tokens_expires_within_session_check
BEFORE INSERT OR UPDATE OF session_id, expires_at ON auth_refresh_tokens
FOR EACH ROW EXECUTE FUNCTION enforce_auth_refresh_token_expiry();

CREATE TABLE IF NOT EXISTS source_checkpoints (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version bigint NOT NULL DEFAULT 1,
    monitor_source_id bigint NOT NULL UNIQUE REFERENCES monitor_sources(id) ON DELETE CASCADE, query_hash char(64) NOT NULL,
    cursor_value text, etag text, last_modified text, high_watermark timestamptz,
    last_successful_run_id bigint, last_fetched_at timestamptz, next_poll_at timestamptz NOT NULL,
    consecutive_failures integer NOT NULL DEFAULT 0 CHECK (consecutive_failures >= 0), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS source_checkpoints_poll_idx ON source_checkpoints(next_poll_at, monitor_source_id);

CREATE TABLE IF NOT EXISTS collection_runs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    query_signature char(64) NOT NULL, request_cursor text, next_cursor text, etag text, last_modified text,
    retry_after timestamptz, page_count integer NOT NULL DEFAULT 0 CHECK (page_count >= 0),
    window_start timestamptz NOT NULL, window_end timestamptz NOT NULL CHECK (window_end > window_start),
    trigger_type varchar(16) NOT NULL CHECK (trigger_type IN ('schedule','manual','retry','reconcile')),
    scheduled_at timestamptz NOT NULL, started_at timestamptz, finished_at timestamptz,
    status varchar(16) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','cancelled')),
    candidate_count bigint NOT NULL DEFAULT 0 CHECK (candidate_count >= 0), accepted_count bigint NOT NULL DEFAULT 0 CHECK (accepted_count >= 0),
    rejected_count bigint NOT NULL DEFAULT 0 CHECK (rejected_count >= 0), error_code varchar(64),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, query_signature, window_start, window_end),
    UNIQUE (id, source_connection_id)
);

ALTER TABLE source_checkpoints DROP CONSTRAINT IF EXISTS source_checkpoints_last_successful_run_fkey;
ALTER TABLE source_checkpoints
    ADD CONSTRAINT source_checkpoints_last_successful_run_fkey
    FOREIGN KEY (last_successful_run_id) REFERENCES collection_runs(id) ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS collection_run_targets (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    collection_run_id bigint NOT NULL REFERENCES collection_runs(id) ON DELETE CASCADE,
    monitor_source_id bigint NOT NULL, monitor_config_version_id bigint NOT NULL,
    target_status varchar(16) NOT NULL DEFAULT 'queued' CHECK (target_status IN ('queued','running','succeeded','failed','cancelled')),
    candidate_count bigint NOT NULL DEFAULT 0 CHECK (candidate_count >= 0), accepted_count bigint NOT NULL DEFAULT 0 CHECK (accepted_count >= 0),
    rejected_count bigint NOT NULL DEFAULT 0 CHECK (rejected_count >= 0), error_code varchar(64),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (monitor_source_id, monitor_config_version_id) REFERENCES monitor_sources(id, config_version_id) ON DELETE RESTRICT,
    UNIQUE (collection_run_id, monitor_source_id),
    UNIQUE (id, collection_run_id)
);

CREATE TABLE IF NOT EXISTS collection_run_items (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id bigint NOT NULL REFERENCES collection_runs(id) ON DELETE CASCADE,
    source_code varchar(64) NOT NULL, external_id varchar(512) NOT NULL, content_type varchar(32) NOT NULL,
    captured_item_version varchar(32) NOT NULL, captured_item jsonb NOT NULL CHECK (jsonb_typeof(captured_item) = 'object'),
    payload_hash char(64) NOT NULL, raw_payload_disposition varchar(32) NOT NULL CHECK (raw_payload_disposition IN ('discarded', 'captured_item_only')),
    content_id bigint,
    outcome varchar(16) NOT NULL CHECK (outcome IN ('captured','skipped','failed')), reason_code varchar(64), observed_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(), source_connection_id bigint NOT NULL,
    ingestion_status varchar(16) NOT NULL DEFAULT 'pending' CHECK (ingestion_status IN ('pending','succeeded','failed')),
    ingestion_error_code varchar(64),
    FOREIGN KEY (run_id, source_connection_id) REFERENCES collection_runs(id, source_connection_id) ON DELETE CASCADE,
    FOREIGN KEY (content_id, source_connection_id) REFERENCES contents(id, source_connection_id) ON DELETE SET NULL (content_id),
    CHECK (outcome = 'captured' AND (
            (content_id IS NULL AND ingestion_status = 'pending' AND ingestion_error_code IS NULL)
            OR (content_id IS NULL AND ingestion_status = 'failed' AND ingestion_error_code IS NOT NULL)
            OR (content_id IS NOT NULL AND ingestion_status = 'succeeded' AND ingestion_error_code IS NULL)
        ) OR (outcome IN ('skipped', 'failed') AND content_id IS NULL AND ingestion_status = 'pending' AND ingestion_error_code IS NULL)),
    UNIQUE (run_id, external_id), UNIQUE (id, run_id)
);

CREATE TABLE IF NOT EXISTS collection_run_target_items (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    collection_run_id bigint NOT NULL,
    collection_run_target_id bigint NOT NULL,
    collection_run_item_id bigint NOT NULL,
    outcome varchar(16) NOT NULL CHECK (outcome IN ('captured','skipped','failed')), reason_code varchar(64),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (collection_run_target_id, collection_run_id) REFERENCES collection_run_targets(id, collection_run_id) ON DELETE CASCADE,
    FOREIGN KEY (collection_run_item_id, collection_run_id) REFERENCES collection_run_items(id, run_id) ON DELETE CASCADE,
    UNIQUE (collection_run_target_id, collection_run_item_id)
);

-- Evidence lineage is an additive shadow write path. Legacy
-- collection_run_items/contents/content_assets remain readable for rollback,
-- but none of them is treated as an original-response or document-version
-- fact by this model.
CREATE TABLE IF NOT EXISTS source_rights_policies (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    recorded_by_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    idempotency_key varchar(128) NOT NULL CHECK (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'),
    command_fingerprint char(64) NOT NULL CHECK (command_fingerprint ~ '^[0-9a-f]{64}$'),
    source_connection_id bigint REFERENCES source_connections(id) ON DELETE RESTRICT,
    scope_type varchar(32) NOT NULL CHECK (scope_type IN ('organization_default','source_endpoint','publisher','feed_or_account','observation')),
    scope_subject varchar(512) NOT NULL DEFAULT '',
    policy_revision bigint NOT NULL CHECK (policy_revision > 0),
    priority smallint NOT NULL CHECK (priority IN (100,200,300,400)),
    basis_summary text NOT NULL CHECK (octet_length(basis_summary) >= 1 AND octet_length(basis_summary) <= 1024),
    terms_url text, license_uri text,
    policy_hash char(64) NOT NULL UNIQUE CHECK (policy_hash ~ '^[0-9a-f]{64}$'),
    parent_policy_id bigint REFERENCES source_rights_policies(id) ON DELETE RESTRICT,
    approved_by_user_id bigint REFERENCES users(id) ON DELETE RESTRICT,
    effective_at timestamptz NOT NULL,
    expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at IS NULL OR expires_at > effective_at),
    CHECK (
        scope_type = 'organization_default' AND source_connection_id IS NULL AND scope_subject = '' AND priority = 100
        OR scope_type IN ('source_endpoint','publisher','feed_or_account') AND source_connection_id IS NOT NULL AND scope_subject <> '' AND priority IN (200,300)
        OR scope_type = 'observation' AND source_connection_id IS NOT NULL AND scope_subject <> '' AND priority = 400
    )
);
DROP TRIGGER IF EXISTS source_rights_policies_append_only ON source_rights_policies;
ALTER TABLE source_rights_policies ADD COLUMN IF NOT EXISTS recorded_by_user_id bigint REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE source_rights_policies ADD COLUMN IF NOT EXISTS idempotency_key varchar(128);
ALTER TABLE source_rights_policies ADD COLUMN IF NOT EXISTS command_fingerprint char(64);
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM source_rights_policies
        WHERE recorded_by_user_id IS NULL OR idempotency_key IS NULL OR command_fingerprint IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_policies_command_receipt_required',
            MESSAGE = 'existing rights policies require an operator-reviewed idempotency receipt before canonical convergence';
    END IF;
END;
$$;
ALTER TABLE source_rights_policies ALTER COLUMN recorded_by_user_id SET NOT NULL;
ALTER TABLE source_rights_policies ALTER COLUMN idempotency_key SET NOT NULL;
ALTER TABLE source_rights_policies ALTER COLUMN command_fingerprint SET NOT NULL;
ALTER TABLE source_rights_policies DROP CONSTRAINT IF EXISTS source_rights_policies_idempotency_key_check;
ALTER TABLE source_rights_policies ADD CONSTRAINT source_rights_policies_idempotency_key_check
    CHECK (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$');
ALTER TABLE source_rights_policies DROP CONSTRAINT IF EXISTS source_rights_policies_command_fingerprint_check;
ALTER TABLE source_rights_policies ADD CONSTRAINT source_rights_policies_command_fingerprint_check
    CHECK (command_fingerprint ~ '^[0-9a-f]{64}$');
ALTER TABLE source_rights_policies
    DROP CONSTRAINT IF EXISTS source_rights_policies_scope_type_scope_subject_policy_revision_key;
ALTER TABLE source_rights_policies DROP CONSTRAINT IF EXISTS source_rights_policies_policy_hash_check;
ALTER TABLE source_rights_policies ADD CONSTRAINT source_rights_policies_policy_hash_check
    CHECK (policy_hash ~ '^[0-9a-f]{64}$');
CREATE UNIQUE INDEX IF NOT EXISTS source_rights_policies_organization_scope_uq
    ON source_rights_policies(scope_type, scope_subject, policy_revision)
    WHERE source_connection_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS source_rights_policies_source_scope_uq
    ON source_rights_policies(source_connection_id, scope_type, scope_subject, policy_revision)
    WHERE source_connection_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS source_rights_policies_scope_idx
    ON source_rights_policies(scope_type, source_connection_id, scope_subject, policy_revision DESC);
CREATE UNIQUE INDEX IF NOT EXISTS source_rights_policies_idempotency_uq
    ON source_rights_policies(idempotency_key);
CREATE UNIQUE INDEX IF NOT EXISTS source_rights_policies_id_version_uq
    ON source_rights_policies(id, version);

CREATE OR REPLACE FUNCTION enforce_source_rights_policy_actor_authority()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM users
        WHERE id = NEW.recorded_by_user_id
          AND role = 'admin'
          AND status = 'active'
          AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_policies_recorder_authority',
            MESSAGE = 'rights policy recorder must be an active administrator';
    END IF;
    IF NEW.approved_by_user_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM users
        WHERE id = NEW.approved_by_user_id
          AND role = 'admin'
          AND status = 'active'
          AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_policies_approver_authority',
            MESSAGE = 'rights policy approver must be an active administrator';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS source_rights_policies_actor_authority ON source_rights_policies;
CREATE TRIGGER source_rights_policies_actor_authority
BEFORE INSERT ON source_rights_policies
FOR EACH ROW EXECUTE FUNCTION enforce_source_rights_policy_actor_authority();

CREATE TABLE IF NOT EXISTS source_rights_decision_batches (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    policy_id bigint NOT NULL,
    expected_policy_version bigint NOT NULL CHECK (expected_policy_version = 1),
    subject_type varchar(32) NOT NULL CHECK (subject_type IN ('source_endpoint','raw_response','source_observation','document_version')),
    subject_key varchar(512) NOT NULL CHECK (octet_length(subject_key) >= 1 AND octet_length(subject_key) <= 512),
    input_digest char(64) NOT NULL CHECK (input_digest ~ '^[0-9a-f]{64}$'),
    recorded_by_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    idempotency_key varchar(128) NOT NULL CHECK (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'),
    command_fingerprint char(64) NOT NULL CHECK (command_fingerprint ~ '^[0-9a-f]{64}$'),
    decision_count smallint NOT NULL CHECK (decision_count BETWEEN 1 AND 9),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (policy_id, expected_policy_version) REFERENCES source_rights_policies(id, version) ON DELETE RESTRICT,
    UNIQUE (id, source_connection_id, policy_id, subject_type, subject_key, input_digest)
);
CREATE UNIQUE INDEX IF NOT EXISTS source_rights_decision_batches_idempotency_uq
    ON source_rights_decision_batches(idempotency_key);
CREATE INDEX IF NOT EXISTS source_rights_decision_batches_subject_idx
    ON source_rights_decision_batches(source_connection_id, subject_type, subject_key, input_digest, created_at DESC, id DESC);

CREATE OR REPLACE FUNCTION enforce_source_rights_decision_batch_actor_authority()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM users
        WHERE id = NEW.recorded_by_user_id
          AND role = 'admin'
          AND status = 'active'
          AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decision_batches_recorder_authority',
            MESSAGE = 'rights decision recorder must be an active administrator';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS source_rights_decision_batches_actor_authority ON source_rights_decision_batches;
CREATE TRIGGER source_rights_decision_batches_actor_authority
BEFORE INSERT ON source_rights_decision_batches
FOR EACH ROW EXECUTE FUNCTION enforce_source_rights_decision_batch_actor_authority();

CREATE TABLE IF NOT EXISTS source_rights_decisions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    decision_batch_id bigint NOT NULL,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    policy_id bigint NOT NULL REFERENCES source_rights_policies(id) ON DELETE RESTRICT,
    policy_revision bigint NOT NULL CHECK (policy_revision > 0),
    policy_scope_type varchar(32) NOT NULL CHECK (policy_scope_type IN ('organization_default','source_endpoint','publisher','feed_or_account','observation')),
    policy_scope_subject varchar(512) NOT NULL DEFAULT '',
    priority_rank smallint NOT NULL CHECK (priority_rank IN (100,200,300,400)),
    basis_summary text NOT NULL CHECK (octet_length(basis_summary) >= 1 AND octet_length(basis_summary) <= 1024),
    terms_url text,
    license_uri text,
    subject_type varchar(32) NOT NULL CHECK (subject_type IN ('source_endpoint','raw_response','source_observation','document_version')),
    subject_key varchar(512) NOT NULL CHECK (octet_length(subject_key) >= 1 AND octet_length(subject_key) <= 512),
    input_digest char(64) NOT NULL CHECK (input_digest ~ '^[0-9a-f]{64}$'),
    action varchar(32) NOT NULL CHECK (action IN ('fetch','store_raw','store_derived','display_private','redistribute','quote','embed_local','send_external_model','retain')),
    decision varchar(8) NOT NULL CHECK (decision IN ('allow','deny','unknown')),
    reason_codes text[] NOT NULL DEFAULT '{}',
    evaluator varchar(64) NOT NULL CHECK (octet_length(evaluator) >= 1 AND octet_length(evaluator) <= 64),
    evaluated_at timestamptz NOT NULL,
    effective_from timestamptz NOT NULL,
    expires_at timestamptz CHECK (expires_at IS NULL OR expires_at > effective_from),
    retention_days integer CHECK (action = 'retain' AND retention_days BETWEEN 1 AND 3650 OR action <> 'retain' AND retention_days IS NULL),
    supersedes_decision_id bigint REFERENCES source_rights_decisions(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, subject_type, subject_key, input_digest, action, policy_id),
    UNIQUE (decision_batch_id, action),
    UNIQUE (id, source_connection_id, action, decision)
);
DROP TRIGGER IF EXISTS source_rights_decisions_append_only ON source_rights_decisions;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS decision_batch_id bigint;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS policy_revision bigint;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS policy_scope_type varchar(32);
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS policy_scope_subject varchar(512);
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS priority_rank smallint;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS basis_summary text;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS terms_url text;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS license_uri text;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS effective_from timestamptz;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS retention_days integer;
ALTER TABLE source_rights_decisions ADD COLUMN IF NOT EXISTS supersedes_decision_id bigint REFERENCES source_rights_decisions(id) ON DELETE RESTRICT;
UPDATE source_rights_decisions AS decision
SET policy_revision = COALESCE(decision.policy_revision, policy.policy_revision),
    policy_scope_type = COALESCE(decision.policy_scope_type, policy.scope_type),
    policy_scope_subject = COALESCE(decision.policy_scope_subject, policy.scope_subject),
    priority_rank = COALESCE(decision.priority_rank, policy.priority),
    basis_summary = COALESCE(decision.basis_summary, policy.basis_summary),
    terms_url = COALESCE(decision.terms_url, policy.terms_url),
    license_uri = COALESCE(decision.license_uri, policy.license_uri),
    effective_from = COALESCE(decision.effective_from, policy.effective_at)
FROM source_rights_policies AS policy
WHERE policy.id = decision.policy_id
  AND (decision.policy_revision IS NULL OR decision.policy_scope_type IS NULL
       OR decision.policy_scope_subject IS NULL OR decision.priority_rank IS NULL
       OR decision.basis_summary IS NULL OR decision.effective_from IS NULL);
ALTER TABLE source_rights_decisions DROP COLUMN IF EXISTS policy_version;
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'source_rights_policies' AND column_name = 'retention_days'
    ) THEN
        EXECUTE $backfill$
            UPDATE source_rights_decisions AS decision
            SET retention_days = policy.retention_days
            FROM source_rights_policies AS policy
            WHERE policy.id = decision.policy_id
              AND decision.action = 'retain'
              AND decision.retention_days IS NULL
              AND policy.retention_days BETWEEN 1 AND 3650
        $backfill$;
    END IF;
END;
$$;
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM source_rights_decisions WHERE decision_batch_id IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_batch_required',
            MESSAGE = 'existing rights decisions require an operator-reviewed decision batch before canonical convergence';
    END IF;
END;
$$;
ALTER TABLE source_rights_decisions ALTER COLUMN decision_batch_id SET NOT NULL;
ALTER TABLE source_rights_decisions ALTER COLUMN policy_revision SET NOT NULL;
ALTER TABLE source_rights_decisions ALTER COLUMN policy_scope_type SET NOT NULL;
ALTER TABLE source_rights_decisions ALTER COLUMN policy_scope_subject SET NOT NULL;
ALTER TABLE source_rights_decisions ALTER COLUMN policy_scope_subject SET DEFAULT '';
ALTER TABLE source_rights_decisions ALTER COLUMN priority_rank SET NOT NULL;
ALTER TABLE source_rights_decisions ALTER COLUMN basis_summary SET NOT NULL;
ALTER TABLE source_rights_decisions ALTER COLUMN effective_from SET NOT NULL;
ALTER TABLE source_rights_decision_batches DROP CONSTRAINT IF EXISTS source_rights_decision_batches_subject_type_check;
ALTER TABLE source_rights_decision_batches ADD CONSTRAINT source_rights_decision_batches_subject_type_check
    CHECK (subject_type IN ('source_endpoint','raw_response','source_observation','document_version'));
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_subject_type_check;
ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_subject_type_check
    CHECK (subject_type IN ('source_endpoint','raw_response','source_observation','document_version'));
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_policy_version_check;
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_policy_revision_check;
ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_policy_revision_check CHECK (policy_revision > 0);
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_policy_scope_type_check;
ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_policy_scope_type_check
    CHECK (policy_scope_type IN ('organization_default','source_endpoint','publisher','feed_or_account','observation'));
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_priority_rank_check;
ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_priority_rank_check CHECK (priority_rank IN (100,200,300,400));
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_basis_summary_check;
ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_basis_summary_check
    CHECK (octet_length(basis_summary) >= 1 AND octet_length(basis_summary) <= 1024);
ALTER TABLE source_rights_decisions DROP CONSTRAINT IF EXISTS source_rights_decisions_input_digest_check;
ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_input_digest_check CHECK (input_digest ~ '^[0-9a-f]{64}$');
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'source_rights_decisions'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) = 'CHECK (expires_at IS NULL OR expires_at > effective_from)'
    ) THEN
        ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_effective_lifetime_check
            CHECK (expires_at IS NULL OR expires_at > effective_from);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'source_rights_decisions'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) =
              'CHECK (action::text = ''retain''::text AND retention_days >= 1 AND retention_days <= 3650 OR action::text <> ''retain''::text AND retention_days IS NULL)'
    ) THEN
        ALTER TABLE source_rights_decisions ADD CONSTRAINT source_rights_decisions_retain_duration_check
            CHECK (action = 'retain' AND retention_days BETWEEN 1 AND 3650 OR action <> 'retain' AND retention_days IS NULL);
    END IF;
END;
$$;
DO $$
DECLARE
    legacy_constraint text;
BEGIN
    FOR legacy_constraint IN
        SELECT constraint_record.conname
        FROM pg_constraint AS constraint_record
        JOIN pg_class AS relation ON relation.oid = constraint_record.conrelid
        JOIN pg_namespace AS namespace ON namespace.oid = relation.relnamespace
        WHERE namespace.nspname = 'public'
          AND relation.relname = 'source_rights_decisions'
          AND constraint_record.contype = 'u'
          AND pg_get_constraintdef(constraint_record.oid) IN (
              'UNIQUE (subject_type, subject_key, input_digest, action, policy_id)',
              'UNIQUE (source_connection_id, subject_type, subject_key, input_digest, action, policy_id)'
          )
    LOOP
        EXECUTE format('ALTER TABLE source_rights_decisions DROP CONSTRAINT %I', legacy_constraint);
    END LOOP;
END;
$$;
