CREATE TABLE IF NOT EXISTS evidence_snapshots (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    collection_run_id bigint REFERENCES collection_runs(id) ON DELETE RESTRICT,
    store_raw_rights_decision_id bigint NOT NULL,
    retain_rights_decision_id bigint NOT NULL,
    rights_action varchar(32) NOT NULL DEFAULT 'store_raw' CHECK (rights_action = 'store_raw'),
    rights_decision varchar(8) NOT NULL DEFAULT 'allow' CHECK (rights_decision = 'allow'),
    retain_action varchar(32) NOT NULL DEFAULT 'retain' CHECK (retain_action = 'retain'),
    retain_decision varchar(8) NOT NULL DEFAULT 'allow' CHECK (retain_decision = 'allow'),
    snapshot_key char(64) NOT NULL CHECK (snapshot_key ~ '^[0-9a-f]{64}$'),
    object_key text NOT NULL UNIQUE,
    payload_sha256 char(64) NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
    collector_profile_version varchar(64) NOT NULL
        CHECK (collector_profile_version ~ '^[a-z0-9][a-z0-9._:-]{0,63}$'),
    mime_type varchar(255) NOT NULL CHECK (octet_length(mime_type) >= 3 AND octet_length(mime_type) <= 255),
    size_bytes bigint NOT NULL CHECK (size_bytes >= 0),
    response_status smallint NOT NULL CHECK (response_status BETWEEN 100 AND 599),
    requested_url text NOT NULL,
    final_url text NOT NULL,
    redirect_chain jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(redirect_chain) = 'array'),
    response_headers jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (
        jsonb_typeof(response_headers) = 'object'
        AND response_headers - ARRAY['content-type','etag','last-modified','date','link','retry-after']::text[] = '{}'::jsonb
    ),
    captured_at timestamptz NOT NULL CHECK (captured_at <= (created_at + '00:05:00'::interval)),
    retention_until timestamptz NOT NULL CHECK (retention_until > captured_at AND retention_until > created_at),
    lifecycle_state varchar(32) NOT NULL DEFAULT 'raw_pending'
        CHECK (lifecycle_state IN ('policy_pending','policy_blocked','raw_pending','raw_available','raw_failed','retention_blocked','quarantined','tombstoned')),
    failure_code varchar(64),
    available_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, source_connection_id),
    UNIQUE (source_connection_id, snapshot_key),
    CHECK (
        lifecycle_state = 'raw_available' AND available_at IS NOT NULL AND failure_code IS NULL
        OR lifecycle_state = 'raw_failed' AND available_at IS NULL AND failure_code IS NOT NULL
        OR lifecycle_state <> 'raw_available' AND lifecycle_state <> 'raw_failed' AND available_at IS NULL AND failure_code IS NULL
    )
);
DROP TRIGGER IF EXISTS evidence_snapshots_lifecycle ON evidence_snapshots;
ALTER TABLE evidence_snapshots ADD COLUMN IF NOT EXISTS retain_rights_decision_id bigint;
ALTER TABLE evidence_snapshots ADD COLUMN IF NOT EXISTS retain_action varchar(32) NOT NULL DEFAULT 'retain';
ALTER TABLE evidence_snapshots ADD COLUMN IF NOT EXISTS retain_decision varchar(8) NOT NULL DEFAULT 'allow';
ALTER TABLE evidence_snapshots ADD COLUMN IF NOT EXISTS collector_profile_version varchar(64);
ALTER TABLE evidence_snapshots ALTER COLUMN retain_rights_decision_id SET NOT NULL;
ALTER TABLE evidence_snapshots ALTER COLUMN collector_profile_version SET NOT NULL;
ALTER TABLE evidence_snapshots ALTER COLUMN retention_until SET NOT NULL;
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_retain_action_check;
ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_retain_action_check CHECK (retain_action = 'retain');
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_retain_decision_check;
ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_retain_decision_check CHECK (retain_decision = 'allow');
