    FOREIGN KEY (retain_rights_decision_id, source_connection_id, retain_action, retain_decision)
    REFERENCES source_rights_decisions(id, source_connection_id, action, decision) ON DELETE RESTRICT;
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_snapshot_key_check;
ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_snapshot_key_check CHECK (snapshot_key ~ '^[0-9a-f]{64}$');
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_payload_sha256_check;
ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_payload_sha256_check CHECK (payload_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_collector_profile_version_check;
ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_collector_profile_version_check
    CHECK (collector_profile_version ~ '^[a-z0-9][a-z0-9._:-]{0,63}$');
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'evidence_snapshots'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) LIKE
              'CHECK (captured_at <=%created_at%00:05:00%interval%'
    ) THEN
        ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_captured_at_check
            CHECK (captured_at <= (created_at + '00:05:00'::interval));
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'evidence_snapshots'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) =
              'CHECK (retention_until > captured_at AND retention_until > created_at)'
    ) THEN
        ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_retention_until_check
            CHECK (retention_until > captured_at AND retention_until > created_at);
    END IF;
END;
$$;
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_snapshot_key_key;
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_source_connection_id_snapshot_key_key;
ALTER TABLE evidence_snapshots DROP CONSTRAINT IF EXISTS evidence_snapshots_source_snapshot_key_uq;
ALTER TABLE evidence_snapshots ADD CONSTRAINT evidence_snapshots_source_snapshot_key_uq
    UNIQUE (source_connection_id, snapshot_key);
CREATE INDEX IF NOT EXISTS evidence_snapshots_reconcile_idx
    ON evidence_snapshots(lifecycle_state, updated_at, id);

CREATE TABLE IF NOT EXISTS evidence_retention_exceptions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    evidence_snapshot_id bigint NOT NULL,
    approved_by_user_id bigint NOT NULL,
    approval_basis text NOT NULL CHECK (btrim(approval_basis) <> '' AND octet_length(approval_basis) <= 2000),
    approved_at timestamptz NOT NULL,
    expires_at timestamptz,
    revoked_by_user_id bigint,
    revoked_at timestamptz,
    revocation_basis text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at IS NULL OR expires_at > approved_at),
    CHECK (
        revoked_at IS NULL AND revoked_by_user_id IS NULL AND revocation_basis IS NULL
        OR revoked_at IS NOT NULL AND revoked_at >= approved_at AND revoked_by_user_id IS NOT NULL
           AND btrim(COALESCE(revocation_basis,'')) <> ''
    )
);
ALTER TABLE evidence_retention_exceptions DROP CONSTRAINT IF EXISTS evidence_retention_exceptions_evidence_snapshot_id_fkey;
ALTER TABLE evidence_retention_exceptions ADD CONSTRAINT evidence_retention_exceptions_evidence_snapshot_id_fkey
    FOREIGN KEY (evidence_snapshot_id) REFERENCES evidence_snapshots(id) ON DELETE RESTRICT;
ALTER TABLE evidence_retention_exceptions DROP CONSTRAINT IF EXISTS evidence_retention_exceptions_approved_by_user_id_fkey;
ALTER TABLE evidence_retention_exceptions ADD CONSTRAINT evidence_retention_exceptions_approved_by_user_id_fkey
    FOREIGN KEY (approved_by_user_id) REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE evidence_retention_exceptions DROP CONSTRAINT IF EXISTS evidence_retention_exceptions_revoked_by_user_id_fkey;
ALTER TABLE evidence_retention_exceptions ADD CONSTRAINT evidence_retention_exceptions_revoked_by_user_id_fkey
    FOREIGN KEY (revoked_by_user_id) REFERENCES users(id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX IF NOT EXISTS evidence_retention_exceptions_active_uq
    ON evidence_retention_exceptions(evidence_snapshot_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS evidence_retention_exceptions_expiry_idx
    ON evidence_retention_exceptions(expires_at,evidence_snapshot_id) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS evidence_deletion_audits (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    evidence_snapshot_id bigint NOT NULL,
    source_connection_id bigint NOT NULL,
    retention_policy_id bigint NOT NULL,
    retention_policy_version bigint NOT NULL CHECK (retention_policy_version > 0),
    attempt_no integer NOT NULL CHECK (attempt_no > 0),
    event_type varchar(32) NOT NULL CHECK (event_type IN ('delete_claimed','delete_succeeded','delete_failed')),
    object_key text NOT NULL,
    payload_sha256 char(64) NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
    reason_code varchar(64) NOT NULL CHECK (reason_code ~ '^[A-Z][A-Z0-9_]{0,63}$'),
    already_missing boolean NOT NULL DEFAULT false,
    occurred_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (evidence_snapshot_id,attempt_no,event_type),
    CHECK (event_type = 'delete_succeeded' OR NOT already_missing),
    CHECK (event_type <> 'delete_failed' OR reason_code IN ('OBJECT_DELETE_FAILED','OBJECT_DELETE_INTEGRITY_FAILED')),
    CHECK (event_type = 'delete_failed' OR reason_code = 'RETENTION_EXPIRED')
);
ALTER TABLE evidence_deletion_audits DROP CONSTRAINT IF EXISTS evidence_deletion_audits_evidence_snapshot_id_fkey;
ALTER TABLE evidence_deletion_audits ADD CONSTRAINT evidence_deletion_audits_evidence_snapshot_id_fkey
    FOREIGN KEY (evidence_snapshot_id) REFERENCES evidence_snapshots(id) ON DELETE RESTRICT;
ALTER TABLE evidence_deletion_audits DROP CONSTRAINT IF EXISTS evidence_deletion_audits_source_connection_id_fkey;
ALTER TABLE evidence_deletion_audits ADD CONSTRAINT evidence_deletion_audits_source_connection_id_fkey
    FOREIGN KEY (source_connection_id) REFERENCES source_connections(id) ON DELETE RESTRICT;
ALTER TABLE evidence_deletion_audits DROP CONSTRAINT IF EXISTS evidence_deletion_audits_retention_policy_id_fkey;
ALTER TABLE evidence_deletion_audits ADD CONSTRAINT evidence_deletion_audits_retention_policy_id_fkey
    FOREIGN KEY (retention_policy_id) REFERENCES source_rights_policies(id) ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS evidence_deletion_audits_snapshot_idx
    ON evidence_deletion_audits(evidence_snapshot_id,attempt_no DESC,id DESC);

CREATE OR REPLACE FUNCTION enforce_evidence_retention_exception()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE snapshot_lifecycle varchar(32);
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='evidence_retention_exception_retained',
            MESSAGE='retention exception approvals cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT lifecycle_state INTO snapshot_lifecycle
        FROM evidence_snapshots WHERE id=NEW.evidence_snapshot_id FOR SHARE;
        IF snapshot_lifecycle IS DISTINCT FROM 'raw_available' THEN
            RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='evidence_retention_exception_available',
                MESSAGE='retention exception requires available raw evidence before deletion is claimed';
        END IF;
        IF NEW.approved_at > CURRENT_TIMESTAMP + interval '5 minutes' THEN
            RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='evidence_retention_exception_time',
                MESSAGE='retention exception approval time is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.evidence_snapshot_id IS DISTINCT FROM OLD.evidence_snapshot_id
       OR NEW.approved_by_user_id IS DISTINCT FROM OLD.approved_by_user_id
       OR NEW.approval_basis IS DISTINCT FROM OLD.approval_basis
       OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
       OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR OLD.revoked_at IS NOT NULL
       OR NEW.revoked_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='evidence_retention_exception_transition',
            MESSAGE='retention exception approval facts are immutable and revocation is one-way';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS evidence_retention_exceptions_guard ON evidence_retention_exceptions;
CREATE TRIGGER evidence_retention_exceptions_guard
BEFORE INSERT OR UPDATE OR DELETE ON evidence_retention_exceptions
FOR EACH ROW EXECUTE FUNCTION enforce_evidence_retention_exception();

CREATE TABLE IF NOT EXISTS source_observations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    collection_run_item_id bigint REFERENCES collection_run_items(id) ON DELETE RESTRICT,
    external_id varchar(512) NOT NULL,
    upstream_identity char(64) NOT NULL CHECK (upstream_identity ~ '^[0-9a-f]{64}$'),
    source_code varchar(64) NOT NULL,
    content_type varchar(32) NOT NULL,
    title text NOT NULL DEFAULT '',
    language varchar(32) NOT NULL DEFAULT 'und',
    author_snapshot varchar(512),
    source_record_url text,
    canonical_url text,
    discussion_url text,
    body_origin varchar(48) NOT NULL CHECK (body_origin IN ('api_content','feed_content','feed_summary','structured_article_body','authorized_payload_extraction','platform_post','search_snippet')),
    completeness varchar(24) NOT NULL CHECK (completeness IN ('full','partial','summary','snippet','metadata_only','unknown')),
    published_at timestamptz,
    published_utc_offset_minutes smallint,
    modified_at timestamptz,
    discovered_at timestamptz NOT NULL,
    captured_at timestamptz NOT NULL,
    observation_state varchar(24) NOT NULL DEFAULT 'active'
        CHECK (observation_state IN ('active','corrected','withdrawn','deleted','policy_blocked')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, external_id, upstream_identity),
    UNIQUE (id, source_connection_id),
    UNIQUE (collection_run_item_id),
    CHECK (source_record_url IS NOT NULL OR canonical_url IS NOT NULL OR discussion_url IS NOT NULL),
    CHECK (modified_at IS NULL OR published_at IS NULL OR modified_at >= published_at),
    CHECK (captured_at >= discovered_at),
    CHECK (
        published_at IS NULL AND published_utc_offset_minutes IS NULL
        OR published_at IS NOT NULL AND (published_utc_offset_minutes IS NULL OR published_utc_offset_minutes BETWEEN -840 AND 840)
    )
);
ALTER TABLE source_observations ADD COLUMN IF NOT EXISTS published_utc_offset_minutes smallint;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid='source_observations'::regclass AND contype='c'
          AND pg_get_constraintdef(oid) LIKE '%published_utc_offset_minutes%'
    ) THEN
        ALTER TABLE source_observations ADD CHECK (
            published_at IS NULL AND published_utc_offset_minutes IS NULL
            OR published_at IS NOT NULL AND (published_utc_offset_minutes IS NULL OR published_utc_offset_minutes BETWEEN -840 AND 840)
        );
    END IF;
END;
$$;
ALTER TABLE source_observations DROP CONSTRAINT IF EXISTS source_observations_upstream_identity_check;
ALTER TABLE source_observations ADD CONSTRAINT source_observations_upstream_identity_check
    CHECK (upstream_identity ~ '^[0-9a-f]{64}$');
ALTER TABLE source_observations DROP CONSTRAINT IF EXISTS source_observations_selected_payload_sha256_check;
ALTER TABLE source_observations DROP COLUMN IF EXISTS selected_payload_sha256;
CREATE INDEX IF NOT EXISTS source_observations_source_time_idx
    ON source_observations(source_connection_id, captured_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS source_observation_evidences (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_connection_id bigint NOT NULL,
    source_observation_id bigint NOT NULL,
    evidence_snapshot_id bigint NOT NULL,
	usage varchar(24) NOT NULL DEFAULT 'document_source' CHECK (usage IN ('document_source','context')),
    locator_type varchar(24) NOT NULL CHECK (locator_type IN ('json_pointer','xml_path','byte_range','whole_payload')),
    locator_value varchar(2048) NOT NULL,
    byte_start bigint,
    byte_end bigint,
    selected_payload_sha256 char(64) NOT NULL CHECK (selected_payload_sha256 ~ '^[0-9a-f]{64}$'),
    selector_version varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (source_observation_id, source_connection_id)
        REFERENCES source_observations(id, source_connection_id) ON DELETE RESTRICT,
    FOREIGN KEY (evidence_snapshot_id, source_connection_id)
        REFERENCES evidence_snapshots(id, source_connection_id) ON DELETE RESTRICT,
    UNIQUE (source_observation_id, evidence_snapshot_id, locator_type, locator_value),
    UNIQUE (id, source_connection_id, source_observation_id),
    CHECK (
        locator_type = 'byte_range' AND byte_start IS NOT NULL AND byte_end IS NOT NULL AND byte_start >= 0 AND byte_end > byte_start
        OR locator_type <> 'byte_range' AND byte_start IS NULL AND byte_end IS NULL
    )
);
ALTER TABLE source_observation_evidences ADD COLUMN IF NOT EXISTS usage varchar(24);
UPDATE source_observation_evidences SET usage='document_source' WHERE usage IS NULL;
ALTER TABLE source_observation_evidences ALTER COLUMN usage SET DEFAULT 'document_source';
ALTER TABLE source_observation_evidences ALTER COLUMN usage SET NOT NULL;
ALTER TABLE source_observation_evidences DROP CONSTRAINT IF EXISTS source_observation_evidences_usage_check;
ALTER TABLE source_observation_evidences ADD CONSTRAINT source_observation_evidences_usage_check
    CHECK (usage IN ('document_source','context'));
ALTER TABLE source_observation_evidences DROP CONSTRAINT IF EXISTS source_observation_evidences_selected_payload_sha256_check;
ALTER TABLE source_observation_evidences ADD CONSTRAINT source_observation_evidences_selected_payload_sha256_check
    CHECK (selected_payload_sha256 ~ '^[0-9a-f]{64}$');
CREATE INDEX IF NOT EXISTS source_observation_evidences_snapshot_idx
    ON source_observation_evidences(evidence_snapshot_id, source_observation_id);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid='source_observation_evidences'::regclass
          AND contype='u'
          AND pg_get_constraintdef(oid)='UNIQUE (id, source_connection_id, source_observation_id)'
    ) THEN
        ALTER TABLE source_observation_evidences ADD CONSTRAINT source_observation_evidences_reference_scope_uq
            UNIQUE (id, source_connection_id, source_observation_id);
    END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS source_parties (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    party_kind varchar(24) NOT NULL CHECK (party_kind IN ('organization','person','account')),
    identity_namespace varchar(64) NOT NULL
        CHECK (identity_namespace ~ '^[a-z0-9][a-z0-9._:-]{0,63}$'),
    external_id varchar(512) NOT NULL CHECK (octet_length(external_id) BETWEEN 1 AND 512),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, identity_namespace, external_id),
    UNIQUE (id, source_connection_id)
);

CREATE TABLE IF NOT EXISTS source_observation_parties (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    source_connection_id bigint NOT NULL,
    source_observation_id bigint NOT NULL,
    source_party_id bigint NOT NULL,
    evidence_reference_id bigint NOT NULL,
    role varchar(24) NOT NULL CHECK (role IN ('publisher','author','distributor','content_origin')),
    display_name_snapshot varchar(512) NOT NULL CHECK (octet_length(display_name_snapshot) BETWEEN 1 AND 512),
    homepage_url_snapshot text,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (source_observation_id, source_connection_id)
        REFERENCES source_observations(id, source_connection_id) ON DELETE RESTRICT,
    FOREIGN KEY (source_party_id, source_connection_id)
        REFERENCES source_parties(id, source_connection_id) ON DELETE RESTRICT,
    FOREIGN KEY (evidence_reference_id, source_connection_id, source_observation_id)
        REFERENCES source_observation_evidences(id, source_connection_id, source_observation_id) ON DELETE RESTRICT,
    UNIQUE (source_observation_id, role, source_party_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS source_observation_parties_one_publisher_uq
    ON source_observation_parties(source_observation_id) WHERE role='publisher';
CREATE UNIQUE INDEX IF NOT EXISTS source_observation_parties_one_content_origin_uq
    ON source_observation_parties(source_observation_id) WHERE role='content_origin';
CREATE INDEX IF NOT EXISTS source_observation_parties_party_idx
    ON source_observation_parties(source_party_id, source_observation_id);

CREATE TABLE IF NOT EXISTS documents (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    document_key char(64) NOT NULL CHECK (document_key ~ '^[0-9a-f]{64}$'),
    external_work_id varchar(512),
    current_document_version_id bigint,
    document_state varchar(24) NOT NULL DEFAULT 'active' CHECK (document_state IN ('active','withdrawn','tombstoned')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id, document_key),
    UNIQUE (id, source_connection_id)
);
ALTER TABLE documents DROP CONSTRAINT IF EXISTS documents_document_key_check;
ALTER TABLE documents ADD CONSTRAINT documents_document_key_check
    CHECK (document_key ~ '^[0-9a-f]{64}$');

CREATE TABLE IF NOT EXISTS document_versions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    document_id bigint NOT NULL REFERENCES documents(id) ON DELETE RESTRICT,
    source_observation_id bigint NOT NULL REFERENCES source_observations(id) ON DELETE RESTRICT,
    revision_no bigint NOT NULL CHECK (revision_no > 0),
    version_key char(64) NOT NULL CHECK (version_key ~ '^[0-9a-f]{64}$'),
    body_origin varchar(48) NOT NULL CHECK (body_origin IN ('api_content','feed_content','feed_summary','structured_article_body','authorized_payload_extraction','platform_post','search_snippet')),
    completeness varchar(24) NOT NULL CHECK (completeness IN ('full','partial','summary','snippet','metadata_only','unknown')),
    word_count integer NOT NULL DEFAULT 0 CHECK (word_count >= 0),
    language varchar(32) NOT NULL DEFAULT 'und',
    truncated boolean NOT NULL DEFAULT false,
    quality_score numeric(5,2) CHECK (quality_score IS NULL OR quality_score BETWEEN 0 AND 100),
    quality_warnings text[] NOT NULL DEFAULT '{}',
    content_sha256 char(64) NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
    extractor_version varchar(64) NOT NULL,
    extractor_profile_version varchar(64) NOT NULL,
    extractor_profile_sha256 char(64) NOT NULL CHECK (extractor_profile_sha256 ~ '^[0-9a-f]{64}$'),
    display_private_rights_decision_id bigint REFERENCES source_rights_decisions(id) ON DELETE RESTRICT,
    lifecycle_state varchar(32) NOT NULL DEFAULT 'policy_pending'
        CHECK (lifecycle_state IN ('policy_pending','policy_blocked','derive_pending','derived_available','derive_failed','readable','retention_blocked','quarantined','tombstoned')),
    captured_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (document_id, revision_no),
    UNIQUE (document_id, version_key),
    UNIQUE (document_id, source_observation_id, content_sha256, extractor_profile_version),
    UNIQUE (id, document_id)
);
CREATE TABLE IF NOT EXISTS document_identity_keys (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    document_id bigint NOT NULL,
    identity_kind varchar(24) NOT NULL CHECK (identity_kind IN ('external_id','canonical_url','content_sha256')),
    identity_value text NOT NULL CHECK (octet_length(identity_value) BETWEEN 1 AND 2048),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_connection_id,identity_kind,identity_value),
    UNIQUE (id,source_connection_id)
);
ALTER TABLE document_identity_keys
    DROP CONSTRAINT IF EXISTS document_identity_keys_document_id_source_connection_id_fkey;
ALTER TABLE document_identity_keys
    DROP CONSTRAINT IF EXISTS document_identity_keys_document_source_fkey;
ALTER TABLE document_identity_keys
    ADD CONSTRAINT document_identity_keys_document_source_fkey
    FOREIGN KEY (document_id,source_connection_id) REFERENCES documents(id,source_connection_id) ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS document_identity_keys_document_idx
    ON document_identity_keys(document_id,identity_kind,id);
INSERT INTO document_identity_keys (source_connection_id,document_id,identity_kind,identity_value)
SELECT source_connection_id,id,'external_id',external_work_id
FROM documents
WHERE external_work_id IS NOT NULL
ORDER BY id
ON CONFLICT (source_connection_id,identity_kind,identity_value) DO NOTHING;
INSERT INTO document_identity_keys (source_connection_id,document_id,identity_kind,identity_value)
SELECT document.source_connection_id,document.id,'canonical_url',observation.canonical_url
FROM documents AS document
JOIN document_versions AS version ON version.document_id=document.id
JOIN source_observations AS observation ON observation.id=version.source_observation_id
WHERE observation.canonical_url IS NOT NULL
ORDER BY document.id,version.id
ON CONFLICT (source_connection_id,identity_kind,identity_value) DO NOTHING;
INSERT INTO document_identity_keys (source_connection_id,document_id,identity_kind,identity_value)
SELECT document.source_connection_id,document.id,'content_sha256',btrim(version.content_sha256)
FROM documents AS document
JOIN document_versions AS version ON version.document_id=document.id
WHERE version.completeness<>'metadata_only'
ORDER BY document.id,version.id
ON CONFLICT (source_connection_id,identity_kind,identity_value) DO NOTHING;
DROP TRIGGER IF EXISTS document_versions_lifecycle ON document_versions;
ALTER TABLE document_versions ADD COLUMN IF NOT EXISTS quality_score numeric(5,2);
ALTER TABLE document_versions ADD COLUMN IF NOT EXISTS extractor_profile_version varchar(64);
ALTER TABLE document_versions ADD COLUMN IF NOT EXISTS display_private_rights_decision_id bigint REFERENCES source_rights_decisions(id) ON DELETE RESTRICT;
ALTER TABLE document_versions DROP CONSTRAINT IF EXISTS document_versions_source_observation_id_key;
DO $$
DECLARE
    business_identity_constraint text;
BEGIN
    FOR business_identity_constraint IN
        SELECT constraint_record.conname
        FROM pg_constraint AS constraint_record
        JOIN pg_class AS relation ON relation.oid = constraint_record.conrelid
        JOIN pg_namespace AS namespace ON namespace.oid = relation.relnamespace
        WHERE namespace.nspname = 'public'
          AND relation.relname = 'document_versions'
          AND constraint_record.contype = 'u'
          AND pg_get_constraintdef(constraint_record.oid) =
              'UNIQUE (document_id, source_observation_id, content_sha256, extractor_profile_version)'
    LOOP
        EXECUTE format('ALTER TABLE document_versions DROP CONSTRAINT %I', business_identity_constraint);
    END LOOP;
END;
$$;
UPDATE document_versions
SET extractor_profile_version = extractor_version
WHERE extractor_profile_version IS NULL;
ALTER TABLE document_versions ALTER COLUMN extractor_profile_version SET NOT NULL;
ALTER TABLE document_versions DROP CONSTRAINT IF EXISTS document_versions_version_key_check;
