ALTER TABLE document_versions DROP CONSTRAINT IF EXISTS document_versions_extractor_profile_sha256_check;
ALTER TABLE document_versions ADD CONSTRAINT document_versions_extractor_profile_sha256_check
    CHECK (extractor_profile_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE document_versions DROP CONSTRAINT IF EXISTS document_versions_quality_score_check;
