ALTER TABLE documents DROP CONSTRAINT IF EXISTS documents_current_document_version_fkey;
ALTER TABLE documents ADD CONSTRAINT documents_current_document_version_fkey
    FOREIGN KEY (current_document_version_id, id) REFERENCES document_versions(id, document_id) ON DELETE RESTRICT;

CREATE TABLE IF NOT EXISTS derived_artifacts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_connection_id bigint NOT NULL REFERENCES source_connections(id) ON DELETE RESTRICT,
    document_version_id bigint NOT NULL REFERENCES document_versions(id) ON DELETE RESTRICT,
    store_derived_rights_decision_id bigint NOT NULL,
    retain_rights_decision_id bigint NOT NULL,
    rights_action varchar(32) NOT NULL DEFAULT 'store_derived' CHECK (rights_action = 'store_derived'),
    rights_decision varchar(8) NOT NULL DEFAULT 'allow' CHECK (rights_decision = 'allow'),
    retain_action varchar(32) NOT NULL DEFAULT 'retain' CHECK (retain_action = 'retain'),
    retain_decision varchar(8) NOT NULL DEFAULT 'allow' CHECK (retain_decision = 'allow'),
    artifact_type varchar(16) NOT NULL CHECK (artifact_type IN ('markdown','plaintext')),
    transformer_profile_sha256 char(64) NOT NULL CHECK (transformer_profile_sha256 ~ '^[0-9a-f]{64}$'),
    vault_relative_path text NOT NULL UNIQUE,
    mime_type varchar(64) NOT NULL,
    sha256 char(64) NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    size_bytes bigint NOT NULL CHECK (size_bytes > 0),
    anchor_normalization_version varchar(64),
    anchor_map_profile_version varchar(96),
    anchor_plaintext_sha256 char(64),
    anchor_markdown_sha256 char(64),
    anchor_map_sha256 char(64),
    lifecycle_state varchar(32) NOT NULL DEFAULT 'derive_pending'
        CHECK (lifecycle_state IN ('derive_pending','derived_available','derive_failed','retention_blocked','quarantined','tombstoned')),
    active boolean NOT NULL DEFAULT false,
    failure_code varchar(64),
    available_at timestamptz,
    retention_until timestamptz NOT NULL CHECK (retention_until > created_at),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (document_version_id, artifact_type, transformer_profile_sha256),
    CHECK (
        lifecycle_state = 'derived_available' AND available_at IS NOT NULL AND failure_code IS NULL
        OR lifecycle_state = 'derive_failed' AND available_at IS NULL AND failure_code IS NOT NULL
        OR lifecycle_state <> 'derived_available' AND lifecycle_state <> 'derive_failed' AND available_at IS NULL AND failure_code IS NULL
    ),
    CHECK (NOT active OR lifecycle_state = 'derived_available'),
    CHECK (
        artifact_type = 'markdown'
        AND anchor_normalization_version IS NOT NULL
        AND anchor_map_profile_version IS NOT NULL
        AND anchor_plaintext_sha256 ~ '^[0-9a-f]{64}$'
        AND anchor_markdown_sha256 = sha256
        AND anchor_map_sha256 ~ '^[0-9a-f]{64}$'
        OR artifact_type = 'plaintext'
        AND anchor_normalization_version IS NULL
        AND anchor_map_profile_version IS NULL
        AND anchor_plaintext_sha256 IS NULL
        AND anchor_markdown_sha256 IS NULL
        AND anchor_map_sha256 IS NULL
    ),
    CHECK (
        artifact_type = 'markdown' AND left(mime_type, 13) = 'text/markdown' AND right(vault_relative_path, 3) = '.md'
        OR artifact_type = 'plaintext' AND left(mime_type, 10) = 'text/plain' AND right(vault_relative_path, 4) = '.txt'
    )
);
DROP TRIGGER IF EXISTS derived_artifacts_lifecycle ON derived_artifacts;
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS source_connection_id bigint REFERENCES source_connections(id) ON DELETE RESTRICT;
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS store_derived_rights_decision_id bigint;
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS retain_rights_decision_id bigint;
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS rights_action varchar(32) NOT NULL DEFAULT 'store_derived';
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS rights_decision varchar(8) NOT NULL DEFAULT 'allow';
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS retain_action varchar(32) NOT NULL DEFAULT 'retain';
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS retain_decision varchar(8) NOT NULL DEFAULT 'allow';
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS retention_until timestamptz;
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS anchor_normalization_version varchar(64);
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS anchor_map_profile_version varchar(96);
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS anchor_plaintext_sha256 char(64);
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS anchor_markdown_sha256 char(64);
ALTER TABLE derived_artifacts ADD COLUMN IF NOT EXISTS anchor_map_sha256 char(64);
ALTER TABLE derived_artifacts ALTER COLUMN source_connection_id SET NOT NULL;
ALTER TABLE derived_artifacts ALTER COLUMN store_derived_rights_decision_id SET NOT NULL;
ALTER TABLE derived_artifacts ALTER COLUMN retain_rights_decision_id SET NOT NULL;
ALTER TABLE derived_artifacts ALTER COLUMN retention_until SET NOT NULL;
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_transformer_profile_sha256_check;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_transformer_profile_sha256_check
    CHECK (transformer_profile_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_sha256_check;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_sha256_check
    CHECK (sha256 ~ '^[0-9a-f]{64}$');
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'derived_artifacts'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) LIKE '%anchor_normalization_version%'
          AND pg_get_constraintdef(oid, true) LIKE '%anchor_map_sha256%'
    ) THEN
        ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_anchor_identity_check CHECK (
            artifact_type = 'markdown'
            AND anchor_normalization_version IS NOT NULL
            AND anchor_map_profile_version IS NOT NULL
            AND anchor_plaintext_sha256 ~ '^[0-9a-f]{64}$'
            AND anchor_markdown_sha256 = sha256
            AND anchor_map_sha256 ~ '^[0-9a-f]{64}$'
            OR artifact_type = 'plaintext'
            AND anchor_normalization_version IS NULL
            AND anchor_map_profile_version IS NULL
            AND anchor_plaintext_sha256 IS NULL
            AND anchor_markdown_sha256 IS NULL
            AND anchor_map_sha256 IS NULL
        ) NOT VALID;
    END IF;
END;
$$;
DO $$
DECLARE
    anchor_constraint_name text;
BEGIN
    FOR anchor_constraint_name IN
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = 'derived_artifacts'::regclass
          AND contype = 'c'
          AND NOT convalidated
          AND pg_get_constraintdef(oid, true) LIKE '%anchor_normalization_version%'
          AND pg_get_constraintdef(oid, true) LIKE '%anchor_map_sha256%'
    LOOP
        EXECUTE format('ALTER TABLE derived_artifacts VALIDATE CONSTRAINT %I', anchor_constraint_name);
    END LOOP;
END;
$$;
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_rights_action_check;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_rights_action_check CHECK (rights_action = 'store_derived');
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_rights_decision_check;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_rights_decision_check CHECK (rights_decision = 'allow');
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_retain_action_check;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_retain_action_check CHECK (retain_action = 'retain');
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_retain_decision_check;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_retain_decision_check CHECK (retain_decision = 'allow');
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_store_derived_rights_fk;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_store_derived_rights_fk
    FOREIGN KEY (store_derived_rights_decision_id, source_connection_id, rights_action, rights_decision)
    REFERENCES source_rights_decisions(id, source_connection_id, action, decision) ON DELETE RESTRICT;
ALTER TABLE derived_artifacts DROP CONSTRAINT IF EXISTS derived_artifacts_retain_rights_fk;
ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_retain_rights_fk
    FOREIGN KEY (retain_rights_decision_id, source_connection_id, retain_action, retain_decision)
    REFERENCES source_rights_decisions(id, source_connection_id, action, decision) ON DELETE RESTRICT;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'derived_artifacts'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) = 'CHECK (retention_until > created_at)'
    ) THEN
        ALTER TABLE derived_artifacts ADD CONSTRAINT derived_artifacts_retention_until_check
            CHECK (retention_until > created_at);
    END IF;
END;
$$;
CREATE UNIQUE INDEX IF NOT EXISTS derived_artifacts_one_active_per_type_uq
    ON derived_artifacts(document_version_id, artifact_type) WHERE active;
CREATE INDEX IF NOT EXISTS derived_artifacts_reconcile_idx
    ON derived_artifacts(lifecycle_state, updated_at, id);

CREATE TABLE IF NOT EXISTS document_anchor_blocks (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    derived_artifact_id bigint NOT NULL REFERENCES derived_artifacts(id) ON DELETE RESTRICT,
    anchor_map_sha256 char(64) NOT NULL CHECK (anchor_map_sha256 ~ '^[0-9a-f]{64}$'),
    block_ordinal integer NOT NULL CHECK (block_ordinal >= 0 AND block_ordinal < 20000),
    plaintext_utf8_byte_start bigint NOT NULL CHECK (plaintext_utf8_byte_start >= 0),
    plaintext_utf8_byte_end bigint NOT NULL CHECK (plaintext_utf8_byte_end > plaintext_utf8_byte_start),
    markdown_utf8_byte_start bigint NOT NULL CHECK (markdown_utf8_byte_start >= 0),
    markdown_utf8_byte_end bigint NOT NULL CHECK (markdown_utf8_byte_end > markdown_utf8_byte_start),
    markdown_anchor varchar(64) NOT NULL CHECK (markdown_anchor ~ '^body-[0-9]{4,5}-[0-9a-f]{12}$'),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (derived_artifact_id, block_ordinal),
    UNIQUE (derived_artifact_id, markdown_anchor)
);
CREATE INDEX IF NOT EXISTS document_anchor_blocks_plaintext_range_idx
    ON document_anchor_blocks(derived_artifact_id, plaintext_utf8_byte_start, plaintext_utf8_byte_end);
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = 'document_anchor_blocks'::regclass
          AND contype = 'f'
          AND confrelid = 'derived_artifacts'::regclass
    ) THEN
        EXECUTE 'ALTER TABLE document_anchor_blocks '
            'ADD CONSTRAINT document_anchor_blocks_derived_artifact_fk '
            'FOREIGN KEY (derived_artifact_id) REFERENCES derived_artifacts(id) ON DELETE RESTRICT';
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION enforce_document_anchor_block_immutability()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    artifact_record derived_artifacts%ROWTYPE;
    document_content_sha256 char(64);
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_anchor_blocks_immutable', MESSAGE = 'document anchor blocks are append-only';
    END IF;
    SELECT * INTO artifact_record FROM derived_artifacts WHERE id = NEW.derived_artifact_id FOR SHARE;
    IF artifact_record.id IS NULL
       OR artifact_record.artifact_type <> 'markdown'
       OR artifact_record.lifecycle_state NOT IN ('derive_pending','derived_available')
       OR artifact_record.anchor_map_sha256 IS DISTINCT FROM NEW.anchor_map_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_anchor_blocks_artifact', MESSAGE = 'document anchor block requires its exact Markdown artifact map';
    END IF;
    SELECT content_sha256 INTO document_content_sha256 FROM document_versions WHERE id = artifact_record.document_version_id;
    IF document_content_sha256 IS NULL OR artifact_record.anchor_plaintext_sha256 IS DISTINCT FROM document_content_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_anchor_blocks_plaintext', MESSAGE = 'document anchor block plaintext identity must match its document version';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS document_anchor_blocks_immutable ON document_anchor_blocks;
CREATE TRIGGER document_anchor_blocks_immutable
BEFORE INSERT OR UPDATE OR DELETE ON document_anchor_blocks
FOR EACH ROW EXECUTE FUNCTION enforce_document_anchor_block_immutability();

CREATE OR REPLACE FUNCTION enforce_source_rights_decision_batch_policy()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    policy_record source_rights_policies%ROWTYPE;
BEGIN
    SELECT * INTO policy_record FROM source_rights_policies WHERE id = NEW.policy_id;
    IF NOT FOUND OR policy_record.version IS DISTINCT FROM NEW.expected_policy_version THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decision_batches_policy_binding',
            MESSAGE = 'rights decision batch policy version is missing or changed';
    END IF;
    IF policy_record.scope_type <> 'organization_default'
       AND policy_record.source_connection_id IS DISTINCT FROM NEW.source_connection_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decision_batches_policy_source',
            MESSAGE = 'rights decision batch source does not match policy source';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS source_rights_decision_batches_policy_binding ON source_rights_decision_batches;
CREATE TRIGGER source_rights_decision_batches_policy_binding
BEFORE INSERT ON source_rights_decision_batches
FOR EACH ROW EXECUTE FUNCTION enforce_source_rights_decision_batch_policy();

CREATE OR REPLACE FUNCTION enforce_source_rights_decision_policy()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    policy_record source_rights_policies%ROWTYPE;
    superseded_record source_rights_decisions%ROWTYPE;
BEGIN
    SELECT * INTO policy_record FROM source_rights_policies WHERE id = NEW.policy_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_policy_binding', MESSAGE = 'rights decision policy is missing';
    END IF;
    IF NEW.policy_revision IS DISTINCT FROM policy_record.policy_revision
       OR NEW.policy_scope_type IS DISTINCT FROM policy_record.scope_type
       OR NEW.policy_scope_subject IS DISTINCT FROM policy_record.scope_subject
       OR NEW.priority_rank IS DISTINCT FROM policy_record.priority
       OR NEW.basis_summary IS DISTINCT FROM policy_record.basis_summary
       OR NEW.terms_url IS DISTINCT FROM policy_record.terms_url
       OR NEW.license_uri IS DISTINCT FROM policy_record.license_uri THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_policy_snapshot', MESSAGE = 'rights decision policy snapshot does not match immutable policy';
    END IF;
    IF NEW.decision = 'allow' AND policy_record.approved_by_user_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_policy_approval',
            MESSAGE = 'allow decision requires an approved immutable policy';
    END IF;
    IF policy_record.scope_type = 'organization_default' THEN
        IF policy_record.source_connection_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_policy_source', MESSAGE = 'organization policy source is invalid';
        END IF;
    ELSIF policy_record.source_connection_id IS DISTINCT FROM NEW.source_connection_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_policy_source', MESSAGE = 'rights decision source does not match policy source';
    END IF;
    IF NEW.subject_type = 'source_endpoint'
       AND (NEW.subject_key IS DISTINCT FROM NEW.source_connection_id::text
            OR NEW.input_digest IS DISTINCT FROM policy_record.policy_hash) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_endpoint_binding',
            MESSAGE = 'endpoint rights decision must bind the concrete source and immutable policy hash';
    END IF;
    IF NEW.effective_from < policy_record.effective_at
       OR (policy_record.expires_at IS NOT NULL AND (NEW.expires_at IS NULL OR NEW.expires_at > policy_record.expires_at)) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_policy_lifetime', MESSAGE = 'rights decision lifetime exceeds policy lifetime';
    END IF;
    IF NEW.supersedes_decision_id IS NOT NULL THEN
        SELECT * INTO superseded_record FROM source_rights_decisions WHERE id = NEW.supersedes_decision_id;
        IF NOT FOUND
           OR superseded_record.source_connection_id IS DISTINCT FROM NEW.source_connection_id
           OR superseded_record.subject_type IS DISTINCT FROM NEW.subject_type
           OR superseded_record.subject_key IS DISTINCT FROM NEW.subject_key
           OR superseded_record.input_digest IS DISTINCT FROM NEW.input_digest
           OR superseded_record.action IS DISTINCT FROM NEW.action THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decisions_supersession', MESSAGE = 'rights decision supersession identity is invalid';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS source_rights_decisions_policy_binding ON source_rights_decisions;
CREATE TRIGGER source_rights_decisions_policy_binding
BEFORE INSERT ON source_rights_decisions
FOR EACH ROW EXECUTE FUNCTION enforce_source_rights_decision_policy();

CREATE OR REPLACE FUNCTION enforce_source_rights_decision_batch_completeness()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    persisted_count integer;
BEGIN
    SELECT count(*) INTO persisted_count
    FROM source_rights_decisions
    WHERE decision_batch_id = NEW.id;
    IF persisted_count IS DISTINCT FROM NEW.decision_count THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'source_rights_decision_batches_complete',
            MESSAGE = 'rights decision batch must commit exactly its declared single-action decisions';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS source_rights_decision_batches_complete ON source_rights_decision_batches;
CREATE CONSTRAINT TRIGGER source_rights_decision_batches_complete
AFTER INSERT ON source_rights_decision_batches
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION enforce_source_rights_decision_batch_completeness();

CREATE OR REPLACE FUNCTION current_rights_action_is_allowed(
    selected_source_connection_id bigint,
    selected_subject_type varchar,
    selected_subject_key varchar,
    selected_input_digest char(64),
    selected_action varchar,
    decision_at timestamptz
)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
WITH terminal AS (
    SELECT decision.*
    FROM source_rights_decisions AS decision
    WHERE decision.source_connection_id = selected_source_connection_id
      AND (
          (decision.subject_type = selected_subject_type
           AND decision.subject_key = selected_subject_key
           AND decision.input_digest = selected_input_digest)
          OR
          (decision.subject_type = 'source_endpoint'
           AND decision.subject_key = selected_source_connection_id::text
           AND EXISTS (
               SELECT 1 FROM source_rights_policies AS policy
               WHERE policy.id = decision.policy_id
                 AND policy.policy_hash = decision.input_digest
           ))
      )
      AND decision.action = selected_action
      AND decision.effective_from <= decision_at
      AND (decision.expires_at IS NULL OR decision_at < decision.expires_at)
      AND NOT EXISTS (
          SELECT 1 FROM source_rights_decisions AS superseding
          WHERE superseding.supersedes_decision_id = decision.id
            AND superseding.effective_from <= decision_at
      )
), highest AS (
    SELECT max(priority_rank) AS priority_rank FROM terminal
)
SELECT EXISTS (SELECT 1 FROM terminal, highest WHERE terminal.priority_rank = highest.priority_rank)
AND NOT EXISTS (
    SELECT 1 FROM terminal, highest
    WHERE terminal.priority_rank = highest.priority_rank AND terminal.decision <> 'allow'
)
$$;

CREATE OR REPLACE FUNCTION current_rights_retention_days(
    selected_source_connection_id bigint,
    selected_subject_type varchar,
    selected_subject_key varchar,
    selected_input_digest char(64),
    decision_at timestamptz
)
RETURNS integer
LANGUAGE sql
STABLE
AS $$
WITH terminal AS (
    SELECT decision.*
    FROM source_rights_decisions AS decision
    WHERE decision.source_connection_id = selected_source_connection_id
      AND (
          (decision.subject_type = selected_subject_type
           AND decision.subject_key = selected_subject_key
           AND decision.input_digest = selected_input_digest)
          OR
          (decision.subject_type = 'source_endpoint'
           AND decision.subject_key = selected_source_connection_id::text
           AND EXISTS (
               SELECT 1 FROM source_rights_policies AS policy
               WHERE policy.id = decision.policy_id
                 AND policy.policy_hash = decision.input_digest
           ))
      )
      AND decision.action = 'retain'
      AND decision.effective_from <= decision_at
      AND (decision.expires_at IS NULL OR decision_at < decision.expires_at)
      AND NOT EXISTS (
          SELECT 1 FROM source_rights_decisions AS superseding
          WHERE superseding.supersedes_decision_id = decision.id
            AND superseding.effective_from <= decision_at
      )
), highest AS (
    SELECT max(priority_rank) AS priority_rank FROM terminal
)
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM terminal, highest WHERE terminal.priority_rank = highest.priority_rank)
     AND NOT EXISTS (SELECT 1 FROM terminal, highest WHERE terminal.priority_rank = highest.priority_rank AND terminal.decision <> 'allow')
    THEN (SELECT min(retention_days) FROM terminal, highest WHERE terminal.priority_rank = highest.priority_rank)
END
$$;

CREATE OR REPLACE FUNCTION current_rights_action_allowed(
    selected_decision_id bigint,
    selected_source_connection_id bigint,
    selected_subject_type varchar,
    selected_subject_key varchar,
    selected_input_digest char(64),
    selected_action varchar,
    decision_at timestamptz
)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
WITH terminal AS (
    SELECT decision.*
    FROM source_rights_decisions AS decision
    WHERE decision.source_connection_id = selected_source_connection_id
      AND (
          (decision.subject_type = selected_subject_type
           AND decision.subject_key = selected_subject_key
           AND decision.input_digest = selected_input_digest)
          OR
          (decision.subject_type = 'source_endpoint'
           AND decision.subject_key = selected_source_connection_id::text
           AND EXISTS (
               SELECT 1 FROM source_rights_policies AS policy
               WHERE policy.id = decision.policy_id
                 AND policy.policy_hash = decision.input_digest
           ))
      )
      AND decision.action = selected_action
      AND decision.effective_from <= decision_at
      AND (decision.expires_at IS NULL OR decision_at < decision.expires_at)
      AND NOT EXISTS (
          SELECT 1
          FROM source_rights_decisions AS superseding
          WHERE superseding.supersedes_decision_id = decision.id
            AND superseding.effective_from <= decision_at
      )
), highest AS (
    SELECT max(priority_rank) AS priority_rank FROM terminal
)
SELECT EXISTS (
    SELECT 1 FROM terminal, highest
    WHERE terminal.id = selected_decision_id
      AND terminal.decision = 'allow'
      AND terminal.priority_rank = highest.priority_rank
)
AND current_rights_action_is_allowed(
    selected_source_connection_id, selected_subject_type, selected_subject_key,
    selected_input_digest, selected_action, decision_at
)
$$;

CREATE OR REPLACE FUNCTION enforce_evidence_snapshot_rights_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    retained_days integer;
    selected_retained_days integer;
BEGIN
    IF NOT current_rights_action_allowed(
        NEW.store_raw_rights_decision_id, NEW.source_connection_id, 'raw_response',
        btrim(NEW.snapshot_key), NEW.payload_sha256, 'store_raw', CURRENT_TIMESTAMP
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_store_raw_rights_binding', MESSAGE = 'evidence snapshot requires exact current store_raw allow';
    END IF;
    IF NOT current_rights_action_allowed(
        NEW.retain_rights_decision_id, NEW.source_connection_id, 'raw_response',
        btrim(NEW.snapshot_key), NEW.payload_sha256, 'retain', CURRENT_TIMESTAMP
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_retain_rights_binding', MESSAGE = 'evidence snapshot requires exact current retain allow';
    END IF;
    retained_days := current_rights_retention_days(
        NEW.source_connection_id, 'raw_response', btrim(NEW.snapshot_key),
        NEW.payload_sha256, CURRENT_TIMESTAMP
    );
    SELECT retention_days INTO selected_retained_days
    FROM source_rights_decisions WHERE id = NEW.retain_rights_decision_id;
    IF retained_days IS NULL OR selected_retained_days IS DISTINCT FROM retained_days THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_retain_rights_binding', MESSAGE = 'evidence snapshot retain receipt is not the current conservative allow';
    END IF;
    IF NEW.retention_until IS DISTINCT FROM NEW.captured_at + retained_days * interval '24 hours' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_retention_lifetime', MESSAGE = 'evidence snapshot retention does not match retain decision';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS evidence_snapshots_rights_binding ON evidence_snapshots;
CREATE TRIGGER evidence_snapshots_rights_binding
BEFORE INSERT ON evidence_snapshots
FOR EACH ROW EXECUTE FUNCTION enforce_evidence_snapshot_rights_binding();

CREATE OR REPLACE FUNCTION enforce_document_version_source_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    document_source_connection_id bigint;
    observation_source_connection_id bigint;
BEGIN
    SELECT source_connection_id INTO document_source_connection_id
    FROM documents WHERE id = NEW.document_id;
    SELECT source_connection_id INTO observation_source_connection_id
    FROM source_observations WHERE id = NEW.source_observation_id;
    IF document_source_connection_id IS NULL
       OR observation_source_connection_id IS NULL
       OR document_source_connection_id IS DISTINCT FROM observation_source_connection_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_versions_source_lineage', MESSAGE = 'document version source does not match source observation';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS document_versions_source_binding ON document_versions;
CREATE TRIGGER document_versions_source_binding
BEFORE INSERT ON document_versions
FOR EACH ROW EXECUTE FUNCTION enforce_document_version_source_binding();

CREATE OR REPLACE FUNCTION enforce_derived_artifact_rights_binding()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    document_id_value bigint;
    document_source_connection_id bigint;
    document_content_sha256 char(64);
    document_captured_at timestamptz;
    retained_days integer;
    selected_retained_days integer;
BEGIN
    SELECT document.id, document.source_connection_id, version.content_sha256, version.captured_at
    INTO document_id_value, document_source_connection_id, document_content_sha256, document_captured_at
    FROM document_versions AS version
    JOIN documents AS document ON document.id = version.document_id
    WHERE version.id = NEW.document_version_id;
    IF NOT FOUND OR document_source_connection_id IS DISTINCT FROM NEW.source_connection_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_document_source', MESSAGE = 'derived artifact source does not match document version';
    END IF;
    IF NEW.vault_relative_path IS DISTINCT FROM format(
        'documents/%s/%s/%s/%s.%s', document_id_value, NEW.document_version_id,
        NEW.artifact_type, btrim(NEW.transformer_profile_sha256),
        CASE NEW.artifact_type WHEN 'markdown' THEN 'md' WHEN 'plaintext' THEN 'txt' ELSE '' END
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_vault_path', MESSAGE = 'derived artifact Vault path does not match immutable identity';
    END IF;
    IF NOT current_rights_action_allowed(
        NEW.store_derived_rights_decision_id, NEW.source_connection_id, 'document_version',
        NEW.document_version_id::text, document_content_sha256, 'store_derived', CURRENT_TIMESTAMP
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_store_derived_rights_binding', MESSAGE = 'derived artifact requires exact current store_derived allow';
    END IF;
    IF NOT current_rights_action_allowed(
        NEW.retain_rights_decision_id, NEW.source_connection_id, 'document_version',
        NEW.document_version_id::text, document_content_sha256, 'retain', CURRENT_TIMESTAMP
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_retain_rights_binding', MESSAGE = 'derived artifact requires exact current retain allow';
    END IF;
    retained_days := current_rights_retention_days(
        NEW.source_connection_id, 'document_version', NEW.document_version_id::text,
        document_content_sha256, CURRENT_TIMESTAMP
    );
    SELECT retention_days INTO selected_retained_days
    FROM source_rights_decisions WHERE id = NEW.retain_rights_decision_id;
    IF retained_days IS NULL OR selected_retained_days IS DISTINCT FROM retained_days THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_retain_rights_binding', MESSAGE = 'derived artifact retain receipt is not the current conservative allow';
    END IF;
    IF NEW.retention_until IS DISTINCT FROM document_captured_at + retained_days * interval '24 hours' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_retention_lifetime', MESSAGE = 'derived artifact retention does not match retain decision';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS derived_artifacts_rights_binding ON derived_artifacts;
CREATE TRIGGER derived_artifacts_rights_binding
BEFORE INSERT ON derived_artifacts
FOR EACH ROW EXECUTE FUNCTION enforce_derived_artifact_rights_binding();

CREATE OR REPLACE FUNCTION reject_immutable_evidence_fact_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'immutable_evidence_fact_mutation', MESSAGE = 'policy, decision, observation, and locator facts are append-only';
END;
$$;

DROP TRIGGER IF EXISTS source_rights_policies_append_only ON source_rights_policies;
CREATE TRIGGER source_rights_policies_append_only
BEFORE UPDATE OR DELETE ON source_rights_policies
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS source_rights_decision_batches_append_only ON source_rights_decision_batches;
CREATE TRIGGER source_rights_decision_batches_append_only
BEFORE UPDATE OR DELETE ON source_rights_decision_batches
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS source_rights_decisions_append_only ON source_rights_decisions;
CREATE TRIGGER source_rights_decisions_append_only
BEFORE UPDATE OR DELETE ON source_rights_decisions
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS source_observations_append_only ON source_observations;
CREATE TRIGGER source_observations_append_only
BEFORE UPDATE OR DELETE ON source_observations
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS source_observation_evidences_append_only ON source_observation_evidences;
CREATE TRIGGER source_observation_evidences_append_only
BEFORE UPDATE OR DELETE ON source_observation_evidences
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS source_parties_append_only ON source_parties;
CREATE TRIGGER source_parties_append_only
BEFORE UPDATE OR DELETE ON source_parties
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS source_observation_parties_append_only ON source_observation_parties;
CREATE TRIGGER source_observation_parties_append_only
BEFORE UPDATE OR DELETE ON source_observation_parties
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();
DROP TRIGGER IF EXISTS evidence_deletion_audits_append_only ON evidence_deletion_audits;
CREATE TRIGGER evidence_deletion_audits_append_only
BEFORE UPDATE OR DELETE ON evidence_deletion_audits
FOR EACH ROW EXECUTE FUNCTION reject_immutable_evidence_fact_mutation();

CREATE OR REPLACE FUNCTION enforce_evidence_snapshot_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    retained_days integer;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_retained', MESSAGE = 'evidence snapshots cannot be deleted';
    END IF;
    IF NEW.source_connection_id IS DISTINCT FROM OLD.source_connection_id
       OR NEW.collection_run_id IS DISTINCT FROM OLD.collection_run_id
       OR NEW.store_raw_rights_decision_id IS DISTINCT FROM OLD.store_raw_rights_decision_id
       OR NEW.retain_rights_decision_id IS DISTINCT FROM OLD.retain_rights_decision_id
       OR NEW.rights_action IS DISTINCT FROM OLD.rights_action
       OR NEW.rights_decision IS DISTINCT FROM OLD.rights_decision
       OR NEW.retain_action IS DISTINCT FROM OLD.retain_action
       OR NEW.retain_decision IS DISTINCT FROM OLD.retain_decision
       OR NEW.snapshot_key IS DISTINCT FROM OLD.snapshot_key
       OR NEW.object_key IS DISTINCT FROM OLD.object_key
       OR NEW.payload_sha256 IS DISTINCT FROM OLD.payload_sha256
       OR NEW.collector_profile_version IS DISTINCT FROM OLD.collector_profile_version
       OR NEW.mime_type IS DISTINCT FROM OLD.mime_type
       OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes
       OR NEW.response_status IS DISTINCT FROM OLD.response_status
       OR NEW.requested_url IS DISTINCT FROM OLD.requested_url
       OR NEW.final_url IS DISTINCT FROM OLD.final_url
       OR NEW.redirect_chain IS DISTINCT FROM OLD.redirect_chain
       OR NEW.response_headers IS DISTINCT FROM OLD.response_headers
       OR NEW.captured_at IS DISTINCT FROM OLD.captured_at
       OR NEW.retention_until IS DISTINCT FROM OLD.retention_until
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_identity_immutable', MESSAGE = 'evidence snapshot identity is immutable';
    END IF;
    IF NEW.lifecycle_state IN ('raw_pending','raw_available') THEN
        retained_days := current_rights_retention_days(
            NEW.source_connection_id, 'raw_response', btrim(NEW.snapshot_key),
            NEW.payload_sha256, CURRENT_TIMESTAMP
        );
        IF NOT current_rights_action_is_allowed(
               NEW.source_connection_id, 'raw_response', btrim(NEW.snapshot_key),
               NEW.payload_sha256, 'store_raw', CURRENT_TIMESTAMP
           )
           OR retained_days IS NULL
           OR NEW.retention_until > NEW.captured_at + retained_days * interval '24 hours'
           OR NEW.retention_until <= CURRENT_TIMESTAMP THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_current_rights_gate', MESSAGE = 'evidence snapshot lifecycle requires current store_raw and retain allows';
        END IF;
    END IF;
    IF NOT (
        OLD.lifecycle_state = NEW.lifecycle_state
        OR OLD.lifecycle_state = 'policy_pending' AND NEW.lifecycle_state IN ('policy_blocked','raw_pending','quarantined')
        OR OLD.lifecycle_state = 'raw_pending' AND NEW.lifecycle_state IN ('raw_available','raw_failed','policy_blocked','quarantined')
        OR OLD.lifecycle_state = 'raw_failed' AND NEW.lifecycle_state IN ('raw_pending','quarantined','tombstoned')
        OR OLD.lifecycle_state = 'raw_available' AND NEW.lifecycle_state IN ('policy_blocked','retention_blocked','quarantined','tombstoned')
        OR OLD.lifecycle_state = 'policy_blocked' AND NEW.lifecycle_state IN ('raw_pending','quarantined','tombstoned')
        OR OLD.lifecycle_state IN ('retention_blocked','quarantined') AND NEW.lifecycle_state = 'tombstoned'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_snapshots_lifecycle_transition', MESSAGE = 'invalid evidence snapshot lifecycle transition';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS evidence_snapshots_lifecycle ON evidence_snapshots;
CREATE TRIGGER evidence_snapshots_lifecycle
BEFORE UPDATE OR DELETE ON evidence_snapshots
FOR EACH ROW EXECUTE FUNCTION enforce_evidence_snapshot_lifecycle();

CREATE OR REPLACE FUNCTION enforce_document_version_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_versions_retained', MESSAGE = 'document versions cannot be deleted';
    END IF;
    IF NEW.document_id IS DISTINCT FROM OLD.document_id
       OR NEW.source_observation_id IS DISTINCT FROM OLD.source_observation_id
       OR NEW.revision_no IS DISTINCT FROM OLD.revision_no
       OR NEW.version_key IS DISTINCT FROM OLD.version_key
       OR NEW.body_origin IS DISTINCT FROM OLD.body_origin
       OR NEW.completeness IS DISTINCT FROM OLD.completeness
       OR NEW.word_count IS DISTINCT FROM OLD.word_count
       OR NEW.language IS DISTINCT FROM OLD.language
       OR NEW.truncated IS DISTINCT FROM OLD.truncated
       OR NEW.quality_score IS DISTINCT FROM OLD.quality_score
       OR NEW.quality_warnings IS DISTINCT FROM OLD.quality_warnings
       OR NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256
       OR NEW.extractor_version IS DISTINCT FROM OLD.extractor_version
       OR NEW.extractor_profile_version IS DISTINCT FROM OLD.extractor_profile_version
       OR NEW.extractor_profile_sha256 IS DISTINCT FROM OLD.extractor_profile_sha256
       OR NEW.captured_at IS DISTINCT FROM OLD.captured_at
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_versions_content_immutable', MESSAGE = 'document version content and provenance are immutable';
    END IF;
    IF NEW.display_private_rights_decision_id IS DISTINCT FROM OLD.display_private_rights_decision_id
       AND NEW.lifecycle_state <> 'readable' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_versions_display_decision_transition', MESSAGE = 'display decision can change only while entering readable';
    END IF;
    IF NEW.lifecycle_state = 'readable' THEN
        IF NEW.display_private_rights_decision_id IS NULL
           OR NOT current_rights_action_allowed(
               NEW.display_private_rights_decision_id,
               (SELECT source_connection_id FROM documents WHERE id = NEW.document_id),
               'document_version', NEW.id::text, NEW.content_sha256, 'display_private', CURRENT_TIMESTAMP
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_version_readable_rights', MESSAGE = 'readable document version requires exact current display_private allow';
        END IF;
        IF NOT EXISTS (
            SELECT 1
            FROM derived_artifacts AS artifact
            JOIN documents AS document ON document.id = NEW.document_id
            WHERE artifact.document_version_id = NEW.id
              AND artifact.source_connection_id = document.source_connection_id
              AND artifact.artifact_type = 'markdown'
              AND artifact.anchor_plaintext_sha256 = NEW.content_sha256
              AND artifact.anchor_markdown_sha256 = artifact.sha256
              AND artifact.anchor_map_sha256 IS NOT NULL
              AND artifact.lifecycle_state = 'derived_available'
              AND artifact.active
              AND artifact.available_at IS NOT NULL
              AND artifact.failure_code IS NULL
              AND artifact.retention_until > CURRENT_TIMESTAMP
              AND current_rights_action_is_allowed(
                  artifact.source_connection_id, 'document_version', artifact.document_version_id::text,
                  NEW.content_sha256, 'store_derived', CURRENT_TIMESTAMP
              )
              AND current_rights_retention_days(
                  artifact.source_connection_id, 'document_version', artifact.document_version_id::text,
                  NEW.content_sha256, CURRENT_TIMESTAMP
              ) IS NOT NULL
              AND artifact.retention_until <= NEW.captured_at + current_rights_retention_days(
                  artifact.source_connection_id, 'document_version', artifact.document_version_id::text,
                  NEW.content_sha256, CURRENT_TIMESTAMP
              ) * interval '24 hours'
              AND EXISTS (
                  SELECT 1 FROM document_anchor_blocks AS anchor
                  WHERE anchor.derived_artifact_id = artifact.id
                    AND anchor.anchor_map_sha256 = artifact.anchor_map_sha256
              )
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_version_readable_artifact', MESSAGE = 'readable document version requires an active healthy retained artifact';
        END IF;
    END IF;
    IF NOT (
        OLD.lifecycle_state = 'policy_pending' AND NEW.lifecycle_state IN ('policy_blocked','derive_pending','quarantined')
        OR OLD.lifecycle_state = 'derive_pending' AND NEW.lifecycle_state IN ('derived_available','derive_failed','policy_blocked','quarantined')
        OR OLD.lifecycle_state = 'derive_failed' AND NEW.lifecycle_state IN ('derive_pending','quarantined','tombstoned')
        OR OLD.lifecycle_state = 'derived_available' AND NEW.lifecycle_state IN ('readable','policy_blocked','quarantined','tombstoned')
        OR OLD.lifecycle_state = 'readable' AND NEW.lifecycle_state IN ('policy_blocked','retention_blocked','quarantined','tombstoned')
        OR OLD.lifecycle_state = 'policy_blocked' AND NEW.lifecycle_state IN ('derive_pending','readable','quarantined','tombstoned')
        OR OLD.lifecycle_state IN ('policy_blocked','retention_blocked','quarantined') AND NEW.lifecycle_state = 'tombstoned'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'document_versions_lifecycle_transition', MESSAGE = 'invalid document version lifecycle transition';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS document_versions_lifecycle ON document_versions;
CREATE TRIGGER document_versions_lifecycle
BEFORE UPDATE OR DELETE ON document_versions
FOR EACH ROW EXECUTE FUNCTION enforce_document_version_lifecycle();

CREATE OR REPLACE FUNCTION enforce_derived_artifact_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    document_content_sha256 char(64);
    document_captured_at timestamptz;
    retained_days integer;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_retained', MESSAGE = 'derived artifacts cannot be deleted';
    END IF;
    IF NEW.document_version_id IS DISTINCT FROM OLD.document_version_id
       OR NEW.source_connection_id IS DISTINCT FROM OLD.source_connection_id
       OR NEW.store_derived_rights_decision_id IS DISTINCT FROM OLD.store_derived_rights_decision_id
       OR NEW.retain_rights_decision_id IS DISTINCT FROM OLD.retain_rights_decision_id
       OR NEW.rights_action IS DISTINCT FROM OLD.rights_action
       OR NEW.rights_decision IS DISTINCT FROM OLD.rights_decision
       OR NEW.retain_action IS DISTINCT FROM OLD.retain_action
       OR NEW.retain_decision IS DISTINCT FROM OLD.retain_decision
       OR NEW.artifact_type IS DISTINCT FROM OLD.artifact_type
       OR NEW.transformer_profile_sha256 IS DISTINCT FROM OLD.transformer_profile_sha256
       OR NEW.vault_relative_path IS DISTINCT FROM OLD.vault_relative_path
       OR NEW.mime_type IS DISTINCT FROM OLD.mime_type
       OR NEW.sha256 IS DISTINCT FROM OLD.sha256
       OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes
       OR NEW.anchor_normalization_version IS DISTINCT FROM OLD.anchor_normalization_version
       OR NEW.anchor_map_profile_version IS DISTINCT FROM OLD.anchor_map_profile_version
       OR NEW.anchor_plaintext_sha256 IS DISTINCT FROM OLD.anchor_plaintext_sha256
       OR NEW.anchor_markdown_sha256 IS DISTINCT FROM OLD.anchor_markdown_sha256
       OR NEW.anchor_map_sha256 IS DISTINCT FROM OLD.anchor_map_sha256
       OR NEW.retention_until IS DISTINCT FROM OLD.retention_until
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_identity_immutable', MESSAGE = 'derived artifact identity is immutable';
    END IF;
    IF NEW.lifecycle_state IN ('derive_pending','derived_available') THEN
        SELECT content_sha256, captured_at
        INTO document_content_sha256, document_captured_at
        FROM document_versions WHERE id = NEW.document_version_id;
        retained_days := current_rights_retention_days(
            NEW.source_connection_id, 'document_version', NEW.document_version_id::text,
            document_content_sha256, CURRENT_TIMESTAMP
        );
        IF document_content_sha256 IS NULL
           OR NOT current_rights_action_is_allowed(
               NEW.source_connection_id, 'document_version', NEW.document_version_id::text,
               document_content_sha256, 'store_derived', CURRENT_TIMESTAMP
           )
           OR retained_days IS NULL
           OR NEW.retention_until > document_captured_at + retained_days * interval '24 hours'
           OR NEW.retention_until <= CURRENT_TIMESTAMP THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_current_rights_gate', MESSAGE = 'derived artifact lifecycle requires current store_derived and retain allows';
        END IF;
    END IF;
    IF NOT (
        OLD.lifecycle_state = NEW.lifecycle_state
        OR OLD.lifecycle_state = 'derive_pending' AND NEW.lifecycle_state IN ('derived_available','derive_failed','quarantined')
        OR OLD.lifecycle_state = 'derive_failed' AND NEW.lifecycle_state IN ('derive_pending','quarantined','tombstoned')
        OR OLD.lifecycle_state = 'derived_available' AND NEW.lifecycle_state IN ('retention_blocked','quarantined','tombstoned')
        OR OLD.lifecycle_state IN ('retention_blocked','quarantined') AND NEW.lifecycle_state = 'tombstoned'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'derived_artifacts_lifecycle_transition', MESSAGE = 'invalid derived artifact lifecycle transition';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS derived_artifacts_lifecycle ON derived_artifacts;
CREATE TRIGGER derived_artifacts_lifecycle
BEFORE UPDATE OR DELETE ON derived_artifacts
FOR EACH ROW EXECUTE FUNCTION enforce_derived_artifact_lifecycle();

CREATE TABLE IF NOT EXISTS content_metric_snapshots (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT,
    captured_at timestamptz NOT NULL, view_count bigint CHECK (view_count >= 0), like_count bigint CHECK (like_count >= 0),
    comment_count bigint CHECK (comment_count >= 0), share_count bigint CHECK (share_count >= 0),
    extra_metrics jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (content_id, captured_at)
);

CREATE TABLE IF NOT EXISTS event_metric_snapshots (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
    captured_at timestamptz NOT NULL, heat_score numeric(7,2) NOT NULL CHECK (heat_score >= 0), trend_score numeric(7,2) NOT NULL,
    source_count bigint NOT NULL DEFAULT 0 CHECK (source_count >= 0), content_count bigint NOT NULL DEFAULT 0 CHECK (content_count >= 0),
    heat_version varchar(64) NOT NULL DEFAULT 'v1', evidence_set_hash char(64) NOT NULL DEFAULT repeat('0', 64),
    capability_profile_set_hash char(64) NOT NULL DEFAULT repeat('0', 64), window_hours smallint NOT NULL DEFAULT 24 CHECK (window_hours IN (1,6,24)),
    trend_status varchar(16) NOT NULL DEFAULT 'stable' CHECK (trend_status IN ('emerging','rising','stable','falling','dormant')),
	component_scores jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(component_scores) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE event_metric_snapshots ADD COLUMN IF NOT EXISTS heat_version varchar(64) NOT NULL DEFAULT 'v1';
ALTER TABLE event_metric_snapshots ADD COLUMN IF NOT EXISTS evidence_set_hash char(64) NOT NULL DEFAULT repeat('0', 64);
ALTER TABLE event_metric_snapshots ADD COLUMN IF NOT EXISTS capability_profile_set_hash char(64) NOT NULL DEFAULT repeat('0', 64);
ALTER TABLE event_metric_snapshots ADD COLUMN IF NOT EXISTS window_hours smallint NOT NULL DEFAULT 24;
ALTER TABLE event_metric_snapshots ADD COLUMN IF NOT EXISTS trend_status varchar(16) NOT NULL DEFAULT 'stable';
ALTER TABLE event_metric_snapshots ADD COLUMN IF NOT EXISTS component_scores jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE event_metric_snapshots DROP CONSTRAINT IF EXISTS event_metric_snapshots_window_hours_check;
ALTER TABLE event_metric_snapshots ADD CONSTRAINT event_metric_snapshots_window_hours_check CHECK (window_hours IN (1,6,24));
ALTER TABLE event_metric_snapshots DROP CONSTRAINT IF EXISTS event_metric_snapshots_trend_status_check;
ALTER TABLE event_metric_snapshots ADD CONSTRAINT event_metric_snapshots_trend_status_check CHECK (trend_status IN ('emerging','rising','stable','falling','dormant'));
ALTER TABLE event_metric_snapshots DROP CONSTRAINT IF EXISTS event_metric_snapshots_component_scores_check;
ALTER TABLE event_metric_snapshots ADD CONSTRAINT event_metric_snapshots_component_scores_check CHECK (jsonb_typeof(component_scores) = 'object');
ALTER TABLE event_metric_snapshots DROP CONSTRAINT IF EXISTS event_metric_snapshots_event_id_captured_at_key;
DROP INDEX IF EXISTS event_metric_snapshots_version_uq;
CREATE UNIQUE INDEX IF NOT EXISTS event_metric_snapshots_version_uq
    ON event_metric_snapshots(event_id, captured_at, window_hours, heat_version, evidence_set_hash, capability_profile_set_hash);

-- EventUpdate is the immutable product timeline for material changes. It is
-- separate from mutable Event projections and from operator audit records.
CREATE TABLE IF NOT EXISTS event_updates (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
    sequence_no bigint NOT NULL CHECK (sequence_no > 0),
    kind varchar(32) NOT NULL CHECK (kind IN ('event_created','rising','cooling','reactivated','source_expansion','metric_changed')),
    summary text NOT NULL CHECK (octet_length(summary) >= 1 AND octet_length(summary) <= 2000),
    observed_at timestamptz NOT NULL,
    reason_codes text[] NOT NULL DEFAULT '{}',
    before_state jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(before_state) = 'object'),
    after_state jsonb NOT NULL CHECK (jsonb_typeof(after_state) = 'object'),
    evidence_set_hash char(64) NOT NULL,
    idempotency_key char(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (event_id, sequence_no),
    UNIQUE (event_id, idempotency_key)
);
CREATE INDEX IF NOT EXISTS event_updates_timeline_idx
    ON event_updates(event_id, sequence_no DESC, id DESC);
CREATE INDEX IF NOT EXISTS event_updates_observed_idx
    ON event_updates(observed_at DESC, id DESC);
ALTER TABLE report_items DROP CONSTRAINT IF EXISTS report_items_event_update_id_fkey;
ALTER TABLE report_items ADD CONSTRAINT report_items_event_update_id_fkey
    FOREIGN KEY (event_update_id) REFERENCES event_updates(id) ON DELETE RESTRICT;

-- Alert threads are the only mutable records in the alert aggregate. Each
-- thread freezes the published Monitor revision that made the trigger valid.
CREATE TABLE IF NOT EXISTS alert_threads (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    monitor_id bigint NOT NULL REFERENCES monitors(id) ON DELETE RESTRICT,
    monitor_config_version_id bigint NOT NULL,
    monitor_revision bigint NOT NULL CHECK (monitor_revision > 0),
    monitor_config_hash char(64) NOT NULL,
    event_id bigint NOT NULL REFERENCES events(id) ON DELETE RESTRICT,
    trigger_type varchar(32) NOT NULL CHECK (trigger_type IN ('new_event','rising','reactivated','threshold_crossed')),
    policy_version varchar(64) NOT NULL,
    state varchar(16) NOT NULL DEFAULT 'open' CHECK (state IN ('open','acknowledged','resolved','suppressed')),
    severity varchar(16) NOT NULL CHECK (severity IN ('info','warning','critical')),
    event_threshold_snapshot numeric(5,2) NOT NULL CHECK (event_threshold_snapshot BETWEEN 0 AND 100),
    alert_min_heat_snapshot numeric(5,2) NOT NULL DEFAULT 0 CHECK (alert_min_heat_snapshot BETWEEN 0 AND 100),
    alert_min_momentum_snapshot numeric(5,2) NOT NULL DEFAULT 0 CHECK (alert_min_momentum_snapshot BETWEEN 0 AND 100),
    alert_min_breadth_snapshot numeric(5,2) NOT NULL DEFAULT 0 CHECK (alert_min_breadth_snapshot BETWEEN 0 AND 100),
    alert_warning_threshold_snapshot numeric(5,2) NOT NULL DEFAULT 75 CHECK (alert_warning_threshold_snapshot BETWEEN 0 AND 100),
    alert_critical_threshold_snapshot numeric(5,2) NOT NULL DEFAULT 90 CHECK (alert_critical_threshold_snapshot BETWEEN alert_warning_threshold_snapshot AND 100),
    alert_cooldown_minutes_snapshot integer NOT NULL DEFAULT 60 CHECK (alert_cooldown_minutes_snapshot BETWEEN 5 AND 1440),
    title_snapshot text NOT NULL CHECK (octet_length(title_snapshot) >= 1 AND octet_length(title_snapshot) <= 1000),
    reason_snapshot text NOT NULL DEFAULT '' CHECK (octet_length(reason_snapshot) <= 2000),
    first_triggered_at timestamptz NOT NULL,
    last_triggered_at timestamptz NOT NULL,
    occurrence_count bigint NOT NULL DEFAULT 0 CHECK (occurrence_count >= 0),
    cooldown_until timestamptz NOT NULL,
    acknowledged_at timestamptz,
    acknowledged_by_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
    resolved_at timestamptz,
    resolved_by_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
    suppressed_at timestamptz,
    suppressed_by_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (monitor_config_version_id, monitor_id) REFERENCES monitor_config_versions(id, monitor_id) ON DELETE RESTRICT,
    UNIQUE (monitor_config_version_id, event_id, trigger_type, policy_version),
    CHECK (last_triggered_at >= first_triggered_at),
    CHECK (cooldown_until >= last_triggered_at),
    CHECK (acknowledged_at IS NOT NULL OR acknowledged_by_user_id IS NULL),
    CHECK (resolved_at IS NOT NULL OR resolved_by_user_id IS NULL),
    CHECK (suppressed_at IS NOT NULL OR suppressed_by_user_id IS NULL)
);
CREATE INDEX IF NOT EXISTS alert_threads_inbox_idx
    ON alert_threads(last_triggered_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS alert_threads_monitor_state_idx
    ON alert_threads(monitor_id, state, last_triggered_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS alert_threads_state_severity_idx
    ON alert_threads(state, severity, last_triggered_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS alert_occurrences (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    alert_thread_id bigint NOT NULL REFERENCES alert_threads(id) ON DELETE RESTRICT,
    event_update_id bigint NOT NULL REFERENCES event_updates(id) ON DELETE RESTRICT,
    severity varchar(16) NOT NULL CHECK (severity IN ('info','warning','critical')),
    final_score_snapshot numeric(5,2) NOT NULL CHECK (final_score_snapshot BETWEEN 0 AND 100),
    threshold_snapshot numeric(5,2) NOT NULL CHECK (threshold_snapshot BETWEEN 0 AND 100),
    heat_score_snapshot numeric(5,2) NOT NULL DEFAULT 0 CHECK (heat_score_snapshot BETWEEN 0 AND 100),
    momentum_score_snapshot numeric(5,2) NOT NULL DEFAULT 0 CHECK (momentum_score_snapshot BETWEEN 0 AND 100),
    breadth_score_snapshot numeric(5,2) NOT NULL DEFAULT 0 CHECK (breadth_score_snapshot BETWEEN 0 AND 100),
    reason_codes text[] NOT NULL DEFAULT '{}',
    fingerprint char(64) NOT NULL UNIQUE,
    triggered_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (alert_thread_id, event_update_id)
);
CREATE INDEX IF NOT EXISTS alert_occurrences_thread_time_idx
    ON alert_occurrences(alert_thread_id, triggered_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS alert_email_deliveries (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    occurrence_id bigint NOT NULL UNIQUE REFERENCES alert_occurrences(id) ON DELETE RESTRICT,
    idempotency_key char(64) NOT NULL UNIQUE,
    recipient text NOT NULL CHECK (octet_length(recipient) >= 3 AND octet_length(recipient) <= 320),
    subject text NOT NULL CHECK (octet_length(subject) >= 1 AND octet_length(subject) <= 1000),
    text_body text NOT NULL CHECK (octet_length(text_body) >= 1 AND octet_length(text_body) <= 10000),
    html_body text NOT NULL CHECK (octet_length(html_body) >= 1 AND octet_length(html_body) <= 20000),
    severity varchar(16) NOT NULL CHECK (severity IN ('warning','critical')),
    status varchar(16) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','claimed','succeeded','retrying','failed')),
    next_attempt_at timestamptz,
    succeeded_at timestamptz,
    last_error text CHECK (last_error IS NULL OR octet_length(last_error) <= 255),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS alert_email_deliveries_next_attempt_idx
    ON alert_email_deliveries(status, next_attempt_at, id);

CREATE TABLE IF NOT EXISTS alert_email_attempts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    delivery_id bigint NOT NULL REFERENCES alert_email_deliveries(id) ON DELETE RESTRICT,
    attempt_no integer NOT NULL CHECK (attempt_no >= 1 AND attempt_no <= 5),
    status varchar(16) NOT NULL CHECK (status IN ('started','succeeded','failed')),
    error text CHECK (error IS NULL OR octet_length(error) <= 255),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (delivery_id, attempt_no, status)
);
CREATE INDEX IF NOT EXISTS alert_email_attempts_delivery_idx
    ON alert_email_attempts(delivery_id, attempt_no, id);

CREATE TABLE IF NOT EXISTS alert_state_audits (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    alert_thread_id bigint NOT NULL REFERENCES alert_threads(id) ON DELETE RESTRICT,
    actor_type varchar(16) NOT NULL CHECK (actor_type IN ('user','system')),
    actor_user_id bigint REFERENCES users(id) ON DELETE RESTRICT,
    from_state varchar(16) NOT NULL CHECK (from_state IN ('open','acknowledged','resolved','suppressed')),
    to_state varchar(16) NOT NULL CHECK (to_state IN ('open','acknowledged','resolved','suppressed')),
    expected_version bigint CHECK (expected_version IS NULL OR expected_version > 0),
    reason_code varchar(64) NOT NULL CHECK (octet_length(reason_code) >= 1 AND octet_length(reason_code) <= 64),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (from_state <> to_state),
    CHECK (actor_type = 'user' AND actor_user_id IS NOT NULL OR actor_type = 'system' AND actor_user_id IS NULL)
);
CREATE INDEX IF NOT EXISTS alert_state_audits_thread_idx
    ON alert_state_audits(alert_thread_id, created_at, id);

CREATE OR REPLACE FUNCTION reject_monitoring_fact_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitoring_fact_append_only_mutation', MESSAGE = 'monitoring facts are append-only';
END;
$$;

DROP TRIGGER IF EXISTS event_updates_append_only ON event_updates;
CREATE TRIGGER event_updates_append_only
BEFORE UPDATE OR DELETE ON event_updates
FOR EACH ROW EXECUTE FUNCTION reject_monitoring_fact_mutation();

DROP TRIGGER IF EXISTS alert_occurrences_append_only ON alert_occurrences;
CREATE TRIGGER alert_occurrences_append_only
BEFORE UPDATE OR DELETE ON alert_occurrences
FOR EACH ROW EXECUTE FUNCTION reject_monitoring_fact_mutation();

DROP TRIGGER IF EXISTS alert_state_audits_append_only ON alert_state_audits;
CREATE TRIGGER alert_state_audits_append_only
BEFORE UPDATE OR DELETE ON alert_state_audits
FOR EACH ROW EXECUTE FUNCTION reject_monitoring_fact_mutation();

-- notification_events is the durable, globally ordered delivery projection.
-- Source-table AFTER triggers write it inside the originating transaction so
-- clients never observe a notification for a rolled-back business fact.
CREATE TABLE IF NOT EXISTS notification_events (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_type varchar(32) NOT NULL CHECK (event_type IN (
        'event.updated','alert.triggered','report.published','report.failed',
        'collection.succeeded','collection.failed'
    )),
    resource_type varchar(24) NOT NULL CHECK (resource_type IN ('event','alert','report','collection_run')),
    resource_id bigint NOT NULL CHECK (resource_id > 0),
    audience_role varchar(16) NOT NULL CHECK (audience_role IN ('viewer','analyst','editor','admin')),
    occurred_at timestamptz NOT NULL,
    payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
    dedupe_key varchar(160) NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE notification_events DROP CONSTRAINT IF EXISTS notification_events_audience_role_check;
ALTER TABLE notification_events ADD CONSTRAINT notification_events_audience_role_check
    CHECK (audience_role IN ('viewer','analyst','editor','admin'));
CREATE INDEX IF NOT EXISTS notification_events_audience_id_idx
    ON notification_events(audience_role, id);

CREATE OR REPLACE FUNCTION project_notification_event()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    projected_event_type varchar(32);
    projected_resource_type varchar(24);
    projected_resource_id bigint;
    projected_audience_role varchar(16);
    projected_occurred_at timestamptz;
    projected_payload jsonb;
    projected_dedupe_key varchar(160);
    alert_occurrence_count bigint;
    alert_state varchar(16);
    alert_cooldown_until timestamptz;
BEGIN
    IF TG_TABLE_NAME = 'event_updates' THEN
        projected_event_type := 'event.updated';
        projected_resource_type := 'event';
        projected_resource_id := NEW.event_id;
        projected_audience_role := 'viewer';
        projected_occurred_at := NEW.observed_at;
        projected_payload := jsonb_build_object(
            'title', '事件发生重要变化',
            'summary', NEW.summary,
            'status', NEW.kind
        );
        projected_dedupe_key := 'event_update:' || NEW.id;
    ELSIF TG_TABLE_NAME = 'alert_occurrences' THEN
        SELECT occurrence_count, state, cooldown_until
        INTO alert_occurrence_count, alert_state, alert_cooldown_until
        FROM alert_threads
        WHERE id = NEW.alert_thread_id;

        -- The first occurrence always disturbs. Later occurrences are durable
        -- facts but do not create a real-time notification while the thread is
        -- suppressed or still inside its frozen cooldown window.
        IF alert_occurrence_count > 0 AND (
            alert_state = 'suppressed' OR NEW.triggered_at < alert_cooldown_until
        ) THEN
            RETURN NEW;
        END IF;
        projected_event_type := 'alert.triggered';
        projected_resource_type := 'alert';
        projected_resource_id := NEW.alert_thread_id;
        projected_audience_role := 'viewer';
        projected_occurred_at := NEW.triggered_at;
        projected_payload := jsonb_build_object(
            'title', '触发新的热点告警',
            'severity', NEW.severity
        );
        projected_dedupe_key := 'alert_occurrence:' || NEW.id;
    ELSIF TG_TABLE_NAME = 'reports' THEN
        projected_event_type := CASE NEW.status WHEN 'published' THEN 'report.published' ELSE 'report.failed' END;
        projected_resource_type := 'report';
        projected_resource_id := NEW.id;
        projected_audience_role := CASE NEW.status WHEN 'published' THEN 'viewer' ELSE 'admin' END;
        projected_occurred_at := COALESCE(NEW.published_at, NEW.updated_at);
        projected_payload := jsonb_build_object(
            'title', CASE NEW.status WHEN 'published' THEN '报告已发布' ELSE '报告生成失败' END,
            'summary', left(NEW.title, 500),
            'status', NEW.status
        );
        projected_dedupe_key := 'report:' || NEW.id || ':' || NEW.status || ':' || NEW.version;
    ELSIF TG_TABLE_NAME = 'collection_runs' THEN
        projected_event_type := CASE NEW.status WHEN 'succeeded' THEN 'collection.succeeded' ELSE 'collection.failed' END;
        projected_resource_type := 'collection_run';
        projected_resource_id := NEW.id;
        projected_audience_role := CASE NEW.status WHEN 'succeeded' THEN 'editor' ELSE 'admin' END;
        projected_occurred_at := COALESCE(NEW.finished_at, NEW.updated_at);
        projected_payload := jsonb_build_object(
            'title', CASE NEW.status WHEN 'succeeded' THEN '采集任务已完成' ELSE '采集任务失败' END,
            'status', NEW.status
        );
        projected_dedupe_key := 'collection_run:' || NEW.id || ':' || NEW.status;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'unsupported notification projection source';
    END IF;

    INSERT INTO notification_events (
        event_type, resource_type, resource_id, audience_role, occurred_at, payload, dedupe_key
    ) VALUES (
        projected_event_type, projected_resource_type, projected_resource_id,
        projected_audience_role, projected_occurred_at, projected_payload, projected_dedupe_key
    ) ON CONFLICT (dedupe_key) DO NOTHING;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS event_updates_notification_projection ON event_updates;
CREATE TRIGGER event_updates_notification_projection
AFTER INSERT ON event_updates
FOR EACH ROW EXECUTE FUNCTION project_notification_event();

DROP TRIGGER IF EXISTS alert_occurrences_notification_projection ON alert_occurrences;
CREATE TRIGGER alert_occurrences_notification_projection
AFTER INSERT ON alert_occurrences
FOR EACH ROW EXECUTE FUNCTION project_notification_event();

DROP TRIGGER IF EXISTS reports_notification_projection ON reports;
CREATE TRIGGER reports_notification_projection
AFTER UPDATE OF status ON reports
FOR EACH ROW
WHEN (OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('published','failed'))
EXECUTE FUNCTION project_notification_event();

DROP TRIGGER IF EXISTS collection_runs_notification_projection ON collection_runs;
CREATE TRIGGER collection_runs_notification_projection
AFTER UPDATE OF status ON collection_runs
FOR EACH ROW
WHEN (OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('succeeded','failed'))
EXECUTE FUNCTION project_notification_event();

CREATE OR REPLACE FUNCTION reject_notification_event_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'notification_events_append_only_mutation', MESSAGE = 'notification events are append-only';
END;
$$;

DROP TRIGGER IF EXISTS notification_events_append_only ON notification_events;
CREATE TRIGGER notification_events_append_only
BEFORE UPDATE OR DELETE ON notification_events
FOR EACH ROW EXECUTE FUNCTION reject_notification_event_mutation();

CREATE TABLE IF NOT EXISTS ai_runs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owning_job_id bigint,
    workspace_key varchar(64) NOT NULL, skill_id varchar(128) NOT NULL,
    task_type varchar(64) NOT NULL, target_type varchar(64) NOT NULL, target_id bigint NOT NULL, target_version bigint NOT NULL,
    runtime_version varchar(96) NOT NULL,
    model_profile_id bigint NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT, prompt_version varchar(64) NOT NULL, schema_version varchar(64) NOT NULL,
    input_hash char(64) NOT NULL, request_object_key text, response_object_key text, structured_result jsonb NOT NULL DEFAULT '{}'::jsonb,
    tokens bigint NOT NULL DEFAULT 0 CHECK (tokens >= 0), cost numeric(12,4) NOT NULL DEFAULT 0 CHECK (cost >= 0), latency_ms bigint NOT NULL DEFAULT 0 CHECK (latency_ms >= 0),
    status varchar(16) NOT NULL CHECK (status IN ('queued','running','validating','retry_wait','succeeded','failed','cancelled')),
    created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz,
    model_profile_version bigint NOT NULL,
    model_version varchar(64) NOT NULL,
    parameters_version varchar(64) NOT NULL,
    input_schema_version varchar(64) NOT NULL,
    evidence_set_hash char(64) NOT NULL,
    reuse_key char(64) NOT NULL,
    attempt smallint NOT NULL DEFAULT 1 CHECK (attempt BETWEEN 1 AND 3),
    max_attempts smallint NOT NULL DEFAULT 1 CHECK (max_attempts BETWEEN 1 AND 3),
    repair_attempted boolean NOT NULL DEFAULT false,
    retry_after timestamptz,
    error_code integer,
    budget_day date NOT NULL,
    reserved_cost numeric(12,4) NOT NULL DEFAULT 0 CHECK (reserved_cost >= 0),
    lease_expires_at timestamptz,
    CHECK (request_object_key IS NULL AND response_object_key IS NULL),
    CHECK (attempt <= max_attempts),
    CHECK (status IN ('queued','running','validating','retry_wait') AND lease_expires_at IS NOT NULL OR status IN ('succeeded','failed','cancelled') AND lease_expires_at IS NULL),
    CHECK (btrim(workspace_key) <> ''),
    CHECK (btrim(skill_id) <> ''),
    CHECK (target_version > 0),
    CHECK (btrim(runtime_version) <> '')
);

-- Existing installations predate the complete execution identity. Preserve
-- those immutable facts under an explicit legacy adapter/skill identity; new
-- runs always provide the four fields directly from the application boundary.
ALTER TABLE ai_runs ADD COLUMN IF NOT EXISTS workspace_key varchar(64);
ALTER TABLE ai_runs ADD COLUMN IF NOT EXISTS skill_id varchar(128);
ALTER TABLE ai_runs ADD COLUMN IF NOT EXISTS target_version bigint;
ALTER TABLE ai_runs ADD COLUMN IF NOT EXISTS runtime_version varchar(96);
ALTER TABLE ai_runs ADD COLUMN IF NOT EXISTS owning_job_id bigint;
UPDATE ai_runs
SET workspace_key = COALESCE(workspace_key, 'default'),
    skill_id = COALESCE(skill_id, 'legacy.' || task_type || '.v1'),
    target_version = COALESCE(target_version, 1),
    runtime_version = COALESCE(runtime_version, 'legacy-provider-v1')
WHERE workspace_key IS NULL OR skill_id IS NULL OR target_version IS NULL OR runtime_version IS NULL;
ALTER TABLE ai_runs ALTER COLUMN workspace_key SET NOT NULL;
ALTER TABLE ai_runs ALTER COLUMN skill_id SET NOT NULL;
ALTER TABLE ai_runs ALTER COLUMN target_version SET NOT NULL;
ALTER TABLE ai_runs ALTER COLUMN runtime_version SET NOT NULL;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ai_runs'::regclass AND contype = 'c'
          AND pg_get_expr(conbin, conrelid) LIKE '%workspace_key%'
    ) THEN
        ALTER TABLE ai_runs ADD CONSTRAINT ai_runs_workspace_key_nonempty CHECK (btrim(workspace_key) <> '');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ai_runs'::regclass AND contype = 'c'
          AND pg_get_expr(conbin, conrelid) LIKE '%skill_id%'
    ) THEN
        ALTER TABLE ai_runs ADD CONSTRAINT ai_runs_skill_id_nonempty CHECK (btrim(skill_id) <> '');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ai_runs'::regclass AND contype = 'c'
          AND pg_get_expr(conbin, conrelid) LIKE '%target_version%'
    ) THEN
        ALTER TABLE ai_runs ADD CONSTRAINT ai_runs_target_version_positive CHECK (target_version > 0);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ai_runs'::regclass AND contype = 'c'
          AND pg_get_expr(conbin, conrelid) LIKE '%runtime_version%'
    ) THEN
        ALTER TABLE ai_runs ADD CONSTRAINT ai_runs_runtime_version_nonempty CHECK (btrim(runtime_version) <> '');
    END IF;
END;
$$;
CREATE UNIQUE INDEX IF NOT EXISTS ai_runs_reuse_succeeded_uq ON ai_runs(reuse_key) WHERE status = 'succeeded';
CREATE UNIQUE INDEX IF NOT EXISTS ai_runs_reuse_inflight_uq ON ai_runs(reuse_key) WHERE status IN ('queued','running','validating','retry_wait');

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'monitor_matches_embedding_model_profile_id_fkey'
          AND conrelid = 'monitor_matches'::regclass
    ) THEN
        ALTER TABLE monitor_matches
            ADD CONSTRAINT monitor_matches_embedding_model_profile_id_fkey
            FOREIGN KEY (embedding_model_profile_id) REFERENCES ai_model_profiles(id) ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'monitor_matches_review_ai_run_id_fkey'
          AND conrelid = 'monitor_matches'::regclass
    ) THEN
        ALTER TABLE monitor_matches
            ADD CONSTRAINT monitor_matches_review_ai_run_id_fkey
            FOREIGN KEY (review_ai_run_id) REFERENCES ai_runs(id) ON DELETE RESTRICT;
    END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS ai_budget_ledgers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    model_profile_id bigint NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT,
    budget_day date NOT NULL,
    reserved_cost numeric(12,4) NOT NULL DEFAULT 0 CHECK (reserved_cost >= 0),
    settled_cost numeric(12,4) NOT NULL DEFAULT 0 CHECK (settled_cost >= 0),
    overage_blocked boolean NOT NULL DEFAULT false,
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (model_profile_id, budget_day)
);

CREATE TABLE IF NOT EXISTS ai_run_evidences (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ai_run_id bigint NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE,
    content_id bigint NOT NULL REFERENCES contents(id) ON DELETE RESTRICT, evidence_role varchar(32) NOT NULL, position integer NOT NULL DEFAULT 0 CHECK (position >= 0),
    created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (ai_run_id, content_id, evidence_role)
);

CREATE TABLE IF NOT EXISTS content_embeddings (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, content_id bigint NOT NULL REFERENCES contents(id) ON DELETE CASCADE,
    model_profile_id bigint NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT, model_version varchar(64) NOT NULL, input_hash char(64) NOT NULL,
    embedding halfvec(1024) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), model_profile_version bigint NOT NULL,
    ai_run_id bigint NOT NULL REFERENCES ai_runs(id) ON DELETE RESTRICT,
    UNIQUE (content_id, model_profile_id, model_version, input_hash)
);
CREATE INDEX IF NOT EXISTS content_embeddings_active_hnsw_idx ON content_embeddings USING hnsw (embedding halfvec_cosine_ops) WHERE active;
CREATE UNIQUE INDEX IF NOT EXISTS content_embeddings_one_active_per_profile_uq ON content_embeddings(content_id, model_profile_id) WHERE active;

CREATE TABLE IF NOT EXISTS monitor_embeddings (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, monitor_id bigint NOT NULL REFERENCES monitors(id) ON DELETE CASCADE,
    model_profile_id bigint NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT, model_version varchar(64) NOT NULL, input_hash char(64) NOT NULL,
    query_text text NOT NULL, embedding halfvec(1024) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), model_profile_version bigint NOT NULL,
    ai_run_id bigint NOT NULL REFERENCES ai_runs(id) ON DELETE RESTRICT,
    UNIQUE (monitor_id, model_profile_id, model_version, input_hash)
);
CREATE INDEX IF NOT EXISTS monitor_embeddings_active_hnsw_idx ON monitor_embeddings USING hnsw (embedding halfvec_cosine_ops) WHERE active;
CREATE UNIQUE INDEX IF NOT EXISTS monitor_embeddings_one_active_per_profile_uq ON monitor_embeddings(monitor_id, model_profile_id) WHERE active;

CREATE TABLE IF NOT EXISTS event_embeddings (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id bigint NOT NULL REFERENCES events(id) ON DELETE CASCADE,
    model_profile_id bigint NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT, model_version varchar(64) NOT NULL, input_hash char(64) NOT NULL,
    embedding halfvec(1024) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), model_profile_version bigint NOT NULL,
    ai_run_id bigint NOT NULL REFERENCES ai_runs(id) ON DELETE RESTRICT,
    UNIQUE (event_id, model_profile_id, model_version, input_hash)
);
CREATE INDEX IF NOT EXISTS event_embeddings_active_hnsw_idx ON event_embeddings USING hnsw (embedding halfvec_cosine_ops) WHERE active;
CREATE UNIQUE INDEX IF NOT EXISTS event_embeddings_one_active_per_profile_uq ON event_embeddings(event_id, model_profile_id) WHERE active;

CREATE TABLE IF NOT EXISTS topic_embeddings (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, topic_id bigint NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    model_profile_id bigint NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT, model_version varchar(64) NOT NULL, input_hash char(64) NOT NULL,
    embedding halfvec(1024) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), model_profile_version bigint NOT NULL,
    ai_run_id bigint NOT NULL REFERENCES ai_runs(id) ON DELETE RESTRICT,
    UNIQUE (topic_id, model_profile_id, model_version, input_hash)
);
CREATE INDEX IF NOT EXISTS topic_embeddings_active_hnsw_idx ON topic_embeddings USING hnsw (embedding halfvec_cosine_ops) WHERE active;
CREATE UNIQUE INDEX IF NOT EXISTS topic_embeddings_one_active_per_profile_uq ON topic_embeddings(topic_id, model_profile_id) WHERE active;

CREATE TABLE IF NOT EXISTS knowledge_revisions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id bigint NOT NULL REFERENCES knowledge_documents(id) ON DELETE RESTRICT,
    revision_no bigint NOT NULL CHECK (revision_no >= 0), source varchar(16) NOT NULL CHECK (source IN ('user','proposal','reconcile')),
    proposal_id bigint REFERENCES knowledge_change_proposals(id) ON DELETE SET NULL, previous_hash char(64), new_hash char(64),
    snapshot_object_key text, frontmatter_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_by bigint REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (document_id, revision_no)
);

CREATE TABLE IF NOT EXISTS vault_sync_runs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_type varchar(16) NOT NULL CHECK (run_type IN ('full','incremental','reconcile')),
    started_at timestamptz, finished_at timestamptz, status varchar(16) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','cancelled')),
    scanned_count bigint NOT NULL DEFAULT 0 CHECK (scanned_count >= 0), changed_count bigint NOT NULL DEFAULT 0 CHECK (changed_count >= 0),
    conflict_count bigint NOT NULL DEFAULT 0 CHECK (conflict_count >= 0), error text, created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS report_deliveries (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, report_id bigint NOT NULL REFERENCES reports(id) ON DELETE RESTRICT,
    subscription_id bigint NOT NULL REFERENCES report_subscriptions(id) ON DELETE RESTRICT, idempotency_key varchar(128) NOT NULL UNIQUE,
    status varchar(16) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','claimed','succeeded','retrying','failed','cancelled')),
    next_attempt_at timestamptz, succeeded_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (report_id, subscription_id)
);
CREATE INDEX IF NOT EXISTS report_deliveries_next_attempt_idx ON report_deliveries(status, next_attempt_at, id);

CREATE TABLE IF NOT EXISTS delivery_attempts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, delivery_id bigint NOT NULL REFERENCES report_deliveries(id) ON DELETE CASCADE,
    attempt_no integer NOT NULL CHECK (attempt_no > 0), started_at timestamptz NOT NULL, finished_at timestamptz,
    status varchar(16) NOT NULL CHECK (status IN ('started','succeeded','failed')), provider_message_id varchar(255), response_code integer, error text,
    created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (delivery_id, attempt_no)
);

CREATE TABLE IF NOT EXISTS audit_logs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_type varchar(32) NOT NULL, actor_id bigint,
    action varchar(120) NOT NULL, resource_type varchar(64) NOT NULL, resource_id bigint, request_id varchar(128), trace_id varchar(128),
    idempotency_key varchar(128), command_fingerprint char(64),
    before_data jsonb, after_data jsonb, result varchar(16) NOT NULL CHECK (result IN ('success','failure','denied')),
    ip_hash char(64), created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (
        idempotency_key IS NULL AND command_fingerprint IS NULL
        OR idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
           AND command_fingerprint ~ '^[0-9a-f]{64}$'
    )
);
ALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS idempotency_key varchar(128);
ALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS command_fingerprint char(64);
ALTER TABLE audit_logs DROP CONSTRAINT IF EXISTS audit_logs_command_receipt_check;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = 'audit_logs'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid, true) LIKE 'CHECK (idempotency_key IS NULL AND command_fingerprint IS NULL%'
    ) THEN
        ALTER TABLE audit_logs ADD CONSTRAINT audit_logs_command_receipt_check CHECK (
            idempotency_key IS NULL AND command_fingerprint IS NULL
            OR idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
               AND command_fingerprint ~ '^[0-9a-f]{64}$'
        );
    END IF;
END;
$$;
CREATE UNIQUE INDEX IF NOT EXISTS audit_logs_idempotency_uq
    ON audit_logs(actor_type, COALESCE(actor_id, 0), action, idempotency_key)
    WHERE idempotency_key IS NOT NULL;

-- Evidence-lineage maintenance runs are auditable operational facts. Dry-run
-- commands never insert these rows; only an explicitly confirmed apply run is
-- persisted. Item rows are append-only so a resume cannot rewrite prior
-- outcomes or conceal a failed/blocked legacy asset.
CREATE TABLE IF NOT EXISTS evidence_lineage_migration_runs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    phase varchar(32) NOT NULL CHECK (phase IN ('source','evidence_metadata','document','match','family_event','evidence_state')),
    status varchar(16) NOT NULL DEFAULT 'running' CHECK (status IN ('running','completed','failed','cancelled')),
    execution_mode varchar(16) NOT NULL DEFAULT 'apply' CHECK (execution_mode = 'apply'),
    operator_id varchar(128) NOT NULL CHECK (operator_id = btrim(operator_id) AND octet_length(operator_id) BETWEEN 1 AND 128),
    reviewer_id varchar(128) NOT NULL CHECK (reviewer_id = btrim(reviewer_id) AND octet_length(reviewer_id) BETWEEN 1 AND 128),
    binary_sha256 char(64) NOT NULL CHECK (binary_sha256 ~ '^[0-9a-f]{64}$'),
    schema_sha256 char(64) NOT NULL CHECK (schema_sha256 ~ '^[0-9a-f]{64}$'),
    configuration_sha256 char(64) NOT NULL CHECK (configuration_sha256 ~ '^[0-9a-f]{64}$'),
    backup_evidence_sha256 char(64) NOT NULL CHECK (backup_evidence_sha256 ~ '^[0-9a-f]{64}$'),
    rehearsal_evidence_sha256 char(64) NOT NULL CHECK (rehearsal_evidence_sha256 ~ '^[0-9a-f]{64}$'),
    batch_size integer NOT NULL CHECK (batch_size BETWEEN 1 AND 1000),
    last_legacy_resource_id bigint NOT NULL DEFAULT 0 CHECK (last_legacy_resource_id >= 0),
    examined_count bigint NOT NULL DEFAULT 0 CHECK (examined_count >= 0),
    reused_count bigint NOT NULL DEFAULT 0 CHECK (reused_count >= 0),
    created_count bigint NOT NULL DEFAULT 0 CHECK (created_count >= 0),
    skipped_count bigint NOT NULL DEFAULT 0 CHECK (skipped_count >= 0),
    blocked_count bigint NOT NULL DEFAULT 0 CHECK (blocked_count >= 0),
    failed_count bigint NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
    resume_count integer NOT NULL DEFAULT 0 CHECK (resume_count >= 0),
    failure_code varchar(64),
    started_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (operator_id <> reviewer_id),
    CHECK (completed_at IS NULL OR completed_at >= started_at),
    CHECK (status = 'running' AND completed_at IS NULL OR status <> 'running' AND completed_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS evidence_lineage_migration_runs_resume_idx
    ON evidence_lineage_migration_runs(status, phase, id);

CREATE TABLE IF NOT EXISTS evidence_lineage_migration_items (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id bigint NOT NULL REFERENCES evidence_lineage_migration_runs(id) ON DELETE RESTRICT,
    phase varchar(32) NOT NULL CHECK (phase IN ('source','evidence_metadata','document','match','family_event','evidence_state')),
    legacy_resource_type varchar(64) NOT NULL CHECK (legacy_resource_type = btrim(legacy_resource_type) AND octet_length(legacy_resource_type) BETWEEN 1 AND 64),
    legacy_resource_id bigint NOT NULL CHECK (legacy_resource_id > 0),
    input_sha256 char(64) NOT NULL CHECK (input_sha256 ~ '^[0-9a-f]{64}$'),
    disposition varchar(16) NOT NULL CHECK (disposition IN ('reused','created','skipped','blocked','failed')),
    target_resource_type varchar(64),
    target_resource_id bigint,
    reason_code varchar(64) NOT NULL CHECK (reason_code = btrim(reason_code) AND reason_code ~ '^[a-z][a-z0-9_]{0,63}$'),
    attempt integer NOT NULL DEFAULT 1 CHECK (attempt > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (run_id, legacy_resource_type, legacy_resource_id, input_sha256),
    CHECK (
        target_resource_type IS NULL AND target_resource_id IS NULL
        OR target_resource_type = btrim(target_resource_type) AND octet_length(target_resource_type) BETWEEN 1 AND 64 AND target_resource_id > 0
    )
);
CREATE INDEX IF NOT EXISTS evidence_lineage_migration_items_cursor_idx
    ON evidence_lineage_migration_items(run_id, legacy_resource_id, id);

CREATE TABLE IF NOT EXISTS evidence_lineage_reconciliation_runs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    scope varchar(32) NOT NULL CHECK (scope IN ('pg-minio','pg-vault','rights-retention','all')),
    status varchar(16) NOT NULL DEFAULT 'running' CHECK (status IN ('running','completed','failed','cancelled')),
    execution_mode varchar(16) NOT NULL DEFAULT 'apply' CHECK (execution_mode = 'apply'),
    operator_id varchar(128) NOT NULL CHECK (operator_id = btrim(operator_id) AND octet_length(operator_id) BETWEEN 1 AND 128),
    reviewer_id varchar(128) NOT NULL CHECK (reviewer_id = btrim(reviewer_id) AND octet_length(reviewer_id) BETWEEN 1 AND 128),
    binary_sha256 char(64) NOT NULL CHECK (binary_sha256 ~ '^[0-9a-f]{64}$'),
    schema_sha256 char(64) NOT NULL CHECK (schema_sha256 ~ '^[0-9a-f]{64}$'),
    configuration_sha256 char(64) NOT NULL CHECK (configuration_sha256 ~ '^[0-9a-f]{64}$'),
    backup_evidence_sha256 char(64) NOT NULL CHECK (backup_evidence_sha256 ~ '^[0-9a-f]{64}$'),
    rehearsal_evidence_sha256 char(64) NOT NULL CHECK (rehearsal_evidence_sha256 ~ '^[0-9a-f]{64}$'),
    batch_size integer NOT NULL CHECK (batch_size BETWEEN 1 AND 1000),
    grace_period_hours integer NOT NULL CHECK (grace_period_hours BETWEEN 1 AND 720),
    last_asset_id bigint NOT NULL DEFAULT 0 CHECK (last_asset_id >= 0),
    examined_count bigint NOT NULL DEFAULT 0 CHECK (examined_count >= 0),
    healthy_count bigint NOT NULL DEFAULT 0 CHECK (healthy_count >= 0),
    finding_count bigint NOT NULL DEFAULT 0 CHECK (finding_count >= 0),
    repaired_count bigint NOT NULL DEFAULT 0 CHECK (repaired_count >= 0),
    failed_count bigint NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
    resume_count integer NOT NULL DEFAULT 0 CHECK (resume_count >= 0),
    failure_code varchar(64),
    started_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (operator_id <> reviewer_id),
    CHECK (completed_at IS NULL OR completed_at >= started_at),
    CHECK (status = 'running' AND completed_at IS NULL OR status <> 'running' AND completed_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS evidence_lineage_reconciliation_runs_resume_idx
    ON evidence_lineage_reconciliation_runs(status, scope, id);

CREATE TABLE IF NOT EXISTS evidence_lineage_reconciliation_items (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id bigint NOT NULL REFERENCES evidence_lineage_reconciliation_runs(id) ON DELETE RESTRICT,
    scope varchar(32) NOT NULL CHECK (scope IN ('pg-minio','pg-vault','rights-retention','all')),
    asset_type varchar(32) NOT NULL CHECK (asset_type IN ('evidence_snapshot','derived_artifact','document_version','active_artifact_pointer','raw_object_orphan','vault_file_orphan')),
    asset_id bigint CHECK (asset_id IS NULL OR asset_id > 0),
    asset_key_sha256 char(64) NOT NULL CHECK (asset_key_sha256 ~ '^[0-9a-f]{64}$'),
    source_connection_id bigint REFERENCES source_connections(id) ON DELETE RESTRICT,
    finding varchar(32) NOT NULL CHECK (finding IN ('missing','orphan_within_grace','orphan_expired','digest_mismatch','policy_blocked','retention_blocked','active_pointer_invalid','healthy')),
    expected_sha256 char(64) CHECK (expected_sha256 IS NULL OR expected_sha256 ~ '^[0-9a-f]{64}$'),
    observed_sha256 char(64) CHECK (observed_sha256 IS NULL OR observed_sha256 ~ '^[0-9a-f]{64}$'),
    lifecycle_before varchar(32),
    lifecycle_after varchar(32),
    repair_action varchar(64),
    reason_code varchar(64) NOT NULL CHECK (reason_code = btrim(reason_code) AND reason_code ~ '^[a-z][a-z0-9_]{0,63}$'),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (run_id, scope, asset_type, asset_key_sha256)
);
ALTER TABLE evidence_lineage_reconciliation_items ADD COLUMN IF NOT EXISTS asset_key_sha256 char(64);
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM evidence_lineage_reconciliation_items WHERE asset_key_sha256 IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'evidence_lineage_reconciliation_items_asset_key_backfill_required', MESSAGE = 'existing reconciliation items require an explicit asset key review';
    END IF;
END;
$$;
ALTER TABLE evidence_lineage_reconciliation_items ALTER COLUMN asset_id DROP NOT NULL;
ALTER TABLE evidence_lineage_reconciliation_items ALTER COLUMN source_connection_id DROP NOT NULL;
ALTER TABLE evidence_lineage_reconciliation_items ALTER COLUMN asset_key_sha256 SET NOT NULL;
ALTER TABLE evidence_lineage_reconciliation_items DROP CONSTRAINT IF EXISTS evidence_lineage_reconciliation_items_asset_type_check;
ALTER TABLE evidence_lineage_reconciliation_items ADD CONSTRAINT evidence_lineage_reconciliation_items_asset_type_check
    CHECK (asset_type IN ('evidence_snapshot','derived_artifact','document_version','active_artifact_pointer','raw_object_orphan','vault_file_orphan'));
ALTER TABLE evidence_lineage_reconciliation_items DROP CONSTRAINT IF EXISTS evidence_lineage_reconciliation_items_asset_id_check;
ALTER TABLE evidence_lineage_reconciliation_items ADD CONSTRAINT evidence_lineage_reconciliation_items_asset_id_check
    CHECK (asset_id IS NULL OR asset_id > 0);
ALTER TABLE evidence_lineage_reconciliation_items DROP CONSTRAINT IF EXISTS evidence_lineage_reconciliation_items_asset_key_sha256_check;
ALTER TABLE evidence_lineage_reconciliation_items ADD CONSTRAINT evidence_lineage_reconciliation_items_asset_key_sha256_check
    CHECK (asset_key_sha256 ~ '^[0-9a-f]{64}$');
DO $$
DECLARE
    legacy_reconciliation_identity text;
BEGIN
    FOR legacy_reconciliation_identity IN
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = 'evidence_lineage_reconciliation_items'::regclass
          AND contype = 'u'
          AND pg_get_constraintdef(oid, true) = 'UNIQUE (run_id, scope, asset_type, asset_id)'
    LOOP
        EXECUTE format('ALTER TABLE evidence_lineage_reconciliation_items DROP CONSTRAINT %I', legacy_reconciliation_identity);
    END LOOP;
END;
$$;
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM pg_class AS index_relation
        JOIN pg_namespace AS namespace ON namespace.oid = index_relation.relnamespace
        WHERE namespace.nspname = 'public'
          AND index_relation.relname = 'evidence_lineage_reconciliation_items_identity_uq'
          AND index_relation.relkind = 'i'
          AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conindid = index_relation.oid)
    ) THEN
        DROP INDEX evidence_lineage_reconciliation_items_identity_uq;
    END IF;
END;
$$;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = 'evidence_lineage_reconciliation_items'::regclass
          AND contype = 'u'
          AND pg_get_constraintdef(oid, true) = 'UNIQUE (run_id, scope, asset_type, asset_key_sha256)'
    ) THEN
        ALTER TABLE evidence_lineage_reconciliation_items
            ADD CONSTRAINT evidence_lineage_reconciliation_items_identity_uq
            UNIQUE (run_id, scope, asset_type, asset_key_sha256);
    END IF;
END;
$$;
DROP INDEX IF EXISTS evidence_lineage_reconciliation_items_finding_idx;
CREATE INDEX IF NOT EXISTS evidence_lineage_reconciliation_items_finding_idx
    ON evidence_lineage_reconciliation_items(run_id, finding, asset_type, asset_key_sha256);

CREATE OR REPLACE FUNCTION prevent_evidence_lineage_maintenance_item_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = TG_TABLE_NAME || '_append_only', MESSAGE = 'evidence lineage maintenance items are append-only';
END;
$$;
DROP TRIGGER IF EXISTS evidence_lineage_migration_items_append_only ON evidence_lineage_migration_items;
CREATE TRIGGER evidence_lineage_migration_items_append_only
BEFORE UPDATE OR DELETE ON evidence_lineage_migration_items
FOR EACH ROW EXECUTE FUNCTION prevent_evidence_lineage_maintenance_item_mutation();
DROP TRIGGER IF EXISTS evidence_lineage_reconciliation_items_append_only ON evidence_lineage_reconciliation_items;
CREATE TRIGGER evidence_lineage_reconciliation_items_append_only
BEFORE UPDATE OR DELETE ON evidence_lineage_reconciliation_items
FOR EACH ROW EXECUTE FUNCTION prevent_evidence_lineage_maintenance_item_mutation();

-- River job metadata belongs to the job-queue infrastructure and is not exposed
-- through application repositories or public APIs. The runtime integration in
-- PLAN-002 validates its expected River version before workers are enabled.
CREATE TABLE IF NOT EXISTS river_job (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind text NOT NULL, args jsonb NOT NULL DEFAULT '{}'::jsonb,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb, state text NOT NULL DEFAULT 'available', attempt integer NOT NULL DEFAULT 0,
    max_attempts integer NOT NULL DEFAULT 25, priority smallint NOT NULL DEFAULT 1, scheduled_at timestamptz NOT NULL DEFAULT now(),
    attempted_at timestamptz, finalized_at timestamptz, unique_key bytea, tags varchar(255)[] NOT NULL DEFAULT '{}',
    errors jsonb[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE NULLS NOT DISTINCT (kind, unique_key)
);
CREATE INDEX IF NOT EXISTS river_job_fetch_idx ON river_job(state, scheduled_at, priority, id);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'ai_runs_owning_job_id_fkey'
          AND conrelid = 'ai_runs'::regclass
    ) THEN
        ALTER TABLE ai_runs
            ADD CONSTRAINT ai_runs_owning_job_id_fkey
            FOREIGN KEY (owning_job_id) REFERENCES river_job(id) ON DELETE RESTRICT;
    END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS river_job_attempt (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id bigint NOT NULL REFERENCES river_job(id) ON DELETE CASCADE,
    attempt integer NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (job_id, attempt)
);

CREATE TABLE IF NOT EXISTS river_queue (
    name text PRIMARY KEY, paused_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS river_leader (
    name text PRIMARY KEY, elected_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS river_migration (
    version bigint PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now()
);

-- Monitor intent drafts are independent from the legacy rule representation.
-- A draft belongs to one configuration identity, while append-only revisions
-- preserve every resource version used by an asynchronous analysis run.
CREATE TABLE IF NOT EXISTS monitor_intent_drafts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    resource_version bigint NOT NULL DEFAULT 1 CHECK (resource_version > 0),
    monitor_id bigint NOT NULL REFERENCES monitors(id) ON DELETE RESTRICT,
    config_version_id bigint NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (config_version_id, monitor_id) REFERENCES monitor_config_versions(id, monitor_id) ON DELETE RESTRICT,
    UNIQUE (id, monitor_id, config_version_id),
    UNIQUE (id, monitor_id)
);

CREATE TABLE IF NOT EXISTS monitor_intent_draft_revisions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    draft_id bigint NOT NULL,
    monitor_id bigint NOT NULL,
    config_version_id bigint NOT NULL,
    resource_version bigint NOT NULL CHECK (resource_version > 0),
    objective text NOT NULL CHECK (octet_length(objective) >= 1 AND octet_length(objective) <= 8000),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (draft_id, monitor_id, config_version_id)
        REFERENCES monitor_intent_drafts(id, monitor_id, config_version_id) ON DELETE RESTRICT,
    UNIQUE (draft_id, resource_version),
    UNIQUE (id, draft_id, resource_version),
    UNIQUE (id, monitor_id, config_version_id)
);

CREATE TABLE IF NOT EXISTS monitor_intent_clauses (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    revision_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    resource_version bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 127),
    operator varchar(16) NOT NULL CHECK (operator IN ('must','should','must_not')),
    field varchar(24) NOT NULL CHECK (field IN ('term','phrase','action','location','language','region','source','time_window')),
    value text NOT NULL CHECK (octet_length(value) >= 1 AND octet_length(value) <= 2048),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (revision_id, draft_id, resource_version)
        REFERENCES monitor_intent_draft_revisions(id, draft_id, resource_version) ON DELETE RESTRICT,
    UNIQUE (revision_id, ordinal)
);
CREATE UNIQUE INDEX IF NOT EXISTS monitor_intent_clauses_identity_uq
    ON monitor_intent_clauses(revision_id, operator, field, lower(value));

CREATE TABLE IF NOT EXISTS monitor_intent_entities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    revision_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    resource_version bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 63),
    canonical_id varchar(256) NOT NULL CHECK (octet_length(canonical_id) >= 1 AND octet_length(canonical_id) <= 256),
    display_name varchar(640) NOT NULL CHECK (octet_length(display_name) >= 1 AND octet_length(display_name) <= 640),
    ambiguity_note text NOT NULL DEFAULT '' CHECK (octet_length(ambiguity_note) <= 4000),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (revision_id, draft_id, resource_version)
        REFERENCES monitor_intent_draft_revisions(id, draft_id, resource_version) ON DELETE RESTRICT,
    UNIQUE (revision_id, ordinal),
    UNIQUE (revision_id, canonical_id),
    UNIQUE (id, draft_id, resource_version)
);

CREATE TABLE IF NOT EXISTS monitor_intent_entity_aliases (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    entity_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    resource_version bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 31),
    alias varchar(640) NOT NULL CHECK (octet_length(alias) >= 1 AND octet_length(alias) <= 640),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (entity_id, draft_id, resource_version)
        REFERENCES monitor_intent_entities(id, draft_id, resource_version) ON DELETE RESTRICT,
    UNIQUE (entity_id, ordinal)
);
CREATE UNIQUE INDEX IF NOT EXISTS monitor_intent_entity_aliases_identity_uq
    ON monitor_intent_entity_aliases(draft_id, resource_version, lower(alias));

CREATE TABLE IF NOT EXISTS monitor_intent_examples (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    revision_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    resource_version bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 63),
    label varchar(16) NOT NULL CHECK (label IN ('positive','negative')),
    example_text text NOT NULL CHECK (octet_length(example_text) >= 1 AND octet_length(example_text) <= 16000),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (revision_id, draft_id, resource_version)
        REFERENCES monitor_intent_draft_revisions(id, draft_id, resource_version) ON DELETE RESTRICT,
    UNIQUE (revision_id, ordinal)
);

CREATE TABLE IF NOT EXISTS monitor_intent_mutation_receipts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    monitor_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    mutation_kind varchar(32) NOT NULL CHECK (mutation_kind = 'candidate_review'),
    idempotency_key varchar(128) NOT NULL CHECK (octet_length(idempotency_key) >= 1 AND octet_length(idempotency_key) <= 128),
    command_fingerprint char(64) NOT NULL CHECK (command_fingerprint ~ '^[0-9a-f]{64}$'),
    expected_resource_version bigint NOT NULL CHECK (expected_resource_version > 0),
    result_resource_version bigint NOT NULL CHECK (result_resource_version = (expected_resource_version + 1)),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (draft_id, monitor_id) REFERENCES monitor_intent_drafts(id, monitor_id) ON DELETE RESTRICT,
    FOREIGN KEY (draft_id, result_resource_version)
        REFERENCES monitor_intent_draft_revisions(draft_id, resource_version) ON DELETE RESTRICT,
    UNIQUE (monitor_id, draft_id, idempotency_key)
);

CREATE TABLE IF NOT EXISTS monitor_intent_analysis_runs (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    monitor_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    draft_resource_version bigint NOT NULL CHECK (draft_resource_version > 0),
    kind varchar(16) NOT NULL CHECK (kind IN ('expansion','preview')),
    input_hash char(64) NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
    profile_version varchar(64) NOT NULL CHECK (profile_version ~ '^[a-z0-9][a-z0-9._:-]{0,63}$'),
    sample_limit integer NOT NULL DEFAULT 0 CHECK (kind = 'expansion' AND sample_limit = 0 OR kind = 'preview' AND sample_limit BETWEEN 1 AND 200),
    request_hash char(64) NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
    idempotency_key varchar(128) NOT NULL UNIQUE CHECK (octet_length(idempotency_key) >= 1 AND octet_length(idempotency_key) <= 128),
    river_job_id bigint NOT NULL UNIQUE REFERENCES river_job(id) ON DELETE RESTRICT,
    status varchar(16) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','invalidated')),
    queued_at timestamptz NOT NULL,
    started_at timestamptz,
    completed_at timestamptz,
    invalidated_at timestamptz,
    failure_reason text CHECK (failure_reason IS NULL OR octet_length(failure_reason) >= 1 AND octet_length(failure_reason) <= 4000),
    result_fingerprint char(64) CHECK (result_fingerprint IS NULL OR result_fingerprint ~ '^[0-9a-f]{64}$'),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (draft_id, monitor_id) REFERENCES monitor_intent_drafts(id, monitor_id) ON DELETE RESTRICT,
    FOREIGN KEY (draft_id, draft_resource_version)
        REFERENCES monitor_intent_draft_revisions(draft_id, resource_version) ON DELETE RESTRICT,
    CHECK (
        status = 'queued' AND started_at IS NULL AND completed_at IS NULL AND invalidated_at IS NULL AND failure_reason IS NULL AND result_fingerprint IS NULL
        OR status = 'running' AND started_at IS NOT NULL AND completed_at IS NULL AND invalidated_at IS NULL AND failure_reason IS NULL AND result_fingerprint IS NULL
        OR status = 'succeeded' AND started_at IS NOT NULL AND completed_at IS NOT NULL AND invalidated_at IS NULL AND failure_reason IS NULL AND result_fingerprint IS NOT NULL
        OR status = 'failed' AND completed_at IS NOT NULL AND invalidated_at IS NULL AND failure_reason IS NOT NULL AND result_fingerprint IS NULL
        OR status = 'invalidated' AND invalidated_at IS NOT NULL AND (
            result_fingerprint IS NULL
            OR started_at IS NOT NULL AND completed_at IS NOT NULL AND failure_reason IS NULL
        )
    ),
    CHECK (started_at IS NULL OR started_at >= queued_at),
    CHECK (completed_at IS NULL OR completed_at >= COALESCE(started_at, queued_at)),
    CHECK (invalidated_at IS NULL OR invalidated_at >= queued_at),
    UNIQUE (id, monitor_id, draft_id, draft_resource_version)
);
CREATE INDEX IF NOT EXISTS monitor_intent_analysis_runs_draft_idx
    ON monitor_intent_analysis_runs(monitor_id, draft_id, draft_resource_version, kind, id);

CREATE TABLE IF NOT EXISTS monitor_intent_expansion_candidates (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    draft_id bigint NOT NULL REFERENCES monitor_intent_drafts(id) ON DELETE RESTRICT,
    introduced_resource_version bigint NOT NULL CHECK (introduced_resource_version > 0),
    candidate_id varchar(128) NOT NULL CHECK (octet_length(candidate_id) >= 1 AND octet_length(candidate_id) <= 128),
    origin_run_id bigint REFERENCES monitor_intent_analysis_runs(id) ON DELETE RESTRICT,
    candidate_value varchar(640) NOT NULL CHECK (octet_length(candidate_value) >= 1 AND octet_length(candidate_value) <= 640),
    source varchar(48) NOT NULL CHECK (source IN ('user_input','entity_alias','approved_historical_feedback','corpus_feedback','llm')),
    reason text NOT NULL CHECK (octet_length(reason) >= 1 AND octet_length(reason) <= 4000),
    model_version varchar(128) NOT NULL,
    prompt_version varchar(128) NOT NULL,
    input_hash char(64) NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
    similarity numeric(8,7) NOT NULL CHECK (similarity BETWEEN 0 AND 1),
    risk varchar(16) NOT NULL CHECK (risk IN ('low','medium','high')),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (draft_id, introduced_resource_version)
        REFERENCES monitor_intent_draft_revisions(draft_id, resource_version) ON DELETE RESTRICT,
    UNIQUE (draft_id, introduced_resource_version, candidate_id),
    UNIQUE (id, draft_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS monitor_intent_expansion_candidates_origin_uq
    ON monitor_intent_expansion_candidates(origin_run_id, candidate_id) WHERE origin_run_id IS NOT NULL;
ALTER TABLE monitor_intent_expansion_candidates
    ALTER COLUMN similarity TYPE numeric(8,7) USING round(similarity::numeric, 7);

CREATE TABLE IF NOT EXISTS monitor_intent_draft_candidates (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version bigint NOT NULL DEFAULT 1 CHECK (version = 1),
    revision_id bigint NOT NULL,
    draft_id bigint NOT NULL,
    resource_version bigint NOT NULL,
    candidate_record_id bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 255),
    approval_status varchar(16) NOT NULL CHECK (approval_status IN ('pending','approved','rejected')),
    reviewer_user_id bigint REFERENCES users(id) ON DELETE RESTRICT,
    reviewed_at timestamptz,
    review_note text NOT NULL DEFAULT '' CHECK (octet_length(review_note) <= 8000),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (revision_id, draft_id, resource_version)
        REFERENCES monitor_intent_draft_revisions(id, draft_id, resource_version) ON DELETE RESTRICT,
    FOREIGN KEY (candidate_record_id, draft_id)
        REFERENCES monitor_intent_expansion_candidates(id, draft_id) ON DELETE RESTRICT,
    CHECK (
        approval_status = 'pending' AND reviewer_user_id IS NULL AND reviewed_at IS NULL AND review_note = ''
        OR approval_status IN ('approved','rejected') AND reviewer_user_id IS NOT NULL AND reviewed_at IS NOT NULL
    ),
    UNIQUE (revision_id, ordinal),
    UNIQUE (revision_id, candidate_record_id)
);

CREATE TABLE IF NOT EXISTS monitor_intent_preview_results (
    run_id bigint PRIMARY KEY REFERENCES monitor_intent_analysis_runs(id) ON DELETE RESTRICT,
    estimated_alert_count integer NOT NULL CHECK (estimated_alert_count >= 0),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS monitor_intent_preview_samples (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id bigint NOT NULL REFERENCES monitor_intent_preview_results(run_id) ON DELETE RESTRICT,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 199),
    document_version_id bigint NOT NULL REFERENCES document_versions(id) ON DELETE RESTRICT,
    title text NOT NULL CHECK (octet_length(title) >= 1 AND octet_length(title) <= 2000),
    decision varchar(16) NOT NULL CHECK (decision IN ('accepted','review','rejected')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (run_id, ordinal),
    UNIQUE (id, run_id)
);

CREATE TABLE IF NOT EXISTS monitor_intent_preview_recall_signals (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sample_id bigint NOT NULL,
    run_id bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 255),
    channel varchar(64) NOT NULL CHECK (octet_length(channel) >= 1 AND octet_length(channel) <= 64),
    rank integer NOT NULL CHECK (rank > 0),
    score numeric(20,10) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (sample_id, run_id) REFERENCES monitor_intent_preview_samples(id, run_id) ON DELETE RESTRICT,
    UNIQUE (sample_id, ordinal)
);
ALTER TABLE monitor_intent_preview_recall_signals
    DROP CONSTRAINT IF EXISTS monitor_intent_preview_recall_signals_score_check;
ALTER TABLE monitor_intent_preview_recall_signals
    ALTER COLUMN score TYPE numeric(20,10) USING round(score::numeric, 10);

CREATE TABLE IF NOT EXISTS monitor_intent_preview_reasons (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sample_id bigint NOT NULL,
    run_id bigint NOT NULL,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 511),
    reason_type varchar(16) NOT NULL CHECK (reason_type IN ('match','exclusion')),
    reason text NOT NULL CHECK (octet_length(reason) >= 1 AND octet_length(reason) <= 4000),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (sample_id, run_id) REFERENCES monitor_intent_preview_samples(id, run_id) ON DELETE RESTRICT,
    UNIQUE (sample_id, reason_type, ordinal)
);

CREATE TABLE IF NOT EXISTS monitor_intent_preview_warnings (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id bigint NOT NULL REFERENCES monitor_intent_preview_results(run_id) ON DELETE RESTRICT,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 255),
    warning text NOT NULL CHECK (octet_length(warning) >= 1 AND octet_length(warning) <= 4000),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (run_id, ordinal)
);

CREATE OR REPLACE FUNCTION enforce_monitor_intent_draft_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    config_state text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_intent_drafts_retained',
            MESSAGE = 'monitor intent drafts are retained';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.id IS DISTINCT FROM OLD.id OR NEW.monitor_id IS DISTINCT FROM OLD.monitor_id
        OR NEW.config_version_id IS DISTINCT FROM OLD.config_version_id
        OR NEW.created_at IS DISTINCT FROM OLD.created_at
        OR NEW.resource_version <> OLD.resource_version + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_intent_drafts_identity_immutable',
            MESSAGE = 'monitor intent draft identity is immutable and its resource version advances by one';
    END IF;
    SELECT state INTO config_state FROM monitor_config_versions
    WHERE id = NEW.config_version_id AND monitor_id = NEW.monitor_id FOR KEY SHARE;
    IF config_state IS DISTINCT FROM 'draft' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_intent_drafts_config_mutable',
            MESSAGE = 'monitor intent may only change while its configuration is a draft';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS monitor_intent_drafts_lifecycle ON monitor_intent_drafts;
CREATE TRIGGER monitor_intent_drafts_lifecycle
BEFORE INSERT OR UPDATE OR DELETE ON monitor_intent_drafts
FOR EACH ROW EXECUTE FUNCTION enforce_monitor_intent_draft_lifecycle();

CREATE OR REPLACE FUNCTION enforce_monitor_intent_append_only()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'monitor_intent_facts_append_only',
        MESSAGE = 'monitor intent historical facts are append-only';
END;
$$;

DROP TRIGGER IF EXISTS monitor_intent_draft_revisions_append_only ON monitor_intent_draft_revisions;
CREATE TRIGGER monitor_intent_draft_revisions_append_only BEFORE UPDATE OR DELETE ON monitor_intent_draft_revisions
FOR EACH ROW EXECUTE FUNCTION enforce_monitor_intent_append_only();
DROP TRIGGER IF EXISTS monitor_intent_clauses_append_only ON monitor_intent_clauses;
CREATE TRIGGER monitor_intent_clauses_append_only BEFORE UPDATE OR DELETE ON monitor_intent_clauses
